export const LONG = {"yahayyu":{"src":"tirmidhi 3524","w":["عَنْ","أَنَسِ","بْنِ","مَالِكٍ،","قَالَ","كَانَ","النَّبِيُّ","صلى","الله","عليه","وسلم","إِذَا","كَرَبَهُ","أَمْرٌ","قَالَ","يَا","حَىُّ","يَا","قَيُّومُ","بِرَحْمَتِكَ","أَسْتَغِيثُ.","وَبِإِسْنَادِهِ","قَالَ","قَالَ","رَسُولُ","اللَّهِ","صلى","الله","عليه","وسلم","أَلِظُّوا","بِيَا","ذَا","الْجَلاَلِ","وَالإِكْرَامِ."],"p":[[0,12],[12,21],[21,35]],"m":{"en":["Anas bin Malik said:“Whenever a matter would distress him, the Prophet (ﷺ) would say: ‘O Living,","O Self-Sustaining Sustainer! In Your Mercy do I seek relief (Yā Ḥayyu yā Qayyūm,","bi-raḥmatika astaghīth).’” And with this chain, that he said: “The Messenger of Allah (ﷺ) said: ‘Be constant with: “O Possessor of Majesty and Honor (Yā Dhal-Jalāli wal-Ikrām).’”"],"tr":["Enes b. Mâlik (r.a.)’den rivâyete göre, şöyle demiştir: Herhangi bir iş Rasûlullah (s.a.v.)’e sıkıntı verdiği zaman şöyle duâ ederdi:","","“Ey devamlı din olan ölümsüz bütün varlıkların tek yöneteni ve gözeteni senin rahmetinle yardım isterim.” Aynı senedle Enes dedi ki: Rasûlullah (s.a.v.) şöyle buyurdu: “Ya zelcelali velikram” duâsına devam ediniz.”"],"ur":["","انس بن مالک رضی الله عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کو جب کوئی کام سخت تکلیف و پریشانی میں ڈال دیتا تو آپ یہ دعا پڑھتے:","«يا حي يا قيوم برحمتك أستغيث» ”اے زندہ اور ہمیشہ رہنے والے! تیری رحمت کے وسیلے سے تیری مدد چاہتا ہوں“۔"],"id":["Telah menceritakan kepada kami [Muhammad bin Hatim Al Muktib] telah menceritakan kepada kami [Abu Badr Syuja' bin Al Walid] dari [Ar Ruhail bin Mu'awiyah] saudara Zuhair bin Mu'awiyah,","dari [Ar Raqasyi] dari [Anas bin Malik] ia berkata;","Nabi shallallahu 'alaihi wasallam apabila mengalami kesusahan beliau berdoa: \"YAA HAYYU, YAA QAYYUUM, BIRAHMATIKA ASTAGHIITSU.\" (Wahai Dzat yang Maha hidup, Wahai Dzat yang terus menerus mengurus makhluk-Nya, dengan rahmat-Mu aku meminta pertolongan)"],"bn":["। আনাস ইবনু মালিক (রাযিঃ) হতে বর্ণিত আছে, তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর সম্মুখে কঠিন কাজ হাযির হলে তিনি বলতেনঃ “হে চিরজীবি,","হে চিরস্থায়ী! আমি তোমার রহমতের ওয়াসীলায় সাহায্য প্রার্থনা করি”। হাসানঃ আল-কালিমুত তাইয়্যিব (হাঃ ১১৮/৭৬)। একই সনদসূত্রে আনাস (রাযিঃ) বলেন,","রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ তোমরা সবসময় “ইয়া যাল-জালালি ওয়াল-ইকরাম\" পাঠ করাকে অপরিহার্য করে নাও। সহীহঃ সহীহাহ (হাঃ ১৫৩৬)। আবূ ঈসা বলেন, এ হাদীসটি গারীব। এ হাদীস আনাস (রাযিঃ) হতে একাধিক সূত্রে বর্ণিত হয়েছে।"]}},"d_help":{"src":"abudawud 1522","w":["عَنْ","مُعَاذِ","بْنِ","جَبَلٍ،","أَنَّ","رَسُولَ","اللَّهِ","صلى","الله","عليه","وسلم","أَخَذَ","بِيَدِهِ","وَقَالَ","يَا","مُعَاذُ","وَاللَّهِ","إِنِّي","لأُحِبُّكَ","وَاللَّهِ","إِنِّي","لأُحِبُّكَ.","فَقَالَ","أُوصِيكَ","يَا","مُعَاذُ","لاَ","تَدَعَنَّ","فِي","دُبُرِ","كُلِّ","صَلاَةٍ","تَقُولُ","اللَّهُمَّ","أَعِنِّي","عَلَى","ذِكْرِكَ","وَشُكْرِكَ","وَحُسْنِ","عِبَادَتِكَ.","وَأَوْصَى","بِذَلِكَ","مُعَاذٌ","الصُّنَابِحِيَّ","وَأَوْصَى","بِهِ","الصُّنَابِحِيُّ","أَبَا","عَبْدِ","الرَّحْمَنِ."],"p":[[0,12],[12,22],[22,34],[34,40],[40,50]],"m":{"en":["Mu'adh b. Jabal reported that the Messenger of Allah (ﷺ) caught his hand and said:By Allah,","I love you, Mu'adh. I give some instruction to you.","Never leave to recite this supplication after every (prescribed) prayer: \"O Allah, help me in remembering You,","in giving You thanks,","and worshipping You well.\" Mu'adh willed this supplication to the narrator al-Sunabihi and al-Sunabihi to 'Abu Abd al-Rahman"],"fr":["Mu’adh b. Jabal a rapporté que le Messager d’Allah ﷺ a pris sa main et a dit :","« Par Allah, je t’aime, Mu’adh. Je vais te donner un conseil.","N’oublie jamais de réciter cette invocation après chaque prière prescrite : “Ô Allah, aide-moi à me souvenir de Toi,","","à Te remercier et à T’adorer de la meilleure façon.” » Mu’adh a transmis cette invocation au narrateur al-Sunabihi, et al-Sunabihi à Abu Abd al-Rahman"],"tr":["Muaz b. Cebel (r.a.)'den rivayet edildiğine göre, Resulullah (s.a.v.) onun elini tutup:","\"Ya Muaz! Vallahi seni seviyorum. Sana bir şeyler tavsiye edeyim, onları her (farz) namazın sonunda oku,","kat'iyyen terk etme\": \"Allah'ım! Seni zikretmekte, sana şükretmekte ve sana güzelce ibâdet etmekte bana yardım et\" dersin\" buyurdu.","Ahmed b. Hanbel, V, 245; İbn Hıbban, Sahih,","III, 234; Hakim el-Müstedrek I, 273. Muaz (r.a.) bu duayı, (râvi) es-Sunabihî'ye, o da (râvi) Ebu Abdurrahman 'a tavsiye etti"],"ur":["معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے میرا ہاتھ پکڑا اور فرمایا:","اے معاذ! قسم اللہ کی، میں تم سے محبت کرتا ہوں، قسم اللہ کی میں تم سے محبت کرتا ہوں ،","پھر فرمایا: اے معاذ! میں تمہیں نصیحت کرتا ہوں: ہر نماز کے بعد یہ دعا پڑھنا کبھی نہ چھوڑنا:","«اللهم أعني على ذكرك وشكرك وحسن عبادتك» اے اللہ! اپنے ذکر،","شکر اور اپنی بہترین عبادت کے سلسلہ میں میری مدد فرما ۔ معاذ رضی اللہ عنہ نے صنابحی کو اور صنابحی نے ابوعبدالرحمٰن کو اس کی وصیت کی۔"],"id":["Telah menceritakan kepada Kami ['Ubaidullah bin Umar bin Maisarah] telah menceritakan kepada Kami [Abdullah bin Yazid Al Muqri`],","telah menceritakan kepada Kami [Haiwah bin Syuraih], ia berkata; aku mendengar ['Uqbah bin Muslim] berkata; telah menceritakan kepadaku [Abu Abdurrahman Al Hubuli] dari [Ash Shunabihi] dari [Mu'adz bin Jabal] bahwa Rasulullah shallAllahu wa'alaihi wa sallam menggandeng tangannya dan berkata:","\"Wahai Mu'adz, demi Allah, aku mencintaimu.\" Kemudian beliau berkata: \"Aku wasiatkan kepadamu wahai Mu'adz,","janganlah engkau tinggalkan setiap selesai shalat untuk mengucapkan, \"ALLAAHUMMA A'INNII 'ALAA DZIKRIKA WA SYUKRIKA WA HUSNI 'IBAADATIK\" (Ya Allah,","bantulah aku untuk berdzikir dan bersyukur kepadaMu serta beribadah kepadaMu dengan baik.) Mu'adz mewasiatkan dengan hal tersebut kepada Ash Shunabihi dan Ash Shunabihi mewasiatkan hal tersebut kepada Abdurrahman"],"bn":["। মু‘আয ইবনু জাবাল (রাঃ) সূত্রে বর্ণিত। একদা রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার হাত ধরে বললেন,","হে মু‘আয! আল্লাহর শপথ! আমি অবশ্যই তোমাকে ভালবাসি, আল্লাহর শপথ! আমি অবশ্যই তোমাকে ভালবাসি। তিনি বললেন, হে মু‘আয!","আমি তোমাকে ওয়াসিয়াত করছি, তুমি প্রত্যেক সালাতের পর এ দু‘আটি কখনো পরিহার করবে নাঃ ‘‘আল্লাহুম্মা আঈন্নী ‘আলা যিকরিকা ওয়া শুকরিকা ওয়া হুসনি ‘ইবাদাতিকা’’ (অর্থঃ হে আল্লাহ!","আপনার স্মরণে,","আপনার কৃতজ্ঞতা প্রকাশে এবং আপনার উত্তম ‘ইবাদাতে আমাকে সাহায্য করুন)। অতঃপর মু‘আয (রাঃ) আস-সুনাবিহী (রহঃ)-কে এবং আস-সুনাবিহী ‘আবদুর রহমানকে এরূপ দু‘আ করার ওয়াসিয়াত করেন।[1] সহীহ।"],"ru":["Передаётся от Му‘аза ибн Джабаля, да будет доволен им Аллах, что однажды Посланник Аллаха ﷺ взял его за руку и сказал:","«О Му‘аз, клянусь Аллахом, поистине, я люблю тебя, клянусь Аллахом, поистине, я люблю тебя».","А потом он сказал: «Наказываю тебе, о Му‘аз, ни в коем случае не забывай в конце каждой молитвы говорить: “О Аллах,","помоги мне поминать Тебя, и благодарить Тебя, и должным образом поклоняться Тебе /Аллахумма,","а‘инни ‘аля зикри-ка, ва шукри-ка ва хусни ‘ибадати-ка/”». Му‘аз завещал это ас-Сунабихи, а ас-Сунабихи завещал это Абу ‘Абдуррахману"]}},"d_steady":{"src":"tirmidhi 2140","w":["عَنْ","أَنَسٍ،","قَالَ","كَانَ","رَسُولُ","اللَّهِ","صلى","الله","عليه","وسلم","يُكْثِرُ","أَنْ","يَقُولَ","يَا","مُقَلِّبَ","الْقُلُوبِ","ثَبِّتْ","قَلْبِي","عَلَى","دِينِكَ.","فَقُلْتُ","يَا","رَسُولَ","اللَّهِ","آمَنَّا","بِكَ","وَبِمَا","جِئْتَ","بِهِ","فَهَلْ","تَخَافُ","عَلَيْنَا","قَالَ","نَعَمْ","إِنَّ","الْقُلُوبَ","بَيْنَ","أَصْبُعَيْنِ","مِنْ","أَصَابِعِ","اللَّهِ","يُقَلِّبُهَا","كَيْفَ","يَشَاءُ."],"p":[[0,12],[12,20],[20,32],[32,44]],"m":{"en":["Anas narrated:\"The Messenger of Allah (s.a.w) would often say: Ya Muqallibal-qulub,","thabbit qalbi 'ala dinik('O Changer of the Hearts!","Strengthen my heart upon Your Religion.)' So I said: 'O Prophet of Allah! We believe in you and what you have come with,","but do you fear for us?' He said: 'Yes. Indeed the hearts are between two Fingers of Allah's Fingers, He changes them as He wills"],"tr":["Enes (radıyallahü anh)’den rivâyete göre, şöyle demiştir: Rasûlüllah (sallallahü aleyhi ve sellem), sık sık “Ey kalpleri halden hale değiştiren Allah’ım kalbimi dinin üzere sabit kıl demeyi çokça yapardı.","Ey Allah’ın Rasûlü dedim sana ve getirdiğin şeriata inandık bu durumda hala bizim hakkımızda korkuyor musun?","Rasûlüllah (sallallahü aleyhi ve sellem) buyurdu ki: Evet çünkü kalpler Allah’ın iki parmağı arasındadır, onları dilediği şekilde evirip çevirir.” (Müslim, Kader: 3) Bu konuda Nevvâs b. Sem’an, Ümmü Seleme, Abdullah b. Amr ve Âişe’den de hadis rivâyet edilmiştir.","Bu hadis hasendir. Aynı şekilde pek çok kişi bu hadisi böylece Â’meş’den, Ebû Sûfyân’dan ve Enes’den rivâyet etmişlerdir. Bazıları da Â’meş’den, Ebû Sûfyân’dan, Câbir’den rivâyet etmişlerdir. Ebû Sûfyân’ın Enes’den rivâyeti daha sahihtir"],"ur":["انس رضی الله عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اکثر یہ دعا پڑھتے تھے «يا مقلب القلوب ثبت قلبي على دينك» ”اے دلوں کے الٹنے پلٹنے والے میرے دل کو اپنے دین پر ثابت رکھ“،","میں نے عرض کیا: اللہ کے رسول! ہم لوگ آپ پر اور آپ کی لائی ہوئی شریعت پر ایمان لے آئے کیا آپ کو ہمارے سلسلے میں اندیشہ رہتا ہے؟ آپ نے فرمایا: ”ہاں،","لوگوں کے دل اللہ کی انگلیوں میں سے دو انگلیوں کے درمیان ہیں جیسا چاہتا ہے انہیں الٹتا پلٹتا رہتا ہے“۔ امام ترمذی کہتے ہیں: ۱- یہ حدیث حسن ہے،","۲- کئی لوگوں نے اسی طرح «عن الأعمش عن أبي سفيان عن أنس» کی سند سے روایت کی ہے۔ بعض لوگوں نے «عن الأعمش عن أبي سفيان عن جابر عن النبي صلى الله عليه وسلم» کی سند سے روایت کی ہے، لیکن ابوسفیان کی حدیث جو انس سے مروی ہے زیادہ صحیح ہے، ۳- اس باب میں نواس بن سمعان، ام سلمہ، عبداللہ بن عمرو اور عائشہ رضی الله عنہم سے بھی احادیث آئی ہیں۔"],"id":["Telah menceritakan kepada kami [Hannad]; telah menceritakan kepada kami [Abu Mu'awiyah] dari [Al A'masy] dari [Abu Sufyan] dari [Anas] dia berkata;","adalah Rasulullah shallallahu 'alaihi wasallam terbiasa membaca do'a \"YA MUQALLIBAL QULUUB TSABBIT QALBII 'ALAA DIINIKA (wahai Dzat yang membolak balikkan hati teguhkanlah hatiku berada di atas agamamu).\" Kemudian aku pun bertanya, \"Wahai Rasulullah, kami beriman kepadamu dan kepada apa yang Anda bawa.","Lalu apakah Anda masih khawatir kepada kami?\" beliau menjawab: \"Ya, karena sesungguhnya hati manusia berada di antara dua genggaman tangan Allah yang Dia bolak-balikkan menurut yang dikehendaki-Nya.\" Abu Isa berkata; Hadits semakna juga diriwayatkan dari An Nawwas bin Sam'an,","Ummu Salamah, Abdullah bin Amr dan A'isyah. Dan ini adalah hadits Hasan, demikianlah kebanyakan telah meriwayatkannya dari Al A'masy dari Abu Sufyan dari Anas, dan sebagian yang lainnya telah meriwayatkannya dari [Al A'masy] dari [Abu Sufyan] dari [Jabir] dari Nabi shallallahu 'alaihi wasallam, namun hadits Abu Sufyan dari Anas lebih shahih"],"bn":["। আনাস (রাঃ) হতে বর্ণিত আছে, তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এই দু’আ অধিক পাঠ করতেনঃ হে অন্তরসমূহের পরিবর্তনকারী! আমার অন্তরকে তোমার দ্বীনের উপর প্রতিষ্ঠিত (দৃঢ়) রাখো। আমি বললাম,","হে আল্লাহর রাসূল (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম)। আমরা ঈমান এনেছি আপনার উপর এবং আপনি যা নিয়ে এসেছেন তার উপর। আপনি আমাদের ব্যাপারে কি কোনরকম আশংকা করেন? তিনি বললেনঃ হ্যাঁ, কেননা,","আল্লাহ তা'আলার আঙ্গুলসমূহের মধ্যকার দুটি আঙ্গুলের মাঝে সমস্ত অন্তরই অবস্থিত। তিনি যেভাবে ইচ্ছা তা পরিবর্তন করেন। সহীহ, ইবনু মা-জাহ (৩৮৩৪)। আবূ ঈসা বলেন, নাওয়াস ইবনু সাম্আন, উম্মু সালামা, আব্দুল্লাহ ইবনু আমর ও আইশা (রাঃ) হতেও এ অনুচ্ছেদে হাদীস বর্ণিত আছে। এ হাদীসটি হাসান। আমাশ-আবৃ সুফিয়ান হতে,","তিনি আনাস (রাঃ)-এর সূত্রে একাধিক বর্ণনাকারী একইরকম হাদীস বর্ণনা করেছেন। কেউ কেউ আমাশ-আবৃ সুফিয়ান হতে, তিনি জাবির (রাঃ) হতে, তিনি রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হতে অনুরূপ হাদীস বর্ণনা করেছেন। আনাস (রাঃ)-এর সূত্রে আবূ সুফিয়ানের বর্ণিত হাদীসটি অনেক বেশি সহীহ।"]}},"m_home":{"src":"bukhari 5363","w":["كَانَ","النَّبِيُّ","صلى","الله","عليه","وسلم","يَصْنَعُ","فِي","الْبَيْتِ","قَالَتْ","كَانَ","فِي","مِهْنَةِ","أَهْلِهِ،","فَإِذَا","سَمِعَ","الأَذَانَ","خَرَجَ."],"p":[[0,12],[12,18]],"m":{"en":["Narrated Al-Aswad bin Yazid:I asked `Aisha \"What did the Prophet (ﷺ) use to do at home?\" She said, \"He used to work for his family,","and when he heard the Adhan (call for the prayer), he would go out"],"fr":["Rapporté par Al-Aswad bin Yazid : J’ai demandé à `Aisha : « Que faisait le Prophète (ﷺ) chez lui ? » Elle a répondu :","« Il aidait sa famille, et quand il entendait l’Adhan (l’appel à la prière), il sortait. »"],"tr":["Esved b. Yezid'den, dedi ki: \"Aişe r.anha'ya: Nebi Sallallahu Aleyhi ve Sellem evde ne yapardı, diye sordum. O: Kendi ev halkının hizmetinde bulunurdu. Ezan okunduğunu işitince de çıkardı, dedi.\" Fethu'l-Bari Açıklaması:","\"Kişinin ailesi arasında\" bizzat \"hizmet etmesi.\" Bu hadisin geri kalan bölümü ile birlikte yeterli açıklaması Namaz bölümünün CemaatIe namaz kılmanın fazileti başlıklarında (676 nolu hadiste) geçmiş bulunmaktadır"],"ur":["ہم سے محمد بن عرعرہ نے بیان کیا، کہا ہم سے شعبہ نے بیان کیا، ان سے حکم بن عتبہ نے، ان سے ابراہیم نے، ان سے اسود بن یزید نے کہ میں نے عائشہ رضی اللہ عنہا سے پوچھا کہ گھر میں نبی کریم صلی اللہ علیہ وسلم کیا کیا کرتے تھے؟ ام المؤمنین رضی اللہ عنہا نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم گھر کے کام کیا کرتے تھے،","پھر آپ جب اذان کی آواز سنتے تو باہر چلے جاتے تھے۔"],"id":["Telah menceritakan kepada kami [Muhammad bin 'Ar'arah] Telah menceritakan kepada kami [Syu'bah] dari [Al Hakam bin Utbah] dari [Ibrahim] dari [Al Aswad bin Yazid] ia berkata; Aku bertanya kepada [Aisyah] radliallahu 'anha mengenai apa saja yang dilakukan Nabi shallallahu 'alaihi wasallam di rumah.","Maka ia pun menjawab, \"Beliau turut membantu pekerjaan keluarganya, dan bila beliau mendengar adzan, beliau pun keluar"],"bn":["আসওয়াদ ইবনু ইয়াযীদ (রহ.) হতে বর্ণিত। তিনি বলেনঃ আমি ‘আয়িশাহ (রাঃ)-কে জিজ্ঞেস করলাম, নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম গৃহে কি কাজ করতেন?","তিনি বললেনঃ তিনি ঘরের কাজ-কর্মে ব্যস্ত থাকতেন, যখন আযান শুনতেন, তখন বেরিয়ে পড়তেন। [1][৬৭৬] (আধুনিক প্রকাশনী- ৪৯৬৩, ইসলামিক ফাউন্ডেশন)"],"ru":["Сообщается, что аль-Асвад ибн Язид сказал: «(Однажды) я спросил ‘Аишу, да будет доволен ею Аллах: “Чем занимался Пророк ﷺ у себя дома?” Она ответила:","“Он помогал (какой-нибудь из) своих жён в работе по дому, а услышав призыв на молитву, отправлялся (совершать её)”»"]}},"m_smile":{"src":"tirmidhi 1956","w":["عَنْ","أَبِي","ذَرٍّ،","قَالَ","قَالَ","رَسُولُ","اللَّهِ","صلى","الله","عليه","وسلم","تَبَسُّمُكَ","فِي","وَجْهِ","أَخِيكَ","لَكَ","صَدَقَةٌ","وَأَمْرُكَ","بِالْمَعْرُوفِ","وَنَهْيُكَ","عَنِ","الْمُنْكَرِ","صَدَقَةٌ","وَإِرْشَادُكَ","الرَّجُلَ","فِي","أَرْضِ","الضَّلاَلِ","لَكَ","صَدَقَةٌ","وَبَصَرُكَ","لِلرَّجُلِ","الرَّدِيءِ","الْبَصَرِ","لَكَ","صَدَقَةٌ","وَإِمَاطَتُكَ","الْحَجَرَ","وَالشَّوْكَةَ","وَالْعَظْمَ","عَنِ","الطَّرِيقِ","لَكَ","صَدَقَةٌ","وَإِفْرَاغُكَ","مِنْ","دَلْوِكَ","فِي","دَلْوِ","أَخِيكَ","لَكَ","صَدَقَةٌ."],"p":[[0,12],[12,24],[24,36],[36,48],[48,52]],"m":{"en":["Abu Dharr narrated that the Messenger of Allah said :\"Your smiling in the face of your brother is charity,","commanding good and forbidding evil is charity, your giving directions to a man lost in the land is charity for you.","Your seeing for a man with bad sight is a charity for you, your removal of a rock,","a thorn or a bone from the road is charity for you. Your pouring what remains from your bucket into the bucket of your brother is charity for you",""],"tr":["Ebû Zerr (r.a.)’den rivâyete göre, şöyle demiştir: Rasûlullah (s.a.v.) şöyle buyurdu: “Kardeşinizin yüzüne gülmeniz size sadaka sevâbı kazandırır.","İyi şeyleri emredip kötülüklerden sakındırmak sadaka sevabı kazandırır. Yabancısı bulunduğu bir bölgedeki kimseye yol gösterip yardımcı olmak sadaka sevâbı kazandırır. Gözünden rahatsız olan bir kimseye yardımcı olmanız sizin için yine sadaka sevâbı kazandırır.","Yollardan insanların gelip geçmesine engel olabilecek taş, kemik, diken gibi şeyleri kaldırmak ta yine sadaka sevâbı kazandırır.","Kendi kabından ihtiyacı olan bir kimsenin kabına bir şeyler boşaltıvermekte yine sadaka sevâbı kazandırır.” Tirmizî rivâyet etmiştir. Tirmizî: Bu Konuda İbn Mes’ûd, Câbir, Huzeyfe, Âişe ve Ebû Hüreyre’den de hadis rivâyet edilmiştir. Tirmizî: Bu hadis hasen garibtir.","Ebû Zümeyl’in ismi Simâk b. Velîd el Hanefî’dir"],"ur":["ابوذر رضی الله عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اپنے بھائی کے سامنے تمہارا مسکرانا تمہارے لیے صدقہ ہے،","تمہارا بھلائی کا حکم دینا اور برائی سے روکنا صدقہ ہے، بھٹک جانے والی جگہ میں کسی آدمی کو تمہارا راستہ دکھانا تمہارے لیے صدقہ ہے،","نابینا اور کم دیکھنے والے آدمی کو راستہ دکھانا تمہارے لیے صدقہ ہے، پتھر، کانٹا اور ہڈی کو راستے سے ہٹانا تمہارے لیے صدقہ ہے،","اپنے ڈول سے اپنے بھائی کے ڈول میں تمہارا پانی ڈالنا تمہارے لیے صدقہ ہے“ ۱؎۔ امام ترمذی کہتے ہیں: ۱- یہ حدیث حسن غریب ہے، ۲- اس باب میں ابن مسعود، جابر، حذیفہ،","عائشہ اور ابوہریرہ رضی الله عنہم سے احادیث آئی ہیں۔"],"id":["Telah menceritakan kepada kami [Abbas bin Abdul Azhim Al Anbari], telah menceritakan kepada kami [An Nadlr bin Muhammad Al Jurasyi Al Yamami],","telah menceritakan kepada kami [Ikrimah bin Ammar], telah menceritakan kepada kami [Abu Zuamail] dari [Malik bin Martsad] dari [bapaknya] dari [Abu Dzarr] ia berkata; Rasulullah shallallahu 'alaihi wasallam bersabda: \"Senyummu kepada saudaramu merupakan sedekah,","engkau berbuat ma'ruf dan melarang dari kemungkaran juga sedekah, engkau menunjukkan jalan kepada orang yang tersesat juga sedekah, engkau menuntun orang yang berpenglihatan kabur juga sedekah, menyingkirkan batu,","duri dan tulang dari jalan merupakan sedekah, dan engkau menuangkan air dari embermu ke ember saudaramu juga sedekah.\" Hadits semakna diriwayatkan dari Ibnu Mas'ud, Jabir, Hudzaifah, 'Aisyah dan Abu Hurairah. Berkata Abu 'Isa:","Ini merupakan hadits hasan gharib dan Abu Zumail bernama Simak bin Walid Al Hanafi"],"bn":["। আবূ যার (রাঃ) হতে বর্ণিত আছে, তিনি বলেন,","রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ তোমার হাস্যোজ্জ্বল মুখ নিয়ে তোমার ভাইয়ের সামনে উপস্থিত হওয়া তোমার জন্য সাদকাস্বরূপ। তোমার সৎকাজের আদেশ এবং তোমার অসৎকাজ হতে বিরত থাকার নির্দেশ তোমার জন্য সাদকাস্বরূপ। পথহারা লোককে পথের সন্ধান দেয়া তোমার জন্য সাদকাস্বরূপ,","স্বল্প দৃষ্টি সম্পন্ন লোককে সঠিক দৃষ্টি দেয়া তোমার জন্য সাদকাস্বরূপ। পথ হতে পাথর, কাটা ও হাড় সরানো তোমার জন্য সাদকাস্বরূপ। তোমার বালতি দিয়ে পানি তুলে তোমার ভাইয়ের বালতিতে ঢেলে দেয়া তোমার জন্য সাদকাস্বরূপ। সহীহ,","সহীহাহ (৫৭২)। ইবনু মাসউদ, জাবির, হুযাইফা, আইশা ও আবূ হুরাইরা (রাঃ) হতেও এ অনুচ্ছেদে হাদীস বর্ণিত আছে। আবূ ঈসা বলেন, এ হাদীসটি হাসান গারীব। আবূ যুমাইলের নাম সিমাক,","পিতা আল-ওয়ালীদ আল-হানাফী।"]}},"m_brother":{"src":"bukhari 13","w":["عَنْ","أَنَسٍ،","عَنِ","النَّبِيِّ","صلى","الله","عليه","وسلم","قَالَ","لا","يُؤْمِنُ","أَحَدُكُمْ","حَتَّى","يُحِبَّ","لأَخِيهِ","مَا","يُحِبُّ","لِنَفْسِهِ."],"p":[[0,12],[12,18]],"m":{"en":["Narrated Anas: The Prophet (ﷺ) said,","\"None of you will have faith till he wishes for his (Muslim) brother what he likes for himself"],"fr":["Rapporté par Anas : Le Prophète (ﷺ) a dit :","Aucun de vous n'aura vraiment la foi tant qu'il n'aimera pas pour son frère (musulman) ce qu'il aime pour lui-même"],"tr":["Enes'ten rivayet edilmiştir: Nebi (Sallallahu aleyhi ve Sellem) şöyle buyurmuştur:","Hiçbiriniz kendisi için sevdiğini (istediğini) (Müslüman) kardeşi için de sevmedikçe iman etmiş olamaz"],"ur":["ہم سے حدیث بیان کی مسدد نے، ان کو یحییٰ نے، انہوں نے شعبہ سے نقل کیا، انہوں نے قتادہ سے، انہوں نے انس رضی اللہ عنہ خادم رسول اللہ صلی اللہ علیہ وسلم سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا۔ اور شعبہ نے حسین معلم سے بھی روایت کیا، انہوں نے قتادہ سے، انہوں نے انس رضی اللہ عنہ سے،","انہوں نے نبی کریم صلی اللہ علیہ وسلم سے نقل فرمایا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا تم میں سے کوئی شخص ایماندار نہ ہو گا جب تک اپنے بھائی کے لیے وہ نہ چاہے جو اپنے نفس کے لیے چاہتا ہے۔"],"id":["Telah menceritakan kepada kami [Musaddad] berkata, telah menceritakan kepada kami [Yahya] dari [Syu'bah] dari [Qotadah] dari [Anas] dari Nabi shallallahu 'alaihi wasallam Dan dari [Husain Al Mu'alim] berkata, telah menceritakan kepada kami [Qotadah] dari [Anas] dari Nabi shallallahu 'alaihi wasallam,","beliau bersabda: \"Tidaklah beriman seseorang dari kalian sehingga dia mencintai untuk saudaranya sebagaimana dia mencintai untuk dirinya sendiri"],"bn":["আনাস (রাযি.) হতে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ তোমাদের কেউ প্রকৃত মু‘মিন হতে পারবে না, যতক্ষণ না সে তার ভাইয়ের জন্য সেটাই পছন্দ করবে,","যা তার নিজের জন্য পছন্দ করে। (মুসলিম ১/১৭ হাঃ ৪৫, আহমাদ ১২৮০১, ১৩৮৭৫) (আধুনিক প্রকাশনীঃ ১২, ইসলামিক ফাউন্ডেশনঃ)"],"ru":["Нам рассказал Мусаддад, сказавший: Нам рассказал Яхья, от Шу‘бы, от Катады, от Анаса, да будет доволен им Аллах, от Пророка ﷺ о том что он сказал:","«Не уверует никто из вас до тех пор, пока не станет желать своему брату (в Исламе) того же, чего желает самому себе»"]}},"m_tongue":{"src":"bukhari 10","w":["عَنِ","النَّبِيِّ","صلى","الله","عليه","وسلم","قَالَ","الْمُسْلِمُ","مَنْ","سَلِمَ","الْمُسْلِمُونَ","مِنْ","لِسَانِهِ","وَيَدِهِ،","وَالْمُهَاجِرُ","مَنْ","هَجَرَ","مَا","نَهَى","اللَّهُ","عَنْهُ."],"p":[[0,12],[12,21]],"m":{"en":["Narrated 'Abdullah bin 'Amr: The Prophet (ﷺ) said, \"A Muslim is the one who avoids harming Muslims with his tongue and hands.","And a Muhajir (emigrant) is the one who gives up (abandons) all what Allah has forbidden"],"fr":["Rapporté par 'Abdullah bin 'Amr : Le Prophète (ﷺ) a dit : Un musulman est celui qui ne fait de mal à aucun autre musulman,","ni par ses paroles ni par ses actes. Et un Muhajir (émigrant) est celui qui abandonne tout ce qu'Allah a interdit"],"tr":["Abdullah bin Amr bin As r.a. Nebiyy-i Muhterem sallallahu aleyhi ve sellem buyurdu ki: Müslüman, dilinden,","elinden müslümanlar selamette kalan kimsedir. Muhacir de Allâh`ın nehyettiğini terkedendir. Tekrarı:"],"ur":["ہم سے آدم بن ابی ایاس نے یہ حدیث بیان کی، ان کو شعبہ نے وہ عبداللہ بن ابی السفر اور اسماعیل سے روایت کرتے ہیں، وہ دونوں شعبی سے نقل کرتے ہیں، انہوں نے عبداللہ بن عمرو بن عاص رضی اللہ عنہما سے، وہ نبی کریم صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا مسلمان وہ ہے جس کی زبان اور ہاتھ سے مسلمان بچے رہیں اور مہاجر وہ ہے جو ان کاموں کو چھوڑ دے جن سے اللہ نے منع فرمایا۔ ابوعبداللہ ( امام بخاری رحمہ اللہ ) نے فرمایا اور ابومعاویہ نے کہ ہم کو حدیث بیان کی داؤد بن ابی ہند نے،","انہوں نے روایت کی عامر شعبی سے، انہوں نے کہا کہ میں نے سنا عبداللہ بن عمرو بن عاص سے، وہ حدیث بیان کرتے ہیں جناب نبی کریم صلی اللہ علیہ وسلم سے ( وہی مذکورہ حدیث ) اور کہا کہ عبدالاعلیٰ نے روایت کیا داؤد سے، انہوں نے عامر سے، انہوں نے عبداللہ بن عمرو بن عاص سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے۔"],"id":["Telah menceritakan kepada kami [Adam bin Abu Iyas] berkata, Telah menceritakan kepada kami [Syu'bah] dari [Abdullah bin Abu As Safar] dan [Isma'il bin Abu Khalid] dari [Asy Sya'bi] dari [Abdullah bin 'Amru] dari Nabi shallallahu 'alaihi wasallam, bersabda: \"Seorang muslim adalah orang yang Kaum Muslimin selamat dari lisan dan tangannya, dan seorang Muhajir adalah orang yang meninggalkan apa yang dilarang oleh Allah \" Abu Abdullah berkata;","dan [Abu Mu'awiyyah] berkata; Telah menceritakan kepada kami [Daud], dia adalah anak Ibnu Hind, dari ['Amir] berkata; aku mendengar [Abdullah], maksudnya ibnu 'Amru, dari Nabi shallallahu 'alaihi wasallam Dan berkata [Abdul A'laa] dari [Daud] dari ['Amir] dari [Abdullah] dari Nabi shallallahu 'alaihi wasallam"],"bn":["‘আবদুল্লাহ ইবনু ‘আমর (রাঃ) হতে বর্ণিত। আল্লাহর রাসূল সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম ইরশাদ করেন, সে-ই মুসলিম, যার জিহবা ও হাত হতে সকল মুসলিম নিরাপদ এবং সে-ই প্রকৃত মুহাজির,","আল্লাহ যা নিষেধ করেছেন তা যে ত্যাগ করে। (৬৪৮৪; মুসলিম ১/১৪ হাঃ ৪০, আহমাদ ৬৭৬৫) (আধুনিক প্রকাশনীঃ ৯, ইসলামিক ফাউন্ডেশনঃ)"],"ru":["Нам рассказал Адам ибн Абу Ияас, сказавший: Нам рассказал Шу‘ба, от ‘Абдуллаха ибн Абу ас-Сафара и Исма‘иля ибн Абу Халида от Аш-Ша‘би, от ‘Абдуллаха ибн ‘Амра, да будет доволен Аллах ими обоими, что Пророк ﷺ сказал:","«Мусульманин — это тот, кто не причиняет (другим) мусульманам вреда своим языком и своими руками, мухаджиром же является тот, кто прекратил (совершать) запрещённое Аллахом»"]}},"m_last":{"src":"bukhari 4437","w":["كَانَ","رَسُولُ","اللَّهِ","صلى","الله","عليه","وسلم","وَهْوَ","صَحِيحٌ","يَقُولُ","إِنَّهُ","لَمْ","يُقْبَضْ","نَبِيٌّ","قَطُّ","حَتَّى","يَرَى","مَقْعَدَهُ","مِنَ","الْجَنَّةِ","ثُمَّ","يُحَيَّا","أَوْ","يُخَيَّرَ.","فَلَمَّا","اشْتَكَى","وَحَضَرَهُ","الْقَبْضُ","وَرَأْسُهُ","عَلَى","فَخِذِ","عَائِشَةَ","غُشِيَ","عَلَيْهِ،","فَلَمَّا","أَفَاقَ","شَخَصَ","بَصَرُهُ","نَحْوَ","سَقْفِ","الْبَيْتِ","ثُمَّ","قَالَ","اللَّهُمَّ","فِي","الرَّفِيقِ","الأَعْلَى.","فَقُلْتُ","إِذًا","لاَ","يُجَاوِرُنَا.","فَعَرَفْتُ","أَنَّهُ","حَدِيثُهُ","الَّذِي","كَانَ","يُحَدِّثُنَا","وَهْوَ","صَحِيحٌ."],"p":[[0,12],[12,24],[24,34],[34,46],[46,51],[51,59]],"m":{"en":["Narrated Aisha:When Allah's Apostle was in good health, he used to say,","\"Never does a prophet die unless he is shown his place in Paradise ( before his death ), and then he is made alive or given the option.\" When the Prophet became ill and his last moments came while his head was on my thigh,","he became unconscious, and when he came to his senses,","he looked towards the roof of the house and then said, \"O Allah! (Please let me be) with the highest companion.\" Thereupon I said,","","\"Hence he is not going to stay with us?\" Then I came to know that his state was the confirmation of the narration he used to mention to us while he was in good health"],"fr":["Rapporté par `Aisha : Quand le Messager d’Allah était en bonne santé, il disait :","« Aucun prophète ne meurt sans qu’on ne lui montre sa place au Paradis avant sa mort, puis il est laissé en vie ou on lui donne le choix.","» Quand le Prophète (ﷺ) tomba malade et que ses derniers instants arrivèrent, alors que sa tête reposait sur ma cuisse, il perdit connaissance.","Lorsqu’il revint à lui, il regarda vers le toit de la maison et dit : « Ô Allah ! (Permets-moi d’être) avec le plus haut compagnon.","» J’ai alors compris qu’il n’allait plus rester avec nous,","et j’ai compris que son état confirmait ce qu’il nous avait dit lorsqu’il était en bonne santé"],"tr":["Aişe dedi ki: \"Resulullah Sallallahu Aleyhi ve Sellem sağlıklı iken şöyle derdi:","Hiçbir Nebiin ruhu cennette kalacağı yeri görmedikçe kabzedilmez. Sonra serbest bırakılır -yahut muhayyer bırakılır.- Resulullah rahatsızlanıp da ruhunun kabzedileceği vakit de yaklaşınca başı Aişe'nin (benim) dizi üzerinde iken bayıldı.","Ayılmca gözleri evin tavanına doğru dikildi.","Sonra: Allah'ım er-Refiku'I-A'la arasında, dedi. Bu sefer ben: O halde bizi tercih etmeyecektir dedim ve onun sağlıklı iken bize söylediği o hadisinin gerçekleşeceğini anladım.\" Fethu'l-Bari Açıklaması:","","\"Sesi kısıldı.\" Ses kısılması boğazda arız olan birhalolup, bundan dolayı ses değişerek kalınlaşır"],"ur":["ہم سے ابوالیمان نے بیان کیا، کہا ہم کو شعیب نے خبر دی،","انہیں زہری نے کہ عروہ بن زبیر نے بیان کیا اور ان سے عائشہ رضی اللہ عنہا نے بیان کیا تندرستی کے زمانے میں رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے کہ جب بھی کسی نبی کی روح قبض کی گئی تو پہلے جنت میں اس کی قیام گاہ اسے ضرور دکھا دی گئی،","پھر اسے اختیار دیا گیا ( راوی کو شک تھا کہ لفظ «يحيا» ہے یا «يخير»،‏‏‏‏ دونوں کا مفہوم ایک ہی ہے ) پھر جب نبی کریم صلی اللہ علیہ وسلم بیمار پڑے اور وقت قریب آ گیا تو سر مبارک عائشہ رضی اللہ عنہا کی ران پر تھا اور آپ پر غشی طاری ہو گئی تھی،","","جب کچھ ہوش ہوا تو آپ کی آنکھیں گھر کی چھت کی طرف اٹھ گئیں اور آپ صلی اللہ علیہ وسلم نے فرمایا۔ «اللهم في الرفيق الأعلى» ۔ میں سمجھ گئی کہ اب نبی کریم صلی اللہ علیہ وسلم ہمیں ( یعنی دنیاوی زندگی کو ) پسند نہیں فرمائیں گے۔ مجھے وہ حدیث یاد آ گئی جو آپ صلی اللہ علیہ وسلم نے تندرستی کے زمانے میں فرمائی تھی۔",""],"id":["Telah menceritakan kepada kami [Abul Yaman] Telah mengabarkan kepada kami [Syu'aib] dari [Az Zuhri] dia berkata;","Telah mengabarkan kepadaku [Urwah bin Zubair] bahwa [Aisyah] berkata; Rasulullah shallallahu 'alaihi wasallam bersabda ketika beliau masih sehat: \"Tidaklah seorang nabi diambil nyawanya,","hingga di perlihatkan terlebih dahulu tempat duduknya di surga. Lalu di suruh memilihnya.\" Tatkala beliau sakit dan ajal menjemputnya,","yang pada waktu itu kepala beliau berada di paha Aisyah, beliau pingsan. Setelah beliau sadar, beliau mengalihkan pandangannya ke atap rumah kemudian bersabda: \"Ya Allah,","sekarang aku memilih kekasihku yang tertinggi.\" Aku berkata; 'kalau begitu beliau tidak akan bersama kita.","Maka aku pun mengerti bahwa ucapanya itu adalah perkataan yang pernah beliau sampaikan kepada kami ketika beliau masih sehat"],"bn":["‘আয়িশাহ (রাঃ) হতে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু ‘আলাইহি ওয়াসাল্লাম সুস্থাবস্থায় বলতেন,","","জান্নাতে তাঁর স্থান দেখানো ব্যতীত কোন নবী (আঃ)-এর প্রাণ কখনো কবজ করা হয়নি। তারপর তাঁকে জীবন বা মৃত্যু একটি গ্রহণ করতে বলা হয়। এরপর যখন নবী সাল্লাল্লাহু ‘আলাইহি ওয়াসাল্লাম অসুস্থ হয়ে পড়লেন এবং তাঁর মাথা ‘আয়িশাহ (রাঃ)-এর উরুতে রাখাবস্থায় তাঁর জান কবজের সময় উপস্থিত হল তখন তিনি সংজ্ঞাহীন হয়ে গেলেন। এরপর যখন তিনি সংজ্ঞা ফিরে পেলেন তখন তিনি ঘরের ছাদের দিকে তাকিয়ে বললেন,","হে আল্লাহ! উচ্চে সমাসীন বন্ধুর সঙ্গে (মিলিত হতে চাই)। অনন্তর আমি বললাম,","তিনি আর আমাদের মাঝে থাকতে চাচ্ছেন না। এরপর আমি উপলব্ধি করলাম যে,","এটা হচ্ছে ঐ কথা যা তিনি আমাদের কাছে সুস্থাবস্থায় বর্ণনা করতেন। [৪৪৩৫] (আধুনিক প্রকাশনীঃ ৪০৮৭, ইসলামিক ফাউন্ডেশনঃ)"],"ru":["Сообщается, что ‘Аиша, да будет доволен ею Аллах, сказала: «Когда Посланник Аллаха ﷺ был здоров, он часто говорил:","“Поистине, ни один пророк никогда не умирал, пока не (предоставлялась ему возможность) увидеть его место в раю, а потом к нему либо обращались с приветствием,","либо предоставлялся выбор”».\\n(Передатчик этого хадиса сказал): «А когда он заболел, и смерть его была уже близка,","и голова его лежала на ноге ‘Аиши, он потерял сознание; очнувшись же, он стал смотреть в потолок, а потом сказал: “О Аллах, (позволь мне оказаться) в высшем обществе!","/Аллахумма, фир-р-рафики-ль-а‘ля!/” Тогда я сказала: “Значит,","он не останется с нами!” — а потом поняла, что эти его слова (подтверждают) то, что он говорил нам, когда был здоров»"]}},"h_niyyah":{"src":"bukhari 1","w":["سَمِعْتُ","رَسُولَ","اللَّهِ","صَلَّى","اللَّهُ","عَلَيْهِ","وَسَلَّمَ،","يَقُولُ:","إِنَّمَا","الْأَعْمَالُ","بِالنِّيَّاتِ،","وَإِنَّمَا","لِكُلِّ","امْرِئٍ","مَا","نَوَى،","فَمَنْ","كَانَتْ","هِجْرَتُهُ","إِلَى","دُنْيَا","يُصِيبُهَا","أَوْ","إِلَى","امْرَأَةٍ","يَنْكِحُهَا،","فَهِجْرَتُهُ","إِلَى","مَا","هَاجَرَ","إِلَيْهِ"],"p":[[0,7],[7,16],[16,26],[26,31]],"m":{"en":["Narrated 'Umar bin Al-Khattab: I heard Allah's Messenger (ﷺ) saying,","\"The reward of deeds depends upon the intentions and every person will get the reward according to what he has intended.","So whoever emigrated for worldly benefits or for a woman to marry,","his emigration was for what he emigrated for"],"fr":["Rapporté par 'Umar ibn Al-Khattab : J'ai entendu le Messager d'Allah (ﷺ) dire :","« La récompense des actions dépend des intentions, et chacun sera récompensé selon son intention.","Donc, celui qui a émigré pour obtenir des biens matériels ou pour épouser une femme,","son émigration sera pour ce pour quoi il a émigré. »"],"tr":["Alkame b. Vakkâs el-Leysî'den: O şöyle demiştir: Ömer İbnu'l-Hattâb'ın minberde şöyle dediğini duydum:","Allah Resulü (Sallallahu Aleyhi ve Sellem)’in şunları söylediğini duydum: \"Ameller niyetlere göredir ve herkes için niyet ettiğinin karşılığı vardır.","Kimin hicreti elde edeceği dünyalığa veya evleneceği bir kadına ise hicreti, hicret ettiği şeyedir. Tekrar: 54, 2529, 3898, 5070, 6689, 6953. Diğer Tahric:: Müslim, imare; Ebu Davud Talak;","Tirmizî, cihad; Nesâî, tahare, talak, eymân; İbn Mace, zühd; Ahmed b. Hanbel, I"],"ur":["کو حمیدی نے یہ حدیث بیان کی، انہوں نے کہا کہ ہم کو سفیان نے یہ حدیث بیان کی، وہ کہتے ہیں ہم کو یحییٰ بن سعید انصاری نے یہ حدیث بیان کی،","انہوں نے کہا کہ مجھے یہ حدیث محمد بن ابراہیم تیمی سے حاصل ہوئی۔ انہوں نے اس حدیث کو علقمہ بن وقاص لیثی سے سنا، ان کا بیان ہے کہ میں نے مسجد نبوی میں منبر رسول صلی اللہ علیہ وسلم پر عمر بن خطاب رضی اللہ عنہ کی زبان سے سنا،","وہ فرما رہے تھے کہ میں نے جناب رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ صلی اللہ علیہ وسلم فرما رہے تھے کہ تمام اعمال کا دارومدار نیت پر ہے اور ہر عمل کا نتیجہ ہر انسان کو اس کی نیت کے مطابق ہی ملے گا۔ پس جس کی ہجرت ( ترک وطن ) دولت دنیا حاصل کرنے کے لیے ہو یا کسی عورت سے شادی کی غرض ہو۔ پس اس کی ہجرت ان ہی چیزوں کے لیے ہو گی جن کے حاصل کرنے کی نیت سے اس نے ہجرت کی ہے۔",""],"id":["Telah menceritakan kepada kami [Al Humaidi Abdullah bin Az Zubair] dia berkata, Telah menceritakan kepada kami [Sufyan] yang berkata,","bahwa Telah menceritakan kepada kami [Yahya bin Sa'id Al Anshari] berkata, telah mengabarkan kepada kami [Muhammad bin Ibrahim At Taimi], bahwa dia pernah mendengar [Alqamah bin Waqash Al Laitsi] berkata; saya pernah mendengar [Umar bin Al Khaththab] diatas mimbar berkata;","saya mendengar Rasulullah shallallahu 'alaihi wasallam bersabda: \"Semua perbuatan tergantung niatnya, dan (balasan) bagi tiap-tiap orang (tergantung) apa yang diniatkan;","Barangsiapa niat hijrahnya karena dunia yang ingin digapainya atau karena seorang perempuan yang ingin dinikahinya, maka hijrahnya adalah kepada apa dia diniatkan"],"bn":["وَقَوْلُ اللهِ جَلَّ ذِكْرُهُ (إِنَّا أَوْحَيْنَا إِلَيْكَ كَمَا أَوْحَيْنَا إِلَى نُوحٍ وَالنَّبِيِّينَ مِنْ بَعْدِ­­هِ) এ মর্মে আল্লাহ্ তা’আলার বাণীঃ ‘‘নিশ্চয় আমি আপনার প্রতি সেরূপ ওয়াহী প্রেরণ করেছি যেরূপ নূহ ও তাঁর পরবর্তী নবীদের (নবীদের) প্রতি ওয়াহী প্রেরণ করেছিলাম।’’ (সূরাহ্ আন-নিসা ৪/১৬৩) ১.","","‘আলক্বামাহ ইবনু ওয়াক্কাস আল-লায়সী (রহ.) হতে বর্ণিত। আমি ‘উমার ইবনুল খাত্তাব (রাঃ)-কে মিম্বারের উপর দাঁড়িয়ে বলতে শুনেছিঃ আমি আল্লাহর রাসূল সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে বলতে শুনেছিঃ কাজ (এর প্রাপ্য হবে) নিয়্যাত অনুযায়ী। আর মানুষ তার নিয়্যাত অনুযায়ী প্রতিফল পাবে। তাই যার হিজরাত হবে ইহকাল লাভের অথবা কোন মহিলাকে বিবাহ করার উদ্দেশে- তবে তার হিজরাত সে উদ্দেশেই হবে, যে জন্যে,","সে হিজরাত করেছে।] (৫৪, ২৫২৯, ৩৮৯৮, ৫০৭০, ৬৬৮৯, ৬৯৫৩; মুসলিম ২৩/৪৫ হাঃ ১৯০৭, আহমাদ ১৬৮) ( আধুনিক প্রকাশনী- ১, ইসলামিক ফাউন্ডেশন)"],"ru":["Сообщается от ‘Умара ибн аль-Хаттаба, да будет доволен им Аллах, как он, будучи на минбаре,","сказал:\\n— Я слышал, как Посланник Аллаха ﷺ сказал: «Поистине, дела (оцениваются) только по намерениям и, поистине, каждому человеку (достанется) лишь то,","что он намеревался (обрести), и (поэтому) переселявшийся[1] ради чего-нибудь мирского или ради женщины, на которой он хотел жениться[2],","переселится (лишь) к тому, к чему он переселялся[3]»"]}},"h_nasiha":{"src":"muslim 196","w":["عَنْ","تَمِيمٍ","الدَّارِيِّ","أَنَّ","النَّبِيَّ","صلى","الله","عليه","وسلم","قَالَ","الدِّينُ","النَّصِيحَةُ","قُلْنَا","لِمَنْ","قَالَ","لِلَّهِ","وَلِكِتَابِهِ","وَلِرَسُولِهِ","وَلأَئِمَّةِ","الْمُسْلِمِينَ","وَعَامَّتِهِمْ."],"p":[[0,12],[12,21]],"m":{"en":["It is narrated on the authority of Tamim ad-Dari that the Prophet (ﷺ) said:\"The Religion is sincerity.\" We said,","\"To whom?\" He said \"To Allah, to His Book, To His Messenger, and to the leaders of the Muslims and their masses"],"fr":["Rapporté par Tamim ad-Dari : Le Prophète ﷺ a dit : « La religion, c’est la sincérité. » Nous avons demandé : « Envers qui ?","» Il a répondu : « Envers Allah, envers Son Livre, envers Son Messager, envers les dirigeants des musulmans et envers l’ensemble des musulmans. »"],"tr":["Bize Muhammed b. Abbad el-Mekkl tahdis etti. Bize Süfyan tahdis edip dedi ki: Süheyl'e dedim ki: Amr, bize Ka'ka' dan tahdis etti. O senin babandan tahdis edip babandan benim rivayetimdeki senedimden bir adamı düşürmesini ümid ettim, dedi. Ancak Süheyl: Ben bu hadisi babamın kendisinden dinlemiş olduğu zattan dinledim, o babamın Şam'daki bir arkadaşı idi,","dedi. Sonra Süfyan bize Süheyl'den tahdis etti. O Ata b. Yezid'den, 0, Temim ed-Dari (r.a.)'dan rivayet ettiğine göre Nebi (Sallallahu aleyhi ve Sellem): \"Din nasihattir\" buyurdu. Biz, kime dedik, O: \"Allah'a, kitabına, Rasulüne, Müslümanların yöneticilerine ve bütün Müslümanlara\" buyurdu. Diğer tahric: Ebu Davud, 4944; Nesai, 4208, 4209; Tuhfetu'l-Eşraf, 2053 A.DAVUDOĞLU İZAHI İÇİN buraya tıklayın"],"ur":["سفیان بن عیینہ نے کہا : میں نے سہیل سے کہا کہ عمرو نے ہمیں قعقاع کے واسطے سے آپ کے والد سے حدیث سنائی ( سفیان نے کہا : ) مجھے امید تھی کہ وہ ( مجھے خود روایت سنا کر ) ایک راوی کم کر دے گا ( چنانچہ سہیل نےکہا ) میں نے اسی سے یہ روایت سنی جس سے میرے والد سے سنی ،","وہ شام میں ان کا دوست تھا ۔ ( محمد بن عباد نے کہا ) پھر سفیان نے ہمیں سہیل کے واسطے سے عطاء بن یزید کی حضرت تمیم داری ‌رضی ‌اللہ ‌عنہ ‌ ‌ سےروایت سنائی کہ بنی اکرم ﷺ نے فرمایا : ’’ دین خیر خواہی کا نام ہے ۔ ‘ ‘ ہم ( صحابہ ‌رضی ‌اللہ ‌عنہ ‌ ‌ ) نے پوچھا : کس کی ( خیر خواہی؟ ) آپ نے فرمایا : ’’ اللہ کی ، اس کی کتاب کی ، اس کے رسول کی ، مسلمانوں کے امیروں کی اور عام مسلمانون کی ( خیرخواہی ۔ ) ‘ ‘"],"id":["Telah menceritakan kepada kami [Muhammad bin Abbad al-Makki] telah menceritakan kepada kami [Sufyan] -dia berkata, saya berkata kepada Suhail- bahwa [Amru] menceritakan kepada kami dari [al-Qa'qa'] dari [bapakmu] dia berkata, dan aku berharap agar satu perawi jatuh dariku, Amru berkata, \"Lalu al Qa'qa' berkata, \"Saya mendengarnya dari orang yang yang bapakku pernah mendengar darinya -dia adalah temannya di Syam-. Kemudian telah menceritakan kepada kami [Sufyan] dari [Suhail] dari [Atha' bin Yazid] dari [Tamim ad-Dari] bahwa nabi shallallahu 'alaihi wasallam bersabda: \"Agama itu adalah nasihat.\" Kami bertanya, \"Nasihat untuk siapa?\" Beliau menjawab,","\"Untuk Allah, kitab-Nya, Rasul-Nya, dan para pemimpin kaum muslimin, serta kaum awam mereka.\" Telah menceritakan kepada kami [Muhammad bin Hatim] telah menceritakan kepada kami [Ibnu Mahdi] telah menceritakan kepada kami [Sufyan] dari [Suhail bin Abu Shalih] dari [Atha' bin Yazid al-Laitsi] dari [Tamim ad-Dari] dari Nabi shallallahu 'alaihi wasallam dengan semisalnya, Dan telah menceritakan kepada kami [Umayyah bin Bistham] telah menceritakan kepada kami [Yazid] -yaitu Ibnu Zurai'- telah menceritakan kepada kami [Rauh] -yaitu Ibnu al-Qasim- telah menceritakan kepada kami [Suhail] dari [Atha' bin Yazid] dia mendengarnya -saat 'Atha menceritakan kepada Abu Shalih- dari [Tamim ad-Dari] dari Rasulullah shallallahu 'alaihi wasallam, seperti hadits tersebut"],"bn":["মুহাম্মাদ ইবনু আব্বাদ আল মাক্কী (রহঃ) ..... তামীম আদ দারী (রহঃ) হতে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়া সাল্লাম বলেছেনঃ সদুপদেশ দেয়াই দীন। আমরা আরয করলাম,","কার জন্য উপদেশ? তিনি বললেনঃ আল্লাহ ও তার কিতাবের, তার রাসূলের, মুসলিম শাসক এবং মুসলিম জনগণের*। (ইসলামিক ফাউন্ডেশনঃ ১০২, ইসলামিক সেন্টারঃ)"],"ru":["Передают со слов Тамим ад-Дари (да будет доволен им Аллах) о том, что Пророк ﷺ сказал: «Религия есть проявление искренности».","Мы спросили: «По отношению к кому?» Он сказал: «(По отношению) к Аллаху, и к Его Книге, и к Его посланнику, и к руководителям мусульман и ко всем мусульманам вообще»"]}},"h_khayr":{"src":"bukhari 6018","w":["عَنْ","أَبِي","هُرَيْرَةَ،","قَالَ","قَالَ","رَسُولُ","اللَّهِ","صلى","الله","عليه","وسلم","مَنْ","كَانَ","يُؤْمِنُ","بِاللَّهِ","وَالْيَوْمِ","الآخِرِ","فَلاَ","يُؤْذِ","جَارَهُ،","وَمَنْ","كَانَ","يُؤْمِنُ","بِاللَّهِ","وَالْيَوْمِ","الآخِرِ","فَلْيُكْرِمْ","ضَيْفَهُ،","وَمَنْ","كَانَ","يُؤْمِنُ","بِاللَّهِ","وَالْيَوْمِ","الآخِرِ","فَلْيَقُلْ","خَيْرًا","أَوْ","لِيَصْمُتْ."],"p":[[0,12],[12,20],[20,28],[28,38]],"m":{"en":["Narrated Abu Huraira:Allah's Messenger (ﷺ) said,","\"Anybody who believes in Allah and the Last Day should not harm his neighbor,","and anybody who believes in Allah and the Last Day should entertain his guest generously and anybody who believes in Allah and the Last Day should talk what is good or keep quiet.","(i.e. abstain from all kinds of evil and dirty talk)"],"fr":["Rapporté par Abu Huraira : Le Messager d’Allah (ﷺ) a dit :","« Celui qui croit en Allah et au Jour dernier ne doit pas nuire à son voisin ;","celui qui croit en Allah et au Jour dernier doit être généreux envers son invité ;","et celui qui croit en Allah et au Jour dernier doit dire du bien ou se taire. »"],"tr":["Ebu Hureyre (r.a.)'dan, dedi ki: \"Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurdu:","Aııah'a ve ahiret gününe iman eden bir kimse komşusuna eziyet vermesin.","Allah'a ve ahiret gününe iman eden bir kimse misafirine ikram etsin.","Allah'a ve ahiret gününe iman eden bir kimse ya hayır söylesin yahut sussun.\" Diğer tahric edenler: Tirmizi Kıyame; Müslim, İman"],"ur":["ہم سے قتیبہ بن سعید نے بیان کیا، انہوں نے کہا ہم سے ابوالاحوص نے بیان، ان سے ابوحصین نے،","","ان سے ابوصالح نے اور ان سے ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ”جو کوئی اللہ اور آخرت کے دن پر ایمان رکھتا ہو وہ اپنے پڑوسی کو تکلیف نہ پہنچائے اور جو کوئی اللہ اور آخرت کے دن پر ایمان رکھتا ہو وہ اپنے مہمان کی عزت کرے اور جو کوئی اللہ اور آخرت کے دن پر ایمان رکھتا ہو وہ اچھی بات زبان سے نکالے ورنہ خاموش رہے۔“",""],"id":["Telah menceritakan kepada kami [Qutaibah bin Sa'id] telah menceritakan kepada kami [Abu Al Ahwash] dari [Abu Hashin] dari [Abu Shalih] dari [Abu Hurairah] dia berkata;","Rasulullah shallallahu 'alaihi wasallam bersabda:","\"Barangsiapa berimana kepada Allah dan hari Akhir, janganlah ia mengganggu tetangganya,","barangsiapa beriman kepada Allah dan hari Akhir hendaknya ia memuliakan tamunya dan barangsiapa beriman kepada Allah dan hari Akhir hendaknya ia berkata baik atau diam"],"bn":["আবূ হুরাইরাহ (রাঃ) হতে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ যে ব্যক্তি আল্লাহ ও আখিরাতের দিনে বিশ্বাস রাখে,","সে যেন তার মেহমানকে সম্মান করে। যে আল্লাহ ও শেষ দিনে বিশ্বাস রাখে,","সে যেন তার প্রতিবেশীকে জ্বালাতন না করে। যে লোক আল্লাহ ও শেষ দিনে বিশ্বাস রাখে,","সে যেন ভাল কথা বলে, অথবা চুপ থাকে। [৫১৮৫; মুসলিম ১/১৯, হাঃ ৪৭, আহমাদ ৭৬৩০] (আধুনিক প্রকাশনী- ৫৫৮৪, ইসলামিক ফাউন্ডেশন)"],"ru":["Передают со слов Абу Хурайры, да будет доволен им Аллах, что Посланник Аллаха ﷺ сказал:","«Пусть тот, кто верует в Аллаха и в Последний день,","не причиняет вреда своему соседу, и пусть тот, кто верует в Аллаха и в Последний день,","оказывает уважение своему гостю, и пусть тот, кто верует в Аллаха и в Последний день, говорит благое или молчит»"]}},"h_ghadab":{"src":"bukhari 6116","w":["قَالَ","لِلنَّبِيِّ","صلى","الله","عليه","وسلم","أَوْصِنِي.","قَالَ","لاَ","تَغْضَبْ.","فَرَدَّدَ","مِرَارًا،","قَالَ","لاَ","تَغْضَبْ."],"p":[[0,7],[7,12],[12,15]],"m":{"en":["Narrated Abu Huraira:A man said to the Prophet (ﷺ) , \"Advise me! \"The Prophet (ﷺ) said,","\"Do not become angry and furious.\" The man asked (the same) again and again, and the Prophet (ﷺ) said in each case,","\"Do not become angry and furious"],"fr":["Rapporté par Abu Huraira : Un homme a dit au Prophète (ﷺ) : « Donne-moi un conseil ! » Le Prophète (ﷺ) a dit :","« Ne te mets pas en colère. » L’homme a répété sa demande plusieurs fois, et à chaque fois,","le Prophète (ﷺ) a répondu : « Ne te mets pas en colère. »"],"tr":["Ebu Hureyre r.a.'dan rivayete göre; \"Bir adam Nebi Sallallahu Aleyhi ve Sellem'e: \"Bana tavsiyede bulun, dedi. Allah Rasulü: Kızma, buyurdu. Adam istediğini defalarca tekrarladığı halde yine: Kızma, buyurdu.\" Diğer tahric eden: Tirmizi Birr Fethu'l-Bari Açıklaması: \"Güçlü kuwetli kişi rakiplerinin sırtını yere getiren değildir.\" Yani gücüyle insanların sırtını çokça yere getiren kişi değildir. \"Asıl güçlü kuwetli kişi, kızdığı zaman kendisine hakim olandır.\" Hadise dair açıklamalar daha önce \"Sövüp saymak ve lanetlemek\" başlığında geçmiş bulunmaktadır. el-Hattabi dedi ki: Nebi efendimizin: \"Kızma\" buyruğu, kızgınlığa götüren sebeplerden uzak dur, kızgınlığı getirecek hallerle kendi kendini karşı karşıya bırakma, demektir. Bizatihi kızmanın kendisinin yasaklanması zaten sözkonusu olamaz. Çünkü kızgınlık tabii bir durum olup insanın tabiatından gitmesi düşünülemez. Anlamının şöyle olduğu da söylenmiştir: Kızma, çünkü kızgınlığın çıkardığı en büyük şey, kibirdir. Kızmak, genelde kişinin istediği bir işe aykırılık halinde ortaya çıkar. Bunun sonucunda da kibir kişiyi kızmaya götürür. Ama nefsin kibri gidene kadar alçak gönüllü davranan kimse, kızgınlığın şerrinden kurtulur. Kızmanın sana emrettiği işi yapma, anlamında olduğu da söylenmiştir. İbn Battal dedi ki: Birinci hadiste nefse karşı mücahedenin düşmana karşı mücahededen daha zor olduğu anlatılmaktadır. Çünkü Nebi Sallallahu Aleyhi ve Sellem kızgınlık halinde kendisine hakim olan kimseyi, insanların en güçlüsü olarak değerlEmdirmiştir. Başkası da şöyle demektedir: Muhtemelen (başlıktaki 6116 nolu hadiste) sözü geçen soruyu soran kişi, çokça kızan birisi idi. Nebi Sallallahu Aleyhi ve Sellem de soru soran herbir kimseye en uygun olan emri verirdi. Bundan dolayı Allah Rasulü, bu kişiye de kızmayı terk etmeyi tavsiyeyle yetindi.","Kimi ilim adamı da şöyle demiştir: Allah kızgınlığı ateşten yarattı ve bunu insanın bir tabiatı kıldı. Kızgınlık ateşinin yanıp parlamasına sebep olan herbir hususta insana karşı çıkılıp yahut onunla tartışıldığı takdirde, onun da yüzü ve gözleri kandan dolayı kızarır. Çünkü insanın teni, arka tarafında gizlenen rengi anlatır. Böyle bir kimse, kendisinden daha alt mertebede bulunana gücünün yettiğini anlarsa bu hali alır. Eğer kendisinden daha yukarı bir mertebede ise, bundan dolayı derinin görünen tarafından kalbin iç tarafına doğru kan çekilmeye başlar ve üzüntüden dolayı rengi sararır. Eğer kendisine denk bir kimseye karşı bu halortaya çıkarsa, kan çekilmek ile yayılmak arasında gider gelir. Bundan dolayı kızarır ve sararır. Öfkenin sonucu olarak dış ve içte değişiklikler meydana gelir. Renk değişmesi, organların titremesi, gelişigüzel davranışların gösterilmesi, hilkatin farklı bir hal alması gibi. Hatta kızgın bir kimse, kendisini kızgın haliyle görecek olursa, suretinin çirkinliğinden ve hilkatinin değişime uğramasından utanarak öfkesi diner. Bütün bunlar zahiren görülen şeylerdir. İç dünyadaki çirkinliği ise, zahiren görünenden daha da ileridir. Çünkü kızgınlık, kalpte kini ve kıskançlığı doğurur, farklı türleriyle kötülükleri kalpte saklamaya neden olur. Hatta kızgınlık ilk olarak insanın iç dünyasını çirkinleştirir. Dışının değişikliğe uğraması ise, iç dünyasındaki değişikliğin bir neticesidir. Bütün bunlar, kızgınlığın bedendeki etkileridir. Dildeki etkilerine gelince,","gelişigüzel sövüp sayar ve aklı başında kimsenin utanacağı, öfkesinin dinmesi esnasında söyleyenin pişman olacağı çirkin sözler söyler. Kızgınlık, dövmek yahut öldürmek gibi fiili davranışlarda da etkisini gösterir. Bütün bunlar ise, daha önce -bir önceki başlıkta- açıklandığı üzere dini anlamıyla gazapta değil, dünyevı gazapta sözkonusudur. Kızıp öfkelenmeyi terk etmeye yardımcı olan husus, öfkeyi yenmenin faziletine dair varid olmuş buyrukları hatırlamak, kızgınlığın semeresi olan şeylerin ortaya çıkması sonucundaki tehditleri hatıra getirmek, ayrıca Süleyman İbn Surad'ın rivayet ettiği hadiste geçtiği gibi, şeytandan Allah'a sığınmak, daha önce Atiyye hadisinde işaret edildiği gibi de abdest almak ile olur. Doğrusunu en iyi bilen Allah'tır"],"ur":["مجھ سے یحییٰ بن یوسف نے بیان کیا، کہا ہم کو ابوبکر نے خبر دی جو ابن عیاش ہیں، انہیں ابوحصین نے،","انہیں ابوصالح نے اور انہیں ابوہریرہ رضی اللہ عنہ نے کہ ایک شخص نے نبی کریم صلی اللہ علیہ وسلم سے عرض کیا کہ مجھے آپ کوئی نصیحت فرما دیجئیے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ غصہ نہ ہوا کر۔ انہوں نے کئی مرتبہ یہ سوال کیا اور نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ غصہ نہ ہوا کر۔",""],"id":["Telah menceritakan kepadaku [Yahya bin Yusuf] telah mengabarkan kepada kami [Abu Bakr yaitu Ibnu Ayyasy] dari [Abu Hashin] dari [Abu Shalih] dari [Abu Hurairah] radliallahu 'anhu bahwa seorang laki-laki berkata kepada Nabi shallallahu 'alaihi wasallam;","\"Berilah aku wasiat?\" beliau bersabda: \"Janganlah kamu marah.\" Laki-laki itu mengulangi kata-katanya,","beliau tetap bersabda: \"Janganlah kamu marah"],"bn":["আবূ হুরাইরাহ হতে বর্ণিত যে,","এক ব্যক্তি নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম -এর নিকট বললঃ আপনি আমাকে অসিয়ত করুন। তিনি বললেনঃ তুমি রাগ করো না। লোকটি কয়েকবার তা বললেন,নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম প্রত্যেক বারেই বললেনঃ রাগ করো না। আধুনিক প্রকাশনী- ৫৬৭৬,","ইসলামিক ফাউন্ডেশন"],"ru":["Передают со слов Абу Хурайры, да будет доволен им Аллах, что один человек попросил Пророка ﷺ: «Дай мне совет».","Он сказал: «Не гневайся». После этого тот несколько раз повторил (свою просьбу,","но Пророк ﷺ каждый раз) говорил: «Не гневайся»"]}},"h_tuhur":{"src":"muslim 534","w":["عَنْ","أَبِي","مَالِكٍ","الأَشْعَرِيِّ،","قَالَ","قَالَ","رَسُولُ","اللَّهِ","صلى","الله","عليه","وسلم","الطُّهُورُ","شَطْرُ","الإِيمَانِ","وَالْحَمْدُ","لِلَّهِ","تَمْلأُ","الْمِيزَانَ.","وَسُبْحَانَ","اللَّهِ","وَالْحَمْدُ","لِلَّهِ","تَمْلآنِ","أَوْ","تَمْلأُ","مَا","بَيْنَ","السَّمَوَاتِ","وَالأَرْضِ","وَالصَّلاَةُ","نُورٌ","وَالصَّدَقَةُ","بُرْهَانٌ","وَالصَّبْرُ","ضِيَاءٌ","وَالْقُرْآنُ","حُجَّةٌ","لَكَ","أَوْ","عَلَيْكَ","كُلُّ","النَّاسِ","يَغْدُو","فَبَائِعٌ","نَفْسَهُ","فَمُعْتِقُهَا","أَوْ","مُوبِقُهَا."],"p":[[0,12],[12,19],[19,31],[31,43],[43,49]],"m":{"en":["Abu Malik at-Ash'ari reported:The Messenger of Allah (ﷺ) said:","Cleanliness is half of faith and al-Hamdu Lillah (all praise and gratitude is for Allah alone) fills the scale,","and Subhan Allah (Glory be to Allah) and al-Hamdu Lillah fill up what is between the heavens and the earth, and prayer is a light,","and charity is proof (of one's faith) and endurance is a brightness and the Holy Qur'an is a proof on your behalf or against you. All men go out early in the morning and sell themselves,","thereby setting themselves free or destroying themselves"],"fr":["Rapporté par Abu Malik al-Ash’ari رضي الله عنه : Le Messager d’Allah ﷺ a dit : « La propreté est la moitié de la foi.","“Al-Hamdu Lillah” (la louange et la reconnaissance reviennent à Allah seul) remplit la balance,","et “Subhan Allah” (Gloire à Allah) et “Al-Hamdu Lillah” remplissent ce qu’il y a entre les cieux et la terre. La prière est une lumière,","l’aumône est une preuve (de la foi), la patience est une clarté, et le Coran est une preuve pour toi ou contre toi.","Tous les hommes sortent le matin et se vendent eux-mêmes : certains se libèrent, d’autres se détruisent. »"],"tr":["Bize İshak b. Mansur tahdis etti, bize Habban b. Hilal tahdis etti, bize Eban tahdis etti. Bize Yahya'nın tahdis ettiğine göre Zeyd kendisine şunu tahdis etti: Ebu Sellam kendisine Ebu Malik el-Eş'arl'den şöyle dediğini tahdis etti: Rasülullah (Sallallahu aleyhi ve Sellem) şöyle buyurdu: ''Abdest imanın yarısıdır. Elhamdulillah mizanı doldurur. Subhanallah ve'l-hamdulillah da göklerle yer arasını doldururlar -yahut doldurur-, namaz bir nurdur, sadaka bir burhandır, sabır bir ışıktır, Kur'an senin lehine ya da aleyhine bir huccettir. Bütün insanlar sabah gider ve nefsini satar. Bu sebeple ya onu hürriyetine kavuşturur (azad eder) yahut onu helake götürür. '' Diğer tahric: Tirmizi, 3517; Tuhfetu'l-Eşraf, 12167 DAVUDOĞLU ŞERHİ AŞAĞIDA NEVEVİ ŞERHİ: Müslim (rahimehullah) dedi ki: \"Bize İshak b. Mansur tahdis etti ... Ebu Malik el-Eş'ar'i'den.\" Bu Darakutni'nin ve başkalannın hakkında bazı tenkitlerde bulunduğu isnadlardan birisidir. Onlar derler ki: Bu isnadta Ebu Sellam ile Ebu Malik arasında bir ravi düşmüştür. (3/99) Düşen ravi ise Abdurrahman b. Gunm'dır. Düştüğünün delili de Muaviye b. Sellam bu hadısi kardeşi Zeyd b. Sellam'dan, O dedesi Ebu Sellam'dan, O Abdurrahman b. Gunm'dan, o Ebu Malik el-Eş'ari'den diye rivayet etmiş olmasıdır. Bu hadisi Nesai, İbn Mace ve başkaları da böyle tahriç etmişlerdir. Bu itiraza Müslim adına şu şekilde cevap vermek mümkündür: Müslim'in halinin zahirinden anlaşılan onun Ebu Sellam'ın bu hadisi Ebu Malik'ten dinlediğini bilmesidir. Bu durumda Ebu Sellam bu hadisi hem Ebu Malik'ten dinlemiş, hem de Abdurrahman b.","Gunm'dan, o Ebu Malik'ten diye de dinle miştir. Bazen onu bizzat ondan, bazen de Abdurrahman'dan diye rivayet etmiştir. Durum her ne olursa olsun metin sahihtir, hakkında bir tenkit sözkonusu değildir. Allah en iyi bilendir. Habban b. Hilal'in isminde ha harfi fethalı okunur, Eban'dan daha önce kitabın baş taraflarında söz edilmiş, munsarıf ve gayrı munsarıf olabileceği, tercih edilenin de munsarıf olduğu belirtilmiş idi. Ebu Sellam'ın adı Mantur elN.rec el-Habeşı ed-Dımeşkl'dir. Onun bu nispeti Habeşlilere değil Yemen'den Himyer'in bir kolunadır. Ebu Malik'in adı hakkında ihtilM edilmiştir. Haris, Ubeyd ve Ka'b b. Asım olduğu, Amr olduğu da söylenmiştir. Şamlı raviler arasında sayılır. \"Abdest imanın yarısıdır. .. yahut onu helake götürür.\" Bu İslam'ın esaslarından pek büyük hadistir. İslam'ın önemli birtakım kaidelerini kapsar. Tuhur (abdest)ten kasıt abdest alma eylemidir. Bu sebeple tercih edilen ve çoğunluğunun görüşüne göre tı harfinin ötreli okunacağıdır, az önce geçtiği gibi fethalı okunması da caizdir. Şatr ise yarısı demektir. Resulullah (Sallallahu aleyhi ve Sellem)'in: \"Abdest imanın yarzsıdır\" buyruğunun anlamı hususunda farklı açıklamalar yapılmıştır. Onun için verilecek mükMat imanın ecrinin yarısına kadar kat1andırılıp, yükselir demek olduğu söylendiği gibi iman kendisinden önceki günahları siler, süpürür, abdest de böyledir. Çünkü abdest ancak iman ile birlikte sahih olur.","İman şartına bağlı olması dola~;.'ısıyla yarısı demektir anlamında olduğu da söylenmiştir. Bir diğer açıklamaya göre burada imandan kasıt namazdır. Nitekim yüce Allah: \"Allah sizin imanınızı boşa çıkaracak değildir.\" (Bakara, 2/143) buyurmaktadır. Taharet (şer'i temizlik) namazın sıhhati için bir şarttır. Bundan dolayı yarısı gibi değerlendirilmiştir. Şatr lafzının gerçek manada yarım olması da zorunlu değildir. Görüşler arasında doğruya en yakın olan budur. Bunun şu anlama gelme ihtimali de vardır: İman kalp ile tasdik, zahiren de inkiyad (emre itaat ve bağlılık) demektir. Bu ikisi imanın birer şatrı (yarısı)dır. Taharet (abdest) ise namazı da ihtiva eder. (3/100) Bu sebepten dolayı namaz da zahiren emre bağlılığı ortaya koyar. Allah en iyi bilendir. \"Elhamdulillah mizanı doldurur.\" Bu da ecrinin büyük olduğu ve bu ecrin mizanı doldurduğu anlamına gelir. Amellerin tartılacağına ve tartıların ağır ve hafif geleceğine dair Kur'an ve sünnetin nasıarı birbirini pekiştirmektedir. \"Subhanallah ve elhamdulillah göklerle yer arasını doldururlar -yahut doldurur. -\" Bu buyruğun anlamı ile ilgili olarak şöyle denilebilir: Eğer bunların sevapıarı bir cisim olarak takdir edilirse göklerle yer arasını doldurur. Faziletlerinin büyük olmasının sebebi ise subhanallah demekle yüce Allah'ın tenzih edilmesi (her türlü eksiklikten münezzeh olduğunun bildirilmesi) ve elhamdulillah diyerek de işlerin yüce Allah'a havale edilip, ona ihtiyacın arz edilmesi anlamlarını kapsadıklarındandır. Allah en iyi bilendir. \"Namaz nurdur.\" Yani o masiyetlerden alıkoyar, hayasızlıklardan ve münkerden uzaklaştırır, doğruya iletir. Tıpkı nur ile aydınlanıldığı gibi. Bunun, namazın ecri kıyamet gününde namaz kılan için bir nur olacaktır anlamında olduğu söylendiği gibi, namaz kılarken kalp onun sebebiyle başka şeylerden boşalıp, zahiri ve batını ile yüce Allah'a yöneldiğinden ötürü hakikatlerin mükaşefesine ve kalbin genişleyip, marifet nurlarının parıldamasına sebep olduğu için de ona nur denilmiştir diye de açıklanmıştır. Şanı yüce Allah da: \"Sabır ve namaz ile (Allah'tan) yardım isteyin.\" (Bakara, 45) buyurmaktadır. Namazın nur olmasının şu anlamda olduğu da söylenmiştir: Namaz kıyamet gününde namaz kılanın yüzü üzerinde açıkça görünen bir nur olacaktır.","Nitekim dünyada da namaz kılmayanların aksine namaz kılanın yüzünde bir parlaklık ve aydınlık olur. Allah en iyi bilendir. \"Sadaka burhandır. \" Tahrir sahibi der ki: Yani delil ve belgelere başvurulduğu gibi, sadakaya da sığınılır. Çünkü ku la kıyamet gününde malını nerede harcadığı sorulacak olursa onun verdiği sadakalar bu soruya verilecek cevabın burhanları (delilleri, belgeleri) olacak, o: Malımı tasadduk ettim diyecek. (Devamla) der ki: Sadaka veren kimsenin kendisiyle tanınacağı bir aiametle alametlendirilecek olması da mümkündür. Böylelikle bu alamet onun halinin ne olduğuna dair bir burhan olur ve malını nerede harcadığı ona sorulmaz. Tahrir sahibinden başkası da şöyle demektedir: Yani sadaka, sadaka verenin imanına dair bir delildir; çünkü münafık sadakaya inanmadığından ötürü sadaka vermez. Bundan dolayı sadaka verenin verdiği sadaka imanının sıdkına (doğruluğuna) delildir. Allah en iyi bilendir. \"Sabır bir ziyadır.\" Bunun anlamı şeriatta sevilen sabır türüdür. Bu da yüce Allah'a itaat üzere sabır, masiyetleri işlemekten uzak durmakta sabır ve aynı zamanda dünyada hoşlanılmayan türlü hal ve musibetlere karşı sabırdır. Maksat ise sabrın övülen bir halolup, sabırlı kimsenin her zaman için doğruluk üzerinde aydınlanan ve sürekli olarak hidayet üzere olan bir kimse olduğunun anlatılmasıdır. (3/101) İbrahim el-Hawas dedi ki: Sabır, kitap ve sünnet üzere sebat etmektir. İbn Ata dedi ki: Sabır, bela halinde güzel bir edeple durmaktır. Üstat Ebu Ali ed-Dekkak (rahimehullah) da şöyle demektedir: Sabrın hakikati takdire itiraz etmemektir. Şikayet etmek maksadıyla olmamak üzere uğradığı belayı açıklamak ise sabra aykırı değildir. Çünkü Eyyub (aleyhisselam): \"Rabbim başıma bu bela gelip çattı.\" (Enbiya, 21/83) dediği bildirilmekle birlikte yüce Allah da onun hakkında: \"Gerçekten biz onu sabredici bulduk, o ne güzel kuldur.\" (Sad, 38/44) buyurmaktadır. Allah en iyi bilendir. \"Kur'an senin lehine ya da aleyhine bir deli/dir\" anlamı gayet açıktır yani onu okuyup, gereğince amel edecek olursan ondan yararlanırsın,","aksi takdirde o senin aleyhine bir delil olur. \"Bütün insanlar sabahleyin gider ... \" Bütün insanlar bizzat kendisi için çalışır. Kimisi itaat etmek suretiyle nefsini yüce Allah'a satarak azaptan azat eder, kurtarır, kimisi de onu şeytana ve hevaya uymak suretiyle onlara onu satar ve böylelikle onu helak eder. Allah en iyi bilendir. DAVUDOĞLU AÇIKLAMA: İSNADI VE TAHRİCİ: Bu hadisi Nesaî ile İbni Mace'de tahriç etmişlerdir. Hadisin isnadı hakkında Dare Kutnî ile diğer bazı hadis uleması söz etmiş ve Ebu Sellam ile Ebu Malik arasından ravi Abdurrahman b. Gunm'un düştüğünü söylemişlerdir, «Buna delil Muaviye b. Sellam'ın aynı hadisi kardeşi Zeyd b. Sellam 'dan, o da dedesi Ebu Sellam'dan, o da Abdurrahman b.Gunm'dan, o da Ebu Malik'i Eş'arî'den naklen rivayet etmiş olmasıdır. Hadisi Nesaî, İbni Mace ve -diğer imamlar bu şekilde tahric etmişlerdir» derler. Nevevî: «Müslim tarafından buna şöyle cevap verilebilir: Zahîre göre! Müslim bu hadisi Ebu Sellam'in Ebu Malik'ten dinlediğini işitmiştir ve Ebu Sellam bunu hem Ebu Malik 'ten hemde Abdurrahman b. Malik 'ten bazanda Abdurrahman b. Gunm 'dan rivayet etmiştir. Ne olursa olsun bu metin sahihtir. Ta'n edecek yeri yoktur.» diyor"],"ur":["حضرت ابو مالک اشعری ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا :","","’’پاکیزگی نصف ایمان ہے ۔ الحمد لله ترازو کو بھر دیتا ہے ۔ سبحان الله اور الحمد لله آسمانوں سے زمین تک کی وسعت کو بھر دیتے ہیں ۔ نماز نور ہے ۔ صدقہ دلیل ہے ۔ صبر روشنی ہے ۔ قرآن تمہارے حق میں یا تمہارے خلاف حجت ہے ہر انسان دن کا آغاز کرتا ہے تو ( کچھ اعمال کے عوض ) اپنا سودا کرتا ہے ،","","پھر یا تو خود آزاد کرنےوالا ہوتا ہے خود کو تباہ کرنے والا ۔ ‘ ‘"],"id":["Telah menceritakan kepada kami [Ishaq bin Manshur] telah menceritakan kepada kami [Habban bin Hilal] telah menceritakan kepada kami [Aban] telah menceritakan kepada kami [Yahya] bahwa [Zaid] telah menceritakan kepadanya,","bahwa [Abu Sallam] telah menceritakan kepadanya dari [Abu Malik al-Asy'ari] dia berkata,","\"Rasulullah shallallahu 'alaihi wasallam bersabda: \"Bersuci adalah setengah dari iman, alhamdulillah memenuhi timbangan, subhanallah dan alhamdulillah keduanya memenuhi,","atau salah satunya memenuhi apa yang ada antara langit dan bumi, shalat adalah cahaya, sedekah adalah petunjuk, kesabaran adalah sinar, dan al-Qur'an adalah hujjah untuk amal kebaikanmu dan hujjah atas amal kejelekanmu.","Setiap manusia adalah berusaha, maka ada orang yang menjual dirinya sehingga membebaskannya atau menghancurkannya"],"bn":["ইসহাক ইবনু মানসূর (রহঃ) ..... আবূ মালিক আল আশ'আরী (রাযিঃ) থেকে বর্ণিত। তিনি বলেন,","","রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ পবিত্রতা হল ঈমানের অর্ধেক অংশ। আলহামদু লিল্লা-হ' মিযানের পরিমাপকে পরিপূর্ণ করে দিবে এবং \"সুবহানাল্লা-হ ওয়াল হামদুলিল্লা-হ\" আসমান ও জমিনের মধ্যবর্তী স্থানকে পরিপূর্ণ করে দিবে। সালাত’ হচ্ছে একটি উজ্জ্বল জ্যোতি। সদাকাহ হচ্ছে দলীল। ধৈর্য হচ্ছে জ্যোতির্ময়। আর \"আল কুরআন' হবে তোমার পক্ষে অথবা বিপক্ষে প্রমাণ স্বরূপ। বস্তুতঃ সকল মানুষই প্রত্যেক ভোরে নিজেকে আমলের বিনিময়ে বিক্রি করে। তার আমল দ্বারা সে নিজেকে (আল্লাহর আযাব থেকে) মুক্ত করে অথবা সে তার নিজের ধ্বংস সাধন করে। (ইসলামিক ফাউন্ডেশনঃ ২য় খণ্ড,","","৪২৫; ইসলামিক সেন্টারঃ)"],"ru":["Сообщается, что Абу Малик аль-Аш‘ари, да будет доволен им Аллах, сказал: «Посланник Аллаха ﷺ сказал:","Очищение половина веры, (слова) “Хвала Аллаху” /Альхамду лиЛляхи/ заполняют собой Весы,","(слова) “Пречист Аллах и хвала Аллаху” /СубханаЛлахи валь-хамду лиЛляхи/ заполняют собой (пространство) между небесами и землёй,","молитва свет, милостыня/садакъа/ доказательство, терпение сияние, а Коран аргумент за тебя или против тебя. Все люди отправляются утром (по своим делам),","и продающий душу свою либо освобождает её, либо губит»"]}},"h_quran":{"src":"bukhari 5027","w":["عَنِ","النَّبِيِّ","صلى","الله","عليه","وسلم","قَالَ","خَيْرُكُمْ","مَنْ","تَعَلَّمَ","الْقُرْآنَ","وَعَلَّمَهُ.","قَالَ","وَأَقْرَأَ","أَبُو","عَبْدِ","الرَّحْمَنِ","فِي","إِمْرَةِ","عُثْمَانَ","حَتَّى","كَانَ","الْحَجَّاجُ،","قَالَ","وَذَاكَ","الَّذِي","أَقْعَدَنِي","مَقْعَدِي","هَذَا."],"p":[[0,12],[12,23],[23,29]],"m":{"en":["Narrated `Uthman:The Prophet (ﷺ) said,","\"The best among you (Muslims) are those who learn the Qur'an and teach it",""],"fr":["Rapporté par `Uthman : Le Prophète (ﷺ) a dit :","« Les meilleurs parmi vous sont ceux qui apprennent le Coran et l’enseignent.","»"],"tr":["Osman radiyallahu anh'dan Nebi Sallallahu Aleyhi ve Sellem'in şöyle buyurduğu rivayet edilmiştir: \"Sizin en hayırlınız Kur'an'ı öğrenen ve öğretendir.\" Sa 'd İbn Ubeyde şöyle dedi: Hz.","Osman döneminde Ebu Abdurrahman Müslümanlara Kur'an öğretti. Haccac dönemine kadar da bu faaliyetini sürdürdü. Bu konuda şöyle demiştir: \"Kur'an'ın faziletine ilişkin nakledilen hadis,","benim buraya oturup Kur'an öğretmeme vesile oldu.\" Diğer tahric edenler: Tirmizî, Fedail-ül Kur’ân; İbn Mâce,i Mukaddime"],"ur":["ہم سے حجاج بن منہال نے بیان کیا، کہا ہم سے شعبہ بن حجاج نے بیان کیا، کہا کہ مجھے علقمہ بن مرثد نے خبر دی، انہوں نے سعد بن عبیدہ سے سنا، انہوں نے ابوعبدالرحمٰن سلمی سے اور انہوں نے عثمان بن عفان رضی اللہ عنہ سے،","انہوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ تم میں سب سے بہتر وہ ہے جو قرآن مجید پڑھے اور پڑھائے۔ سعد بن عبیدہ نے بیان کیا کہ ابوعبدالرحمٰن سلمی نے لوگوں کو عثمان رضی اللہ عنہ کے زمانہ خلافت سے حجاج بن یوسف کے عراق کے گورنر ہونے تک قرآن مجید کی تعلیم دی۔ وہ کہا کرتے تھے کہ یہی حدیث ہے جس نے مجھے اس جگہ ( قرآن مجید پڑھانے کے لیے ) بٹھا رکھا ہے۔",""],"id":["Telah menceritakan kepada kami [Hajjaj bin Minhal] Telah menceritakan kepada kami [Syu'bah] ia berkata, Telah mengabarkan kepadaku ['Alqamah bin Martsad] Aku mendengar [Sa'd bin Ubaidah] dari [Abu Abdurrahman As Sulami] dari [Utsman] radliallahu 'anhu,","dari Nabi shallallahu 'alaihi wasallam, beliau bersabda: \"Orang yang paling baik di antara kalian adalah seorang yang belajar Al Qur`an dan mengajarkannya.\" Abu Abdirrahman membacakan (Al Qur`an) pada masa Utsman hingga Hajjaj pun berkata,","\"Dan hal itulah yang menjadikanku duduk di tempat dudukku ini"],"bn":["‘উসমান (রাঃ) সূত্রে নবী সাল্লাল্লাহু ‘আলাইহি ওয়াসাল্লাম হতে বর্ণিত। তিনি বলেন,","তোমাদের মধ্যে ঐ ব্যক্তি সবচেয়ে উত্তম যে কুরআন শিখে এবং অন্যকে শিখায়। [৫০২৮] (আধুনিক প্রকাশনীঃ ৪৬৫৩,","ইসলামিক ফাউন্ডেশনঃ)"],"ru":["Передают со слов ‘Усмана, да будет доволен им Аллах,","что Пророк ﷺ сказал: «Лучшим из вас является тот,","кто изучает Коран и учит ему (других)»"]}},"h_kalima":{"src":"bukhari 2989","w":["قَالَ","رَسُولُ","اللَّهِ","صلى","الله","عليه","وسلم","كُلُّ","سُلاَمَى","مِنَ","النَّاسِ","عَلَيْهِ","صَدَقَةٌ","كُلَّ","يَوْمٍ","تَطْلُعُ","فِيهِ","الشَّمْسُ،","يَعْدِلُ","بَيْنَ","الاِثْنَيْنِ","صَدَقَةٌ،","وَيُعِينُ","الرَّجُلَ","عَلَى","دَابَّتِهِ،","فَيَحْمِلُ","عَلَيْهَا،","أَوْ","يَرْفَعُ","عَلَيْهَا","مَتَاعَهُ","صَدَقَةٌ،","وَالْكَلِمَةُ","الطَّيِّبَةُ","صَدَقَةٌ،","وَكُلُّ","خَطْوَةٍ","يَخْطُوهَا","إِلَى","الصَّلاَةِ","صَدَقَةٌ،","وَيُمِيطُ","الأَذَى","عَنِ","الطَّرِيقِ","صَدَقَةٌ."],"p":[[0,12],[12,18],[18,26],[26,33],[33,42],[42,47]],"m":{"en":["Narrated Abu Huraira:Allah's Messenger (ﷺ) said,","\"There is a (compulsory) Sadaqa (charity) to be given for every joint of the human body (as a sign of gratitude to Allah) everyday the sun rises.","To judge justly between two persons is regarded as Sadaqa,","and to help a man concerning his riding animal by helping him to ride it or by lifting his luggage on to it, is also regarded as Sadaqa,","and (saying) a good word is also Sadaqa, and every step taken on one's way to offer the compulsory prayer (in the mosque) is also Sadaqa and to remove a harmful thing from the way is also Sadaqa",""],"fr":["Rapporté par Abu Huraira : Le Messager d’Allah (ﷺ) a dit :","« Il y a une aumône obligatoire pour chaque articulation du corps humain chaque jour où le soleil se lève.","Rendre justice entre deux personnes est une aumône,","aider quelqu’un avec sa monture en l’aidant à monter ou à porter ses affaires dessus est aussi une aumône,","dire une bonne parole est une aumône, chaque pas fait pour aller prier à la mosquée est une aumône,","et enlever un obstacle du chemin est aussi une aumône. »"],"tr":["Ebu Hureyre r.a.'in naklettiğine göre Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurmuştur:","\"Bir kimsenin parmaklarındaki boğumların her birinin,","üzerine güneşin doğduğu her gün için sadakası vardır. İki kişinin arasını bulup aralarında adaletle karar vermek bir sadakadır.","Bir kimsenin hayvanına binmesine veya eşyalarını yüklemesine yardımcı olmak sadakadır.","Güzel söz sadakadır,","namaz kılmak üzere giderken atılan her adım sadakadır ve yol üzerindeki bir engeli kaldırmak sadakadır"],"ur":["ہم سے اسحاق بن منصور نے بیان کیا، کہا ہم کو عبدالرزاق نے خبر دی، کہا ہم کو معمر نے خبر دی،","","انہیں ہمام نے اور ان سے ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ”انسان کے ہر ایک جوڑ پر صدقہ لازم ہوتا ہے۔ ہر دن جس میں سورج طلوع ہوتا ہے۔ پھر اگر وہ انسانوں کے درمیان انصاف کرے تو یہ بھی ایک صدقہ ہے اور کسی کو سواری کے معاملے میں اگر مدد پہنچائے،","","اس طرح پر کہ اسے اس پر سوار کرائے یا اس کا سامان اٹھا کر رکھ دے تو یہ بھی ایک صدقہ ہے اور اچھی بات منہ سے نکالنا بھی ایک صدقہ ہے اور ہر قدم جو نماز کے لیے اٹھتا ہے وہ بھی صدقہ ہے اور اگر کوئی راستے سے کسی تکلیف دینے والی چیز کو ہٹا دے تو وہ بھی ایک صدقہ ہے۔“",""],"id":["Telah bercerita kepadaku [Ishaq] telah mengabarkan kepada kami ['Abdur Rozzaq] telah mengabarkan kepada kami [Ma'mar] dari [Hammam] dari [Abu Hurairah radliallahu 'anhu] berkata;","Rasulullah shallallahu 'alaihi wasallam bersabda:","","\"Setiap ruas tulang pada manusia wajib atasnya shadaqah dan setiap hari terbitnya matahari seseorang yang mendamaikan antara dua orang yang bertikai adalah shadaqah dan menolong seseorang untuk menaiki hewan tunggangannya lalu mengangkat barang-barangnya ke atas hewan tungganyannya adalah shadaqah dan ucapan yang baik adalah shadaqah dan setiap langkah yang dijalankan munuju shalat adalah shadaqah dan menyingkirkan sesuatu yang bisa menyakiti atau menghalngi orang dari jalan adalah shadaqah","",""],"bn":["আবূ হুরাইরাহ্ (রাঃ) হতে বর্ণিত। তিনি বলেন, আল্লাহর রাসূল সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেন যে,","মানুষের প্রত্যেক জোড়ার প্রতি সদাকাহ রয়েছে,","প্রতি দিন যাতে সূর্য উদিত হয় দু’জন লোকের মধ্যে সুবিচার করাও সদাকাহ,","কাউকে সাহায্য করে সাওয়ারীতে আরোহণ করিয়ে দেয়া বা তার উপরে তার মালপত্র তুলে দেয়াও সদাকাহ, ভাল কথাও সদাকাহ,","সালাত আদায়ের উদ্দেশে পথ চলায় প্রতিটি কদমেও সদাকাহ, রাস্তা থেকে কষ্টদায়ক বস্তু অপসারণ করাও সদাকাহ। (২৭০৭) (মুসলিম ১২/১৭ হাঃ ১০০৯,","আহমাদ ৮১৮৯) (আধুনিক প্রকাশনীঃ ২৭৬৮, ইসলামিক ফাউন্ডেশনঃ)"],"ru":["Сообщается со слов Абу Хурайры, да будет доволен им Аллах, что Посланник Аллаха ﷺ сказал:","«На каждом суставе человека лежит обязанность раздавать милостыню каждый день,","в который восходит солнце. Если он справедливо рассудит между двумя, это будет милостыней.","Если он поможет человеку взобраться на его верховое животное или поднимет на верховое животное его вещи, это будет милостыней.","И благое слово также является милостыней. И каждый шаг, который он делает на пути к молитве, является милостыней. И если он уберёт с дороги то,","что мешает (прохожим), это также будет милостыней»"]}},"h_rahma":{"src":"bukhari 7376","w":["قَالَ","رَسُولُ","اللَّهِ","صلى","الله","عليه","وسلم","لاَ","يَرْحَمُ","اللَّهُ","مَنْ","لاَ","يَرْحَمُ","النَّاسَ."],"p":[[0,14]],"m":{"en":["Narrated Jarir bin `Abdullah:Allah's Messenger (ﷺ) said, \"Allah will not be merciful to those who are not merciful to mankind"],"fr":["Rapporté par Jarir bin `Abdullah : Le Messager d’Allah (ﷺ) a dit : « Allah ne fera pas miséricorde à ceux qui ne sont pas miséricordieux envers les gens. »"],"tr":["Cerir b. Abdullah r.a.'ın nakline göre Resulullah Sallallahu Aleyhi ve Sellem: \"Allah insanlara merhamet etmeyene, merhamet etmez.\" buyurmuştur"],"ur":["ہم سے محمد نے بیان کیا، انہوں نے کہا ہم کو ابومعاویہ نے خبر دی، انہیں اعمش نے، انہیں زید بن وہب اور ابوظبیان نے اور ان سے جریر بن عبداللہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ”جو لوگوں پر رحم نہیں کھاتا اللہ بھی اس پر رحم نہیں کھاتا۔“"],"id":["Telah menceritakan kepada kami [Muhammad bin Salam] telah menceritakan kepada kami [Abu Mu'awiyah] dari [Al A'masy] dari [Zaid bin Wahb] dan [Abu dlabyan] dari [Jarir bin Abdullah] berkata, \"Rasulullah shallallahu 'alaihi wasallam bersabda: \"Allah tak bakalan menyayangi siapa saja yang tidak menyayangi manusia"],"bn":["জারীর ইবনু ‘আবদুল্লাহ্ (রাঃ) হতে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ আল্লাহ্ তার প্রতি রহম করেন না, যে মানুষের প্রতি রহম করে না। [৬০১৩] (আধুনিক প্রকাশনী- ৬৮৬০, ইসলামিক ফাউন্ডেশন)"],"ru":["Сообщается, что Джарир ибн ‘Абдуллах (да будет доволен Аллах ими обоими) сказал: «Посланник Аллаха ﷺ сказал: “Не помилует Аллах того, кто сам не проявляет милосердия к людям”»"]}},"h_adwam":{"src":"bukhari 5861","w":["أَنَّ","النَّبِيَّ","صلى","الله","عليه","وسلم","كَانَ","يَحْتَجِرُ","حَصِيرًا","بِاللَّيْلِ","فَيُصَلِّي،","وَيَبْسُطُهُ","بِالنَّهَارِ","فَيَجْلِسُ","عَلَيْهِ،","فَجَعَلَ","النَّاسُ","يَثُوبُونَ","إِلَى","النَّبِيِّ","صلى","الله","عليه","وسلم","فَيُصَلُّونَ","بِصَلاَتِهِ","حَتَّى","كَثُرُوا","فَأَقْبَلَ","فَقَالَ","يَا","أَيُّهَا","النَّاسُ","خُذُوا","مِنَ","الأَعْمَالِ","مَا","تُطِيقُونَ،","فَإِنَّ","اللَّهَ","لاَ","يَمَلُّ","حَتَّى","تَمَلُّوا،","وَإِنَّ","أَحَبَّ","الأَعْمَالِ","إِلَى","اللَّهِ","مَا","دَامَ","وَإِنْ","قَلَّ."],"p":[[0,11],[11,23],[23,35],[35,44],[44,53]],"m":{"en":["Narrated `Aisha:The Prophet (ﷺ) used to construct a loom with a Hasir at night m order to pray therein,","and during the day he used to spread it out and sit on it. The people started coming to the Prophet (ﷺ) at night to offer the prayer behind him When their number increased,","the Prophet (ﷺ) faced them and said. O people!","Do only those good deeds which you can do, for Allah does not get tired (of giving reward) till you get tired,","and the best deeds to Allah are the incessant ones though they were few"],"fr":["Rapporté par `Aisha : Le Prophète (ﷺ) fabriquait un rideau avec un Hasir la nuit pour y prier,","et pendant la journée il l’étendait et s’asseyait dessus. Les gens ont commencé à venir prier derrière lui la nuit. Quand ils sont devenus nombreux,","le Prophète (ﷺ) s’est tourné vers eux et a dit : Ô gens ! Faites seulement les bonnes actions que vous pouvez accomplir,","car Allah ne se lasse pas de récompenser tant que vous ne vous lassez pas,","et les meilleures actions pour Allah sont celles qui sont régulières, même si elles sont peu nombreuses"],"tr":["Aişe r.anha'dan rivayete göre \"Nebi Sallallahu Aleyhi ve Sellem geceleyin bir hasırı hücre edinir, namaz kılardı. Gündüzün. de onu yayar, üzerine otururdu.","Bu sefer insanlar da Nebi Sallallahu Aleyhi ve Sellem'in yanına gitmeye ve ona uyarak namaz kılmaya başladılar. Nihayet sayıları çoğaldı. Bunun üzerine onlara dönerek şöyle buyurdu: Ey insanlar, amellerden güç yetirebileceğiniz kadarını alın. Şüphesiz Allah sizler usanmadığınız sürece (size sevap yazmaktan) vazgeçmez.","Hiç şüphesiz Allah'ın ameller arasında en sevdiği, az dahi olsa devamlı alanıdır.\" Fethu'l-Bari Açıklaması: \"Hasır ve benzeri şeyler üzerine oturmak.\" Hasır ne olduğu bilinen bir şeydir. Hasır, se af denilen çubuklardan ve benzerlerinden yapılır.","\"Ve benzeri\" lafzından maksadı ise yere serilen, pek değerli olmayan şeylerdir. \"Geldiklerini\", döndüklerini ... Yine bu hadisin açıklaması İman bölümünde geçmiş bulunmaktadır.","\"Şüphesiz Allah'ın ameller arasında en sevdiği, az dahi olsa devamlı alanıdır.\" Yani amelde bulunan kimsenin hayatı boyunca devam edenidir"],"ur":["مجھ سے محمد بن ابی بکر نے بیان کیا، انہوں نے کہا ہم سے معتمر نے بیان کیا، ان سے عبیداللہ نے بیان کیا، ان سے سعید بن ابی سعید نے بیان کیا،","","ان سے ابوسلمہ بن عبدالرحمٰن نے اور ان سے عائشہ رضی اللہ عنہا نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم رات میں چٹائی کا گھیرا بنا لیتے تھے اور ان گھیرے میں نماز پڑھتے تھے اور اسی چٹائی کو دن میں بچھاتے تھے اور اس پر بیٹھتے تھے پھر لوگ ( رات کی نماز کے وقت ) نبی کریم صلی اللہ علیہ وسلم کے پاس جمع ہونے لگے اور نبی کریم صلی اللہ علیہ وسلم کی نماز کی اقتداء کرنے لگے جب مجمع زیادہ بڑھ گیا تو نبی کریم صلی اللہ علیہ وسلم متوجہ ہوئے اور فرمایا کہ لوگو!","","عمل اتنے ہی کیا کرو جتنی کہ تم میں طاقت ہو کیونکہ اللہ تعالیٰ ( اجر دینے سے ) نہیں تھکتا مگر تم ( عمل سے ) تھک جاتے ہو اور اللہ کی بارگاہ میں سب سے زیادہ پسند وہ عمل ہے جسے پابندی سے ہمیشہ کیا جائے، خواہ وہ کم ہی ہو۔"],"id":["","Telah menceritakan kepadaku [Muhammad bin Abu Bakr] telah menceritakan kepada kami [Mu'tamir] dari ['Ubaidullah] dari [Sa'id bin Abu Sa'id] dari [Abu Salamah bin Abdurrahman] dari [Aisyah] radliallahu 'anha bahwa pada suatu malam Nabi shallallahu 'alaihi wasallam pernah membuat sekat (di dalam masjid) dengan tikar lalu shalat di dalamnya, dan menghamparkannya di siang hari untuk duduk,","ternyata orang-orang berkumpul di sekeliling Nabi shallallahu 'alaihi wasallam untuk mengerjakan shalat sebagaimana beliau shalat, hingga orang-orang semakin banyak,","lalu beliau menghadap (kepada mereka) dan bersabda: \"Wahai sekalian manusia, beramalah menurut yang kalian sanggupi, sesungguhnya Allah tidak akan bosan sehingga kalian merasa bosan,","sesungguhnya amalan yang paling dicintai Allah adalah yang dikerjakan secara kontinyu walaupun sedikit"],"bn":["‘আয়িশাহ (রাঃ) হতে বর্ণিত যে,","নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম রাতের বেলা চাটাই দিয়ে ঘেরাও দিয়ে সালাত আদায় করতেন। আর দিনের বেলা তা বিছিয়ে তার উপর বসতেন। লোকজন নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর নিকট একত্রিত হয়ে তাঁর সঙ্গে সালাত আদায় করতে লাগল। এমনকি বহু লোক একত্রিত হল। তখন নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাদের উদ্দেশে বললেনঃ হে লোক সকল!","তোমরা ‘আমল করতে থাক তোমাদের সামর্থ্য অনুযায়ী। কারণ,","আল্লাহ তা‘আলা ক্লান্ত হন না, বরং তোমরাই ক্লান্ত হয়ে পড়বে। আর আল্লাহর নিকট ঐ ‘আমল সবচেয়ে প্রিয়,","যা সর্বদা করা হয়, তা কম হলেও। [৭২৯] (আধুনিক প্রকাশনী- ৫৪৩৫, ইসলামিক ফাউন্ডেশন)"],"ru":["Сообщается, что ‘Аиша, да будет доволен ею Аллах, рассказала о том, что у Пророка ﷺ была циновка,","которую он подготавливал для себя ночью и совершал на ней молитву, а днём он расстилал её для сидения на ней. (Через некоторое время) люди стали собираться возле Пророка ﷺ и совершать такую же молитву,","как он, что привело к тому, что их количество увеличилось. (Пророк ﷺ) повернулся к ним и сказал: “О люди!","Совершайте из деяний те, что вы способны осилить, ибо Аллаху не наскучит, пока не наскучит вам! И поистине,","наиболее любимым для Аллаха являются те деяния, что совершаются постоянно, даже если их мало!”»"]}},"h_bunyan":{"src":"bukhari 481","w":["عَنْ","أَبِي","مُوسَى،","عَنِ","النَّبِيِّ","صلى","الله","عليه","وسلم","قَالَ","إِنَّ","الْمُؤْمِنَ","لِلْمُؤْمِنِ","كَالْبُنْيَانِ،","يَشُدُّ","بَعْضُهُ","بَعْضًا.","وَشَبَّكَ","أَصَابِعَهُ."],"p":[[0,12],[12,19]],"m":{"en":["Narrated Abu Musa:The Prophet (ﷺ) said, \"A faithful believer to a faithful believer is like the bricks of a wall,","enforcing each other.\" While (saying that) the Prophet (ﷺ) clasped his hands, by interlacing his fingers"],"fr":["Rapporté par Abu Musa : Le Prophète (ﷺ) a dit : « Un croyant envers un autre croyant est comme les briques d’un mur,","elles se soutiennent mutuellement. » En disant cela, le Prophète (ﷺ) a joint ses mains en entrelaçant ses doigts"],"tr":["Ebu Musa Nebi Sallallahu Aleyhi ve Sellem'in parmaklarını birbirine kenetleyerek şöyle buyurduğunu nakletmiştir:","\"Mu'min, mu'min için, parçaları birbirini sıkı sıkıya tutan bir bina gibidir. Tekrar:"],"ur":["ہم سے خلاد بن یحییٰ نے بیان کیا، کہا ہم سے سفیان ثوری نے ابی بردہ بن عبداللہ بن ابی بردہ سے، انہوں نے اپنے دادا (ابوبردہ) سے،","انہوں نے ابوموسیٰ اشعری رضی اللہ عنہ سے۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے کہ آپ صلی اللہ علیہ وسلم نے فرمایا ایک مومن دوسرے مومن کے لیے عمارت کی طرح ہے کہ اس کا ایک حصہ دوسرے حصہ کو قوت پہنچاتا ہے۔ اور آپ صلی اللہ علیہ وسلم نے ایک ہاتھ کی انگلیوں کو دوسرے ہاتھ کی انگلیوں میں داخل کیا۔"],"id":["Telah menceritakan kepada kami [Khallad bin Yahya] berkata, telah menceritakan kepada kami [Sufyan] dari [Abu Burdah bin 'Abdullah bin Abu Burdah] dari [Kakeknya] dari [Abu Musa] dari Nabi shallallahu 'alaihi wasallam,","beliau bersabda: \"Sesungguhnya seorang mukmin dengan mukmin lainnya seperti satu bangunan yang saling menguatkan satu sama lain.\" kemudian beliau menganyam jari jemarinya"],"bn":["আবূ মূসা (রাযি.) হতে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ একজন মু’মিন আরেকজন মু‘মিনের জন্যে ইমারতস্বরূপ,","যার এক অংশ অপর অংশকে শক্তিশালী করে থাকে। এ ব’লে তিনি তার হাতের আঙুলগুলো একটার মধ্যে আরেকটা প্রবেশ করালেন। (২৪৪৬, ৬০২৬; মুসলিম ৫৪/১৭, হাঃ ২৫৮৫, আহমাদ ১৯৬৪৪) (আধুনিক প্রকাশনীঃ ৪৫৯, ইসলামিক ফাউন্ডেশনঃ)"],"ru":["Передают со слов Абу Мусы, да будет доволен им Аллах, о том, что (однажды) Пророк ﷺ сказал: «Поистине,","(в отношениях) друг с другом верующие подобны строению, отдельные части которого укрепляют друг друга», и (,сказав это,) он переплёл между собой пальцы (своих рук)"]}},"h_ilm":{"src":"muslim 6853","w":["وَمَنْ","سَلَكَ","طَرِيقًا","يَلْتَمِسُ","فِيهِ","عِلْمًا","سَهَّلَ","اللَّهُ","لَهُ","بِهِ","طَرِيقًا","إِلَى","الْجَنَّةِ","وَمَا","اجْتَمَعَ","قَوْمٌ","فِي","بَيْتٍ","مِنْ","بُيُوتِ","اللَّهِ","يَتْلُونَ","كِتَابَ","اللَّهِ","وَيَتَدَارَسُونَهُ","بَيْنَهُمْ","إِلاَّ","نَزَلَتْ","عَلَيْهِمُ","السَّكِينَةُ","وَغَشِيَتْهُمُ","الرَّحْمَةُ","وَحَفَّتْهُمُ","الْمَلاَئِكَةُ","وَذَكَرَهُمُ","اللَّهُ","فِيمَنْ","عِنْدَهُ","وَمَنْ","بَطَّأَ","بِهِ","عَمَلُهُ","لَمْ","يُسْرِعْ","بِهِ","نَسَبُهُ."],"p":[[0,12],[12,24],[24,36],[36,46]],"m":{}},"h_taqwa":{"src":"tirmidhi 1987","w":["عَنْ","أَبِي","ذَرٍّ،","قَالَ","قَالَ","لِي","رَسُولُ","اللَّهِ","صلى","الله","عليه","وسلم","اتَّقِ","اللَّهَ","حَيْثُمَا","كُنْتَ","وَأَتْبِعِ","السَّيِّئَةَ","الْحَسَنَةَ","تَمْحُهَا","وَخَالِقِ","النَّاسَ","بِخُلُقٍ","حَسَنٍ."],"p":[[0,12],[12,24]],"m":{"en":["Abu Dharr said:\"The Messenger of Allah said to me:","'Have Taqwa of Allah wherever you are, and follow an evil deed with a good one to wipe it out, and treat the people with good behavior"],"tr":["Ebû Zerr (radıyallahü anh)’den rivâyete göre, Rasûlüllah (sallallahü aleyhi ve sellem) şöyle buyurmuştur: “Nerede olursan ol Allah’a karşı sorumluluk bilinciyle yaşa,","işlediğin bir günahın arkasından hemen bir sevap işle ki onu imha edip yok etsin. İnsanlara güzel ahlakla muamele et.” (Dârimî, Rıkak: 71) Bu konuda Ebû Hüreyre’den de hadis rivâyet edilmiştir. Bu hadis hasen sahihtir"],"ur":["ابوذر رضی الله عنہ کہتے ہیں کہ کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جہاں بھی رہو اللہ سے ڈرو،","برائی کے بعد ( جو تم سے ہو جائے ) بھلائی کرو جو برائی کو مٹا دے ۱؎ اور لوگوں کے ساتھ حسن اخلاق سے پیش آؤ“۔ امام ترمذی کہتے ہیں: ۱- یہ حدیث حسن صحیح ہے، ۲- اس باب میں ابوہریرہ رضی الله عنہ سے بھی روایت ہے۔"],"id":["Telah menceritakan kepada kami [Muhammad bin Basysyar], telah menceritakan kepada kami [Abdurrahman bin Mahdi], telah menceritakakan kepada kami [Sufyan] dari [Habib bin Abu Tsabit] dari [Maimun bin Abu Syabib] dari [Abu Dzar] ia berkata; Rasulullah shallallahu 'alaihi wasallam pernah bersabda kepadaku:","\"Bertakwalah kamu kepada Allah dimana saja kamu berada dan ikutilah setiap keburukan dengan kebaikan yang dapat menghapuskannya, serta pergauilah manusia dengan akhlak yang baik.\" Hadits semakna juga diriwayatkan oleh Abu Hurairah. Abu Isa berkata; Ini adalah hadits hasan shahih. Telah menceritakan kepada kami [Mahmud bin Ghailan] Telah menceritakan kepada kami [Abu Ahmad] dan [Abu Nu'aim] dari [Sufyan] dari [Habib] dengan isnad ini semisalnya. Telah menceritakan kepada kami [Waki'] dari [Sufyan] dari [Habib bin Tsabit] dari [Maimun bin Abu Syabib] dari [Mu'adz bin Jabal] dari Nabi shallallahu 'alaihi wasallam semisalnya. Mahmud berkata; Yang shahih adalah haditsnya Abu Dzar"],"bn":["। আবূ যার (রাঃ) হতে বর্ণিত আছে, তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম আমাকে বলেছেনঃ তুমি যেখানেই থাক আল্লাহ্ তা'আলাকে ভয় কর, মন্দ কাজের পরপরই ভাল কাজ কর, তাতে মন্দ দূরীভূত হয়ে যাবে এবং মানুষের সাথে উত্তম আচরণ কর। হাসান, মিশকাত (৫০৮৩),","রাওযুন নায়ীর (৮৫৫) আবূ হুরাইরা (রাঃ) হতেও এ অনুচ্ছেদে হাদীস বর্ণিত আছে। আবূ ঈসা বলেন, এ হাদীসটি হাসান সহীহ্। মাহমূদ ইবনু গাইলান-আবূ আহমাদ হতে, তিনি আবু নুয়াইম হতে, তিনি সুফিয়ান হতে, তিনি হাবীব (রাহঃ) হতে এই সূত্রে একইরকম বর্ণনা করেছেন। মাহমূদ-ওয়াকী হতে, তিনি সুফিয়ান হতে, তিনি হাবীব ইবনু আবী সাবিত হতে, তিনি মাইমূন ইবনু আবী শাবীব হতে, তিনি মুআয ইবনু জাবাল (রাঃ) হতে, তিনি রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হতে একইরকম বর্ণনা করেছেন। মাহমূদ বলেন, আবূ যর (রাঃ)-এর হাদীসটি সহীহ।"]}},"h_yassiru":{"src":"bukhari 69","w":["عَنْ","أَنَسٍ،","عَنِ","النَّبِيِّ","صلى","الله","عليه","وسلم","قَالَ","يَسِّرُوا","وَلاَ","تُعَسِّرُوا،","وَبَشِّرُوا","وَلاَ","تُنَفِّرُوا."],"p":[[0,12],[12,15]],"m":{"en":["Narrated Anas bin Malik:The Prophet (ﷺ) said, \"Facilitate things to people (concerning religious matters),","and do not make it hard for them and give them good tidings and do not make them run away (from Islam)"],"fr":["Rapporté par Anas bin Malik : Le Prophète (ﷺ) a dit : « Rendez les choses faciles aux gens (concernant la religion), ne les rendez pas difficiles,","annoncez-leur de bonnes nouvelles et ne les faites pas fuir (de l’islam). »"],"tr":["Enes r.a. Nebi (Sallallahu aleyhi ve Sellem)'in şöyle söylediğini rivayet etmiştir: \"Kolaylaştırın, zorlaştırmayım.","Müjdeleyin, nefret ettirmeyin. Tekrar:"],"ur":["ہم سے محمد بن بشار نے بیان کیا، ان سے یحییٰ بن سعید نے، ان سے شعبہ نے، ان سے ابوالتیاح نے، انہوں نے انس بن مالک رضی اللہ عنہ سے نقل کیا، وہ رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا،","آسانی کرو اور سختی نہ کرو اور خوش کرو اور نفرت نہ دلاؤ۔"],"id":["Telah menceritakan kepada kami [Muhammad bin Basysyar] berkata, telah menceritakan kepada kami [Yahya bin Sa'id] berkata, telah menceritakan kepada kami [Syu'bah] Telah menceritakan kepadaku [Abu At Tayyah] dari [Anas bin Malik] dari Nabi shallallahu 'alaihi wasallam,","beliau bersabda: \"permudahlah dan jangan persulit, berilah kabar gembira dan jangan membuat orang lari"],"bn":["আনাস (রাযি.) থেকে বর্ণিত, নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ তোমরা সহজ পন্থা অবলম্বন কর, কঠিন পন্থা অবলম্বন করো না, মানুষকে সুসংবাদ দাও, বিরক্তি সৃষ্টি করো না। (৬১২৫;","মুসলিম ৩২/৩ হাঃ ১৭৩৪, আহমাদ ১৩১৭৪) (আধুনিক প্রকাশনীঃ ৬৯, .ফা)"],"ru":["Передают со слов Анаса, да будет доволен им Аллах, что Пророк ﷺ сказал: «Облегчайте, а не создавайте затруднения, радуйте (людей) добрыми вестями,","а не внушайте отвращение (к Исламу)»"]}},"h_shadid":{"src":"bukhari 6114","w":["أَنَّ","رَسُولَ","اللَّهِ","صلى","الله","عليه","وسلم","قَالَ","لَيْسَ","الشَّدِيدُ","بِالصُّرَعَةِ،","إِنَّمَا","الشَّدِيدُ","الَّذِي","يَمْلِكُ","نَفْسَهُ","عِنْدَ","الْغَضَبِ."],"p":[[0,11],[11,18]],"m":{"en":["Narrated Abu Huraira:Allah's Messenger (ﷺ) said, \"The strong is not the one who overcomes the people by his strength,","but the strong is the one who controls himself while in anger"],"fr":["Rapporté par Abu Huraira : Le Messager d'Allah (ﷺ) a dit : « Le fort n’est pas celui qui l’emporte sur les autres par sa force,","mais celui qui sait se maîtriser lorsqu’il est en colère. »"],"tr":["Ebu Hureyre r.a.'dan rivayete göre; \"Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurdu: Güçlü,","kuvvetli kişi rakiplerinin sırtını yerine getiren kişi değildir. Asıl güçlü kuvvetli kişi, öfkelendiği vakit nefsine hakim olabilendir"],"ur":["ہم سے عبداللہ بن یوسف نے بیان کیا، انہوں نے کہا ہم کو امام مالک نے خبر دی، انہیں ابن شہاب نے،","انہیں سعید بن مسیب نے اور انہیں ابوہریرہ رضی اللہ عنہ نے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ”پہلوان وہ نہیں ہے جو کشتی لڑنے میں غالب ہو جائے بلکہ اصلی پہلوان تو وہ ہے جو غصہ کی حالت میں اپنے آپ پر قابو پائے بے قابو نہ ہو جائے۔“"],"id":["Telah menceritakan kepada kami [Abdullah bin Yusuf] telah mengabarkan kepada kami [Malik] dari [Ibnu Syihab] dari [Sa'id bin Musayyib] dari [Abu Hurairah] radliallahu 'anhu bahwa Rasulullah shallallahu 'alaihi wasallam bersabda:","\"Tidaklah orang yang kuat adalah orang yang pandai bergulat, tapi orang yang kuat adalah orang yang dapat menahan nafsunya ketika ia marah"],"bn":["لِقَوْلِ اللَّهِ تَعَالَى: (وَالَّذِينَ يَجْتَنِبُونَ كَبَائِرَ الإِثْمِ وَالْفَوَاحِشَ وَإِذَا مَا غَضِبُوا هُمْ يَغْفِرُونَ)، (الَّذِينَ يُنْفِقُونَ فِي السَّرَّاءِ وَالضَّرَّاءِ وَالْكَاظِمِينَ الْغَيْظَ وَالْعَافِينَ عَنِ النَّاسِ وَاللَّهُ يُحِبُّ الْمُحْسِنِينَ) মহান আল্লাহর বাণীঃ যারা বড় বড় পাপ এবং অশ্লীল কার্যকলাপ হতে বেঁচে চলে এবং রাগান্বিত হয়েও ক্ষমা করে। (সূরাহ আশ্-শূরা ৪২/৩৭)। এবং আল্লাহর বাণী) যারা সচ্ছল ও অসচ্ছল অবস্থায় আল্লাহর পথে) ব্যয় করে এবং যারা ক্রোধ সংবরণকারী এবং মানুষের প্রতি ক্ষমাশীল,","আল্লাহ সৎকর্মশীলদের ভালবাসেন। (সূরাহ আলে ইমরান ৩/১৩৪)। ৬১১৪. আবূ হুরাইরাহ হতে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ প্রকৃত বীর সে নয়, যে কাউকে কুস্তিতে হারিয়ে দেয়। বরং সেই আসল বীর, যে রাগের সময় নিজেকে নিয়ন্ত্রণে রাখতে পারে। [মুসলিম ৪৫/৩০, হাঃ ২৬০৯, আহমাদ ৭২২৩] (আধুনিক প্রকাশনী- ৫৬৭৪, ইসলামিক ফাউন্ডেশন)"],"ru":["Передают со слов Абу Хурайры, да будет доволен им Аллах, что Посланник Аллаха ﷺ сказал: «Не тот силён,","кто побеждает часто, силён лишь тот, кто (способен) владеть собой в гневе»"]}},"h_yanih":{"src":"tirmidhi 2317","w":["عَنْ","أَبِي","هُرَيْرَةَ،","قَالَ","قَالَ","رَسُولُ","اللَّهِ","صلى","الله","عليه","وسلم","مِنْ","حُسْنِ","إِسْلاَمِ","الْمَرْءِ","تَرْكُهُ","مَا","لاَ","يَعْنِيهِ."],"p":[[0,12],[12,19]],"m":{"en":["Abu Hurairah narrated that the Messenger of Allah (s.a.w) said:\"Indeed among the excellence of a person's Islam is that he leaves what does not concern him",""],"tr":["Ebû Hureyre (r.a.)’den rivâyete göre, Rasûlullah (Sallallahu aleyhi ve Sellem) şöyle buyurmuştur: “Bir kimsenin lüzumsuz ve boş şeyleri terk etmesi iyi bir Müslüman oluşundandır.” Diğer tahric: İbn Mâce,","Fiten (h.no:3976) Tirmizî: Bu hadis garib olup bu hadisi Ebû Seleme’nin Ebû Hüreyre’den bu şekilde rivâyetiyle bilmekteyiz. İBN-İ MACE HADİSİ VE İZAH İÇİN TIKLA"],"ur":["ابوہریرہ رضی الله عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”کسی شخص کے اسلام کی خوبی یہ ہے کہ وہ لایعنی اور فضول باتوں کو چھوڑ دے“ ۱؎۔ امام ترمذی کہتے ہیں: ۱- یہ حدیث غریب ہے،","۲- ہم اس حدیث کو ابوسلمہ کی روایت سے جسے وہ ابوہریرہ رضی الله عنہ سے اور ابوہریرہ رضی الله عنہ نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے ہیں صرف اسی سند سے جانتے ہیں۔"],"id":["Telah menceritakan kepada kami [Ahmad bin Nashr An Naisaburi] dan yang lainnya telah menceritakan kepada kami mereka berkata bahwa [Abu Mushir] telah menceritakan kepada kami dari [Isma'il bin 'Abdullah bin Sama'ah] dari [Al Auza'i] dari [Qurroh] dari [Az Zuhri] dari [Abu Salamah] dari [Abu Hurairah] dia berkata bahwa Rasulullah Shallallahu 'alaihi wa salam bersabda:","\" Di antara tanda baiknya Islam seseorang adalah meninggalkan sesuatu yang tidak bermanfaat baginya.\" Dia berkata: Hadits ini gharib, kami tidak mengetahuinya dari Hadits Abu Salamah dari Abu Hurairah dari Nabi Shallallahu 'alaihi wa Salam kecuali dari Jalur sanad ini"],"bn":["। আবূ হুরাইরা (রাঃ) হতে বর্ণিত আছে, তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ কোন ব্যক্তির ইসলামের অন্যতম সৌন্দর্য হলো অনর্থক আচরণ ত্যাগ করা। সহীহ, ইবনু মা-জাহ (৩৯৭৬)। আবূ ঈসা বলেন,","এ হাদীসটি গারীব। আমরা শুধুমাত্র আবূ সালামা হতে আবূ হুরাইরা (রাঃ)-এর বরাতে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লামের সূত্রে বর্ণিত রিওয়ায়াত হিসাবে এটি জেনেছি।"]}},"du_huda":{"src":"muslim 6904","w":["عَنْ","عَبْدِ","اللَّهِ،","عَنِ","النَّبِيِّ","صلى","الله","عليه","وسلم","أَنَّهُ","كَانَ","يَقُولُ","اللَّهُمَّ","إِنِّي","أَسْأَلُكَ","الْهُدَى","وَالتُّقَى","وَالْعَفَافَ","وَالْغِنَى."],"p":[[0,12],[12,19]],"m":{"en":["Abdullah reported that Allah's Messenger (ﷺ) used to supplicate (in these words):\" O Allah.","I beg of Thee the right guidance, safeguard against evils, chastity and freedom from want"],"fr":["Rapporté par Abdullah : Le Messager d’Allah ﷺ invoquait ainsi : « Ô Allah,","je Te demande la bonne direction, la protection contre le mal, la chasteté et l’indépendance. »"],"tr":["Bize Muhammed b. Müsennâ ile Muhammed b. Beşşâr rivayet ettiler. (Dedilerki): Bize Muhammed b. Ca'fer rivayet etti. (Dediki): Bize Şu'be, Ebû İshak'dan, o da Ebû'l-Ahvas'dan,","o da Abdullah'dan, o da Nebi (Sallallahu Aleyhi ve Sellem)'den naklen rivayet etti ki: «Allahım! Ben senden hidayet, takva, iffet ve (gönül) zenginlik (i) dilerim.» dermiş"],"ur":["محمد بن مثنیٰ اور محمد بن بشار نے کہا : ہمیں محمد بن جعفر نے حدیث بیان کی ، انہوں نے کہا : ہمیں شعبہ نے ابواسحٰق سے حدیث سنائی ، انہوں نے ابواحوص سے ،","انہوں نے حضرت عبداللہ ( بن مسعود رضی اللہ عنہ ) سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم فرمایا کرتے تھے : \" اے اللہ! میں تجھ سے ہدایت ، تقویٰ ، پاک دامنی ، اور ( دل کا ) غنا مانگتا ہوں ۔"],"id":["Telah menceritakan kepada kami [Muhammad bin Al Mutsanna] dan [Muhammad bin Basysyar] mereka berkata; telah menceritakan kepada kami [Muhammad bin Ja'far] telah menceritakan kepada kami [Syu'bah] dari [Abu Ishaq] dari [Abul Ahwash] dari ['Abdullah] dari Nabi shallallahu 'alaihi wasallam bahwasanya beliau pernah berdoa: \"ALLOOHUMMA INNII AS-ALUKALHUDAA WATTUQOO WAL'AFAAFA WALGHINAA \"Ya Allah ya Tuhanku,","sesungguhnya aku memohon kepada-Mu petunjuk, ketakwaan, terhindar dari perbuatan yang tidak baik, dan kecukupan (tidak minta-minta,).\" Dan telah menceritakan kepada kami [Ibnu Al Mutsanna] dan [Ibnu Basyar] keduanya berkata; Telah menceritakan kepada kami [Abdurrahman] dari [Sufyan] dari [Abu Ishaq] melalui jalur ini dengan Hadits yang serupa. Namun Ibnu Mutsanna di dalam riwayatnya mengatakan lafazh; wal 'iffah (dan harga diri)"],"bn":["মুহাম্মাদ ইবনুল মুসান্না ও মুহাম্মাদ ইবনু বাশশার (রহঃ) ..... আবদুল্লাহ (রাযিঃ) এর সূত্রে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম থেকে বর্ণিত। তিনি এ বলে দুআ করতেন,","“আল্ল-হুম্মা ইন্নী আস্আলুকাল হুদা ওয়াত তুকা ওয়াল “আফা-ফা ওয়াল গিনা” অর্থাৎ- \"হে আল্লাহ! আমি আপনার নিকট পথনির্দেশ, আল্লাহভীতি, চারিত্রিক উৎকর্ষতা ও সচ্ছলতার জন্য দুআ করছি।\" (ইসলামিক ফাউন্ডেশন ৬৬৫৬, ইসলামিক সেন্টার)"]}},"du_hamm":{"src":"bukhari 6369","w":["كَانَ","النَّبِيُّ","صلى","الله","عليه","وسلم","يَقُولُ","اللَّهُمَّ","إِنِّي","أَعُوذُ","بِكَ","مِنَ","الْهَمِّ","وَالْحَزَنِ،","وَالْعَجْزِ","وَالْكَسَلِ،","وَالْجُبْنِ","وَالْبُخْلِ،","وَضَلَعِ","الدَّيْنِ،","وَغَلَبَةِ","الرِّجَالِ."],"p":[[0,12],[12,18],[18,22]],"m":{"en":["Narrated Anas bin Malik:The Prophet (ﷺ) used to say, \"O Allah! I seek refuge with You from worry and grief,","from incapacity and laziness, from cowardice and miserliness,","from being heavily in debt and from being overpowered by (other) men.\""],"fr":["Rapporté par Anas bin Malik : Le Prophète (ﷺ) disait : « Ô Allah ! Je cherche protection auprès de Toi contre l’inquiétude et la tristesse,","contre l’incapacité et la paresse, contre la lâcheté et l’avarice,","contre le poids des dettes et contre le fait d’être dominé par d’autres hommes. »"],"tr":["Enes İbn Malik'ten rivayet edildiğine göre Resulullah Sallallahu Aleyhi ve Sellem şöyle dua ederdi: \"Allahım' kederden, hüzünden, düşkünlükten, tembellikten, korkaklıktan, cimrilikten, borç sıkıntısından ve güçlülerin tasallutundan sana sığınırım\" Fethu'l-Bari Açıklaması:","Bu hadiste zikredilen altı hususun şerhi daha önce yapılmıştı. Keder diye çevirdiğimiz \"hemm\" kelimesi hali hazırdaki olumsuz durumları ifade eder. Hüzün ise geçmiş zamanla ilgilidir.","Düşkünlük, \"kudret sahibi olmanın\" tersidir. Tembellik de çalışkanlığın zıddıdır. Cimrilik cömertliğe, korkaklık da cesarete aykırıdır"],"ur":["ہم سے خالد بن مخلد نے بیان کیا، انہوں نے کہا ہم سے سلیمان نے بیان کیا، انہوں نے کہا کہ مجھ سے عمرو بن ابی عمرو نے بیان کیا، انہوں نے کہا کہ میں نے انس بن مالک رضی اللہ عنہ سے سنا،","کہا کہ نبی کریم صلی اللہ علیہ وسلم کہتے تھے «اللهم إني أعوذ بك من الهم والحزن،‏‏‏‏ والعجز والكسل،‏‏‏‏ والجبن والبخل،‏‏‏‏ وضلع الدين،‏‏‏‏ وغلبة الرجال» ”اے اللہ!","میں تیری پناہ مانگتا ہوں غم و الم سے، عاجزی سے، سستی سے، بزدلی سے، بخل، قرض چڑھ جانے اور لوگوں کے غلبہ سے۔“"],"id":["Telah menceritakan kepada kami [Khalid bin Makhlad] telah menceritakan kepada kami [Sulaiman] dia berkata; telah menceritakan kepadaku ['Amru bin Abu 'Amru] dia berkata; saya mendengar [Anas bin Malik] dia berkata;","Nabi shallallahu 'alaihi wasallam mengucapkan: \"ALLAHUMMA INII A'UUDZUBIKA MINAL HAMMI WAL HAZANI WAL 'AJZI WAL KASALI WALJUBNI WALBUKHLI WADLALA'ID DAINI WAGHALABATIR RIJAALI (Ya Allah,","aku berlindung kepada-Mu dari rasa sedih dan duka cita, lemah dan malas, pengecut dan kikir dan terlilit hutang serta dikuasai musuh)"],"bn":["আনাস ইবনু মালিক (রাঃ) হতে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলতেনঃ হে আল্লাহ!","নিশ্চয়ই আমি আপনার কাছে আশ্রয় চাই- দুশ্চিন্তা, পেরেশানী, অক্ষমতা, অলসতা, কাপুরুষতা, কৃপণতা,","ঋণভার ও মানুষের প্রভাবাধীন হওয়া থেকে। (আধুনিক প্রকাশনী-৫৯২৩, ইসলামিক ফাউন্ডেশন)"],"ru":["Анас ибн Малик, да будет доволен им Аллах, передаёт, что Пророк ﷺ часто говорил: «О Аллах, я прошу у Тебя защиты от тревог и печалей, от слабости и лени,","от трусости и скупости, бремени долга и от притеснения со стороны людей /Аллахумма инни а‘узу би-ка мина-ль-хамми ва-ль-‘аджзи ва-ль-касали,","ва-ль-джубни ва-ль-бухли ва даля‘и-д-дайни ва галябати-р-риджали/»"]}},"du_taqwa":{"src":"muslim 6906","w":["كَانَ","رَسُولُ","اللَّهِ","صلى","الله","عليه","وسلم","يَقُولُ","كَانَ","يَقُولُ","اللَّهُمَّ","إِنِّي","أَعُوذُ","بِكَ","مِنَ","الْعَجْزِ","وَالْكَسَلِ","وَالْجُبْنِ","وَالْبُخْلِ","وَالْهَرَمِ","وَعَذَابِ","الْقَبْرِ","اللَّهُمَّ","آتِ","نَفْسِي","تَقْوَاهَا","وَزَكِّهَا","أَنْتَ","خَيْرُ","مَنْ","زَكَّاهَا","أَنْتَ","وَلِيُّهَا","وَمَوْلاَهَا","اللَّهُمَّ","إِنِّي","أَعُوذُ","بِكَ","مِنْ","عِلْمٍ","لاَ","يَنْفَعُ","وَمِنْ","قَلْبٍ","لاَ","يَخْشَعُ","وَمِنْ","نَفْسٍ","لاَ","تَشْبَعُ","وَمِنْ","دَعْوَةٍ","لاَ","يُسْتَجَابُ","لَهَا."],"p":[[0,12],[12,24],[24,36],[36,48],[48,55]],"m":{"en":["Zaid b. Alqam reported:I am not going to say anything but only that which Allah's Messenger (may peace be upgn him) used to say.","He used to supplicate:\" O Allah, I seek refuge in Thee from incapacity, from sloth, from cowardice, from miserliness, decrepitude and from torment of the grave. O Allah,","grant to my soul the sense of righteousness and purify it, for Thou art the Best Purifier thereof. Thou art the Protecting Friend thereof, and Guardian thereof. O Allah,","I seek refuge in Thee from the knowledge which does not benefit, from the heart that does not entertain the fear (of Allah),","from the soul that does not feel contented and the supplication that is not responded"],"fr":["Rapporté par Zaid b. Alqam : Je ne vais rien dire d’autre que ce que le Messager d’Allah ﷺ disait. Il invoquait :","« Ô Allah, je cherche refuge auprès de Toi contre l’incapacité, la paresse, la lâcheté, l’avarice, la vieillesse et contre le châtiment de la tombe. Ô Allah,","accorde à mon âme la piété et purifie-la, car Tu es le meilleur à la purifier. Tu es son Protecteur et son Gardien. Ô Allah,","je cherche refuge auprès de Toi contre la connaissance qui ne profite pas, contre le cœur qui ne craint pas (Allah),","contre l’âme qui n’est jamais satisfaite et contre l’invocation qui n’est pas exaucée. »"],"tr":["Bize Ebû Bekr b. Ebî Şeybe ile İshak b. İbrahim ve Muhammed b. Abdillah b. Numeyr rivayet ettiler. Lâfız İbni Numeyri'ndir. (İshak: Ahberana;","ötekiler ise: Haddesena tâbirlerini kullandılar, dedilerki): Bize Ebû Muaviye, Âsım'dan, o da Abdullah b. Haris ile Ebu Osman En-Nehdî'den, onlar da Zeyd b. Erkam'dan naklen rivayet etti. (Şöyle de­miş):","Size ancak Resulullah (Sallallahu Aleyhi ve Sellem)'in söylediği gibi söylüyorum. O: «Allahım! Ben acz'den, tenbellikten, korkaklıktan. cimrilikten ihtiyarlıktan ve kabir, azabından sana sığınırım. Allahım!","Nefsime takvasını ver. Ve onu pâk eyle. Onu pâk edecek yegane sen varsın. Onun velisi ve mevlası sensin! Allahım! Ben fayda vermeyen ilim'den,","korkmayan kalb'den, doymayan nefisden ve kabul olunmayan duadan sana sığınırım.» derdi. İZAH 2725 TE"],"ur":["عبداللہ بن حارث اور ابو عثمان نہدی نے حضرت زید بن ارقم رضی اللہ عنہ سے روایت کی ، انہوں نے کہا :","میں تمہیں اسی طرح بتاتا ہوں جس طرح رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا ، آپ فرماتے تھے : \" اے اللہ! میں تجھ سے تیری پناہ میں آتا ہوں ، عاجز ہو جانے ، سستی ، بزدلی ، بخل ،","سخت بڑھاپے اور قبر کے عذاب سے ۔ اے اللہ! میرے دل کو تقویٰ دے ، اس کو پاکیزہ کر دے ، تو ہی اس ( دل ) کو سب سے بہتر پاک کرنے والا ہے ، تو ہی اس کا رکھوالا اور اس کا مددگار ہے ۔ اے اللہ!","میں تجھ سے ایسے علم سے تیری پناہ مانگتا ہوں جو کوئی فائدہ نہ دے اور ایسے دل سے جو ( تیرے آگے ) جھک کر مطمئن نہ ہوتا ہو اور ایسے من سے جو سیر نہ ہو اور ایسی دعا سے جسے شرف قبولیت نصیب نہ ہو ۔",""],"id":["Telah menceritakan kepada kami [Abu Bakr bin Abu Syaibah] dan [Ishaq bin Ibrahim] dan [Muhammad bin 'Abdullah bin Numair] -dan lafadh ini milik Ibnu Numair- Ishaq berkata; Telah mengabarkan kepada kami, sedangkan yang lainnya berkata;","Telah menceritakan kepada kami [Abu Mu'awiyah] dari [Ashim] dari [Abdullah bin Al Harits] dan dari [Abu Utsman An Nahdi] dari [Zaid bin Arqam] dia berkata; \"Saya tidak akan mengatakan kepada kalian kecuali seperti apa yang pernah diucapkan Rasulullah shallallahu 'alaihi wasallam dalam doanya yang berbunyi: \"ALLOOHUMMA INNII A'UUDZU BIKA MINAL 'AJZI WAL KASALI,","WAL JUBNI WAL BUKHLI WAL HAROMI, WA'ADZAABIL QOBRI, ALLOOHUMMA AATI NAFSII TAQWAAHAA, WAZAKKIHAA ANTA KHOIRU MAN ZAKKAAHAA, ANTA WALIYYUHAA WAMAULAAHAA, ALLOOHUMMA INNII A'UUDZU BIKA MIN 'ILMIN LAA YANFA'U WAMIN QOLBIN LAA YAKHSYA'U WAMIN NAFSIN LAA TASYBA'U WAMIN DA'WATIN LAA YUSTAJAABA LAHU' Ya Allah ya Tuhanku, aku berlindung kepada-Mu dari kelemahan,","kemalasan, ketakutan, kekikiran, kepikunan, dan siksa kubur. Ya Allah ya Tuhanku, berikanlah ketakwaan kepada jiwaku, sucikanlah ia, sesungguhnya Engkaulah sebaik-baik Dzat yang dapat mensucikannya, Engkaulah yang menguasai dan yang menjaganya.","Ya Allah ya Tuhanku, sesungguhnya aku berlindung kepada-Mu dari ilmu yang tidak berguna, hati yang tidak khusyu', diri yang tidak pernah puas, dan doa yang tidak terkabulkan"],"bn":["আবূ বাকর ইবনু আবূ শাইবাহ্, ইসহাক ইবনু ইব্রাহীম ও মুহাম্মাদ ইবনু আবদুল্লাহ ইবনু নুমায়র (রহঃ) ..... যায়দ ইবনু আরকাম (রাযিঃ) থেকে বর্ণিত। তিনি বলেন,","আমি তোমাদের নিকট তেমনই বলব যেমনটি রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলতেন। তিনি (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম) বলতেনঃ \"আল্ল-হুম্মা ইন্নী আউযুবিকা মিনাল আজ্‌যি ওয়াল কাসালি ওয়াল জুৱ্‌নি ওয়াল বুখ্‌লি ওয়াল হারামি ওয়া আযা-বিল কবরি, আল্ল-হুম্মা আ-তি নাফসী তাকওয়া-হা ওয়াযাক্কিহা- আনতা খইরু মান্‌ যাককা-হা আনতা ওয়ালী ইউহা- ওয়া মাওলা-হা-,","আল্ল-হুম্মা ইন্নী আউযুবিকা মিন ইলমিন লা- ইয়ান্‌ফা'উ ওয়ামিন কলবিনু লা- ইয়াখশাউ ওয়ামিন নাফসিন লা- তাশবাউ ওয়ামিন দা’ওয়াতিন লা- ইউসতাজা-বু লাহা-” অর্থাৎ- \"হে আল্লাহ! আমি আপনার নিকট পানাহ চাই অপারগতা, অলসতা, ভীরুতা, বখিলতা, বার্ধক্যতা এবং কবরের শাস্তি থেকে। হে আল্লাহ!","আপনি আমার অন্তরে পরহেযগারিতা দান করুন এবং একে সংশোধন করে দিন। আপনি একমাত্র সর্বোত্তম সংশোধনকারী এবং আপনিই একমাত্র তার মালিক ও আশ্রয়স্থল। হে আল্লাহ! আমি আপনার নিকট পানাহ চাই এমন ইলম হতে যা কোন উপকারে আসবে না ও এমন অন্তঃকরণ থেকে যা আল্লাহর ভয়ে ভীত হয় না;","এমন আত্মা থেকে যা কক্ষনও তৃপ্ত হয় না। আর এমন দু’আ থেকে যা কবুল হয় না।\" (ইসলামিক ফাউন্ডেশন ৬৬৫৮, ইসলামিক সেন্টার)"]}},"du_karb":{"src":"bukhari 6345","w":["كَانَ","النَّبِيُّ","صلى","الله","عليه","وسلم","يَدْعُو","عِنْدَ","الْكَرْبِ","لاَ","إِلَهَ","إِلاَّ","اللَّهُ","الْعَظِيمُ","الْحَلِيمُ،","لاَ","إِلَهَ","إِلاَّ","اللَّهُ","رَبُّ","السَّمَوَاتِ","وَالأَرْضِ،","رَبُّ","الْعَرْشِ","الْعَظِيمِ."],"p":[[0,12],[12,22],[22,25]],"m":{"en":["Narrated Ibn `Abbas:The Prophet (ﷺ) used to invoke Allah at the time of distress,","saying, \"La ilaha illal-lahu Al-`Azim, al- Halim, La ilaha illal-lahu Rabbu-s-samawati wal-ard wa Rabbu-l-arsh il-azim",""],"fr":["Rapporté par Ibn `Abbas : Le Prophète ﷺ invoquait Allah lors des moments de détresse en disant :","« La ilaha illal-lahu Al-`Azim, al-Halim, La ilaha illal-lahu Rabbu-s-samawati wal-ard wa Rabbu-l-arsh il-azim.","»"],"tr":["İbn Abbas'tan nakledildiğine göre Resulullah Sallallahu Aleyhi ve Sellem sıkıntı halinde şöyle dua ederdi: La ilahe illallahu’l-Azimu’l-Halim,","La ilahe illallahu Rabbi’s-semavati ve’l-ardi ve .Rabbi’l-Arşi’l-Azim Meali: \"Azim ve halim olan Allah'tan başka ilah yoktur. Göklerin,","yerin ve yüce arşın rabbi olan Allah'tan başka ilah yoktur"],"ur":["ہم سے مسلم بن ابراہیم نے بیان کیا، انہوں نے کہا ہم سے ہشام بن عروہ نے بیان کیا، انہوں نے کہا ہم سے قتادہ نے بیان کیا،","ان سے ابوالعالیہ نے اور ان سے ابن عباس رضی اللہ عنہما نے کہ نبی کریم صلی اللہ علیہ وسلم پریشانی کے وقت یہ دعا کرتے تھے «لا إله إلا الله العظيم الحليم،‏‏‏‏ لا إله إلا الله رب السموات والأرض،‏‏‏‏ رب العرش العظيم» ”اللہ کے سوا کوئی معبود نہیں جو بہت عظمت والا ہے اور برد بار ہے،","اللہ کے سوا کوئی معبود نہیں جو آسمانوں اور زمین کا رب اور بڑے بھاری عرش کا رب ہے۔“"],"id":["Telah menceritakan kepada kami [Muslim bin Ibrahim] telah menceritakan kepada kami [Hisyam] telah menceritakan kepada kami [Qatadah] dari [Abu 'Aliyah] dari [Ibnu Abbas] radliallahu 'anhuma dia berkata;","\"Nabi shallallahu 'alaihi wasallam biasa berdo'a ketika dalam kesulitan, beliau mengucapkan: \"LAA ILAAHA ILLALLAHUL 'ADZIIM AL HALIIM LAA ILAAHA ILLALLAH RABBUL 'ARSYIL 'AZHIIM (Tiada Ilah selain Allah Yang Maha Agung dan Maha Penyantun.","Tiada ilah selain Allah, Tuhan langit dan bumi serta Tuhan arasy yang mulia)"],"bn":["ইবনু ‘আব্বাস (রাঃ) হতে বর্ণিত। তিনি বলেনঃ নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বিপদের সময় এ দু‘আ পড়তেনঃ আল্লাহ ব্যতীত কোন ইলাহ নেই। যিনি মহান ও ধৈর্যশীল। আল্লাহ ছাড়া আর কোন ইলাহ নেই। তিনিই আসমান যমীনের প্রতিপালক ও মহান আরশের প্রভু। [৬৩৪৬,","৭৪২৬, ৭৪৩১; মুসলিম ৪৮/২১, হাঃ ২৭৩০,","আহমাদ ৩৩৫৪] (আধুনিক প্রকাশনী- ৫৮৯৯, ইসলামিক ফাউন্ডেশন)"],"ru":["Передают со слов Ибн ‘Аббаса, да будет доволен Аллах им и его отцом, что когда Пророком ﷺ овладевала скорбь, он обращался к Аллаху с мольбой, говоря: «Нет божества достойного поклонения,","кроме Аллаха Великого, Выдержанного, нет божества достойного поклонения, кроме Аллаха, Господа небес и земли, нет божества достойного поклонения, кроме Аллаха, Господа великого Трона!». \\n/Ля иляха илля-Ллаху-ль-‘Азымуль-Халим, ля иляха илля-Ллаху,","Раббу-с-самаввати, валь-ард, ля иляха илля-Ллаху, Раббуль-‘аршиль‘азым"]}},"h_shukr":{"src":"abudawud 4811","w":["عَنْ","أَبِي","هُرَيْرَةَ،","عَنِ","النَّبِيِّ","صلى","الله","عليه","وسلم","قَالَ","لاَ","يَشْكُرُ","اللَّهَ","مَنْ","لاَ","يَشْكُرُ","النَّاسَ."],"p":[[0,12],[12,17]],"m":{"en":["Narrated Abu Hurayrah: The Prophet (ﷺ) said:","He who does not thank the people is not thankful to Allah"],"fr":["Rapporté par Abu Hurayrah : Le Prophète ﷺ a dit :","« Celui qui ne remercie pas les gens ne remercie pas Allah. »"],"tr":["Ebu Hureyre'den (rivayet edildiğine göre) Nebi (Sallallahu aleyhi ve Sellem): \"İnsanlara teşekkür etmeyen, Allah'a şükretmez.\"buyurmuştur. Diğer tahric: Tirmizî,","birr; Ahmed b. Hanbel, II-258, 295, 303, 388, 461, 492, III, 32, 74, IV, 278, 375, V"],"ur":["ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:","جو لوگوں کا شکر ادا نہیں کرتا اللہ کا ( بھی ) شکر ادا نہیں کرتا ۔"],"id":["Telah menceritakan kepada kami [Muslim bin Ibrahim] berkata, telah menceritakan kepada kami [Ar Rabi' bin Muslim] dari [Muhammad bin Ziyad] dari [Abu Hurairah] dari Nabi shallallahu 'alaihi wasallam,","beliau bersabda: \"Tidak dianggap bersyukur kepada Allah orang yang tidak bersyukur kepada manusia"],"bn":["। আবূ হুরাইরাহ (রাঃ) সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ যে ব্যক্তি মানুষের প্রতি কৃতজ্ঞতা প্রকাশ করে না সে আল্লাহর প্রতিও কৃতজ্ঞতা প্রকাশ করে না। অথবা যে ব্যক্তি মানুষের প্রতি অকৃতজ্ঞ,","সে আল্লাহর প্রতিও অকৃতজ্ঞ।[1] সহীহ।"]}},"h_dua":{"src":"tirmidhi 3372","w":["عَنِ","النُّعْمَانِ","بْنِ","بَشِيرٍ،","عَنِ","النَّبِيِّ","صلى","الله","عليه","وسلم","قَالَ","الدُّعَاءُ","هُوَ","الْعِبَادَةُ.","ثُمَّ","قَرَأََ:","وقالَ","رَبُّكُمُ","ادْعُونِي","أَسْتَجِبْ","لَكُمْ","إِنَّ","الَّذِينَ","يَسْتَكْبِرُونَ","عَنْ","عِبَادَتِي","سَيَدْخُلُونَ","جَهَنَّمَ","دَاخِرِينَ."],"p":[[0,12],[12,24],[24,29]],"m":{"en":["An-Nu`man bin Bashir narrated that:The Prophet said: “The supplication,","is worship.” Then he recited: And Your Lord said: “Call upon me, I will respond to you. Verily, those who scorn My worship,","they will surely enter Hell humiliated"],"tr":["Numân b. Beşîr (r.a.)’den rivâyete göre: Rasûlullah (s.a.v.) şöyle buyurmuştur: “Duâ ibadettir.” Sonra mü’min sûresi 60.","ayetini okudu: “Ama Rabbiniz buyuruyor ki: “Bana duâ edin, duânızı kabul edeyim. Şüphesiz ki, bana kulluk etmekten ululuk taslayarak çekinenler,","aşağılık bir halde Cehenneme gireceklerdir.”"],"ur":["نعمان بن بشیر رضی الله عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ”دعا ہی عبادت ہے، پھر آپ نے آیت: «وقال ربكم ادعوني أستجب لكم إن الذين يستكبرون عن عبادتي سيدخلون جهنم داخرين» ”تمہارا رب فرماتا ہے،","تم مجھے پکارو، میں تمہاری پکار ( دعا ) کو قبول کروں گا، جو لوگ مجھ سے مانگنے سے گھمنڈ کرتے ہیں، وہ جہنم میں ذلیل و خوار ہو کر داخل ہوں گے“ ( المومن: ۶ ) پڑھی“۔ امام ترمذی کہتے ہیں: ۱- یہ حدیث حسن صحیح ہے، ۲- منصور نے یہ حدیث اعمش سے اور اعمش نے ذر سے روایت کی ہے،","ہم اسے صرف ذر کی روایت سے جانتے ہیں، یہ ذر بن عبداللہ ہمدانی ہیں ثقہ ہیں، عمر بن ذر کے والد ہیں۔"],"id":["Telah menceritakan kepada kami [Ahmad bin Mani'] telah menceritakan kepada kami [Marwan bin Mu'awiyah] dari [Al A'masy] dari [Dzar] dari [Yusai'] dari [An Nu'man bin Basyir] dari Nabi shallallahu 'alaihi wasallam beliau bersabda:","\"Doa adalah ibadah.\" Kemudian beliau membaca ayat: Dan Tuhanmu berfirman: \"Berdoalah kepada-Ku, niscaya akan Kuperkenankan bagimu. Sesungguhnya orang-orang yang menyombongkan diri dari menyembah-Ku akan masuk neraka Jahannam dalam keadaan hina dina.\" (QS. Ghafir 60), Abu Isa berkata; hadits ini adalah hadits hasan shahih,","dan telah diriwayatkan oleh [Manshur] serta [Al A'masy] dari [Dzarr] dan kami tidak mengetahuinya kecuali dari hadits Dzar bin Abdullah Al Hamdani, ia adalah orang tsiqah, anak Umar bin Dzar"],"bn":["নুমান ইবনু বাশীর (রাযিঃ) হতে বর্ণিত আছে, নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ দু'আই হল ইবাদাত। তারপর তিনি পাঠ করেন (অনুবাদ) “এবং তোমাদের রব বলেছেন, আমাকে তোমরা আহবান কর,","আমি তোমাদের আহবানে সাড়া দিব। নিশ্চয় যে সকল লোক আমার ইবাদাত করতে অহংকার করে (বিরত থাকে), শীঘ্রই তারা ভৎসনার সঙ্গে জাহান্নামে প্রবেশ করবে”— (সূরা মু'মিন ৬০)। সহীহঃ ইবনু মাজাহ (হাঃ ৩৮২৮)। আবূ ঈসা বলেন,","হাদীসটি হাসান সহীহ। এ হাদীসটি মানসূর ও আমাশ (রাহঃ) যার-এর সূত্রে বর্ণনা করেছেন। আমরা এ হাদীসটি কেবল যার-এর সনদেই অবগত হয়েছি। যার ইবনু আবদুল্লাহ আল-হামদানী নির্ভরযোগ্য বর্ণনাকারী। তিনি উমার ইবনু যার-এর পিতা।"]}},"h_akhu":{"src":"bukhari 2442","w":["أَنَّ","رَسُولَ","اللَّهِ","صلى","الله","عليه","وسلم","قَالَ","الْمُسْلِمُ","أَخُو","الْمُسْلِمِ،","لاَ","يَظْلِمُهُ","وَلاَ","يُسْلِمُهُ،","وَمَنْ","كَانَ","فِي","حَاجَةِ","أَخِيهِ","كَانَ","اللَّهُ","فِي","حَاجَتِهِ،","وَمَنْ","فَرَّجَ","عَنْ","مُسْلِمٍ","كُرْبَةً","فَرَّجَ","اللَّهُ","عَنْهُ","كُرْبَةً","مِنْ","كُرُبَاتِ","يَوْمِ","الْقِيَامَةِ،","وَمَنْ","سَتَرَ","مُسْلِمًا","سَتَرَهُ","اللَّهُ","يَوْمَ","الْقِيَامَةِ."],"p":[[0,11],[11,23],[23,35],[35,44]],"m":{"en":["Narrated `Abdullah bin `Umar:Allah's Messenger (ﷺ) said, \"A Muslim is a brother of another Muslim,","so he should not oppress him, nor should he hand him over to an oppressor. Whoever fulfilled the needs of his brother,","Allah will fulfill his needs; whoever brought his (Muslim) brother out of a discomfort, Allah will bring him out of the discomforts of the Day of Resurrection,","and whoever screened a Muslim, Allah will screen him on the Day of Resurrection"],"fr":["Rapporté par ‘Abdullah bin ‘Umar : Le Messager d’Allah (ﷺ) a dit : « Un musulman est le frère d’un autre musulman,","il ne doit donc pas lui faire de tort ni le livrer à un injuste. Celui qui satisfait les besoins de son frère,","Allah satisfera ses besoins ; celui qui soulage son frère musulman d’une difficulté,","Allah le soulagera des difficultés du Jour de la Résurrection ; et celui qui couvre un musulman, Allah le couvrira le Jour de la Résurrection. »"],"tr":["İbn Şihab, Salim'den, o da Abdullah İbn Ömer r.a.'den nakletmiştir: Allah Resulü Sallallahu Aleyhi ve Sellem şöyle buyurmuştur:","\"Müslüman Müslüman'ın kardeşidir; ona haksızlık etmez ve onu ölüme terketmez. Her kim kardeşinin bir ihtiyacını görürse Allah da onun ihtiyacını görür.","Her kim bir Müslüman'ın bir sıkıntısını giderirse Allah da kıyamet gününde onun sıkıntılarından bir sıkıntısını giderir.","Her kim bir Müslümanın ayıbını örterse Allah da kıyamet gününde onun ayıbını örter. \" Tekrar: 6951 Diğer tahric: Tirmizî, Hudud; Ebu Dâvud, Edeb"],"ur":["ہم سے یحییٰ بن بکیر نے بیان کیا، کہا کہ ہم سے لیث نے بیان کیا، ان سے عقیل نے، ان سے ابن شہاب نے، انہیں سالم نے خبر دی،","اور انہیں عبداللہ بن عمر رضی اللہ عنہما نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ایک مسلمان دوسرے مسلمان کا بھائی ہے،","پس اس پر ظلم نہ کرے اور نہ ظلم ہونے دے۔ جو شخص اپنے بھائی کی ضرورت پوری کرے، اللہ تعالیٰ اس کی ضرورت پوری کرے گا۔ جو شخص کسی مسلمان کی ایک مصیبت کو دور کرے،","اللہ تعالیٰ اس کی قیامت کی مصیبتوں میں سے ایک بڑی مصیبت کو دور فرمائے گا۔ اور جو شخص کسی مسلمان کے عیب کو چھپائے اللہ تعالیٰ قیامت میں اس کے عیب چھپائے گا۔"],"id":["Telah menceritakan kepada kami [Yahya bin Bukair] telah menceritakan kepada kami [Al Laits] dari ['Uqail] dari [Ibnu Syihab] bahwa [Salim] mengabarkannya bahwa ['Abdullah bin 'Umar radliallahu 'anhuma] mengabarkannya bahwa Rasulullah shallallahu 'alaihi wasallam bersabda:","\"Seorang muslim adalah saudara bagi muslim lainnya,","dia tidak menzhaliminya dan tidak membiarkannya untuk disakiti. Siapa yang membantu kebutuhan saudaranya maka Allah akan membantu kebutuhannya. Siapa yang menghilangkan satu kesusahan seorang muslim,","maka Allah menghilangkan satu kesusahan baginya dari kesusahan-kesusahan hari qiyamat. Dan siapa yang menutupi (aib) seorang muslim maka Allah akan menutup aibnya pada hari qiyamat"],"bn":["‘আবদুল্লাহ ইবনু ‘উমার (রাঃ) হতে বর্ণিত। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেন,","মুসলিম মুসলিমের ভাই। সে তার উপর জুলুম করবে না এবং তাকে যালিমের হাতে সোপর্দ করবে না। যে কেউ তার ভাইয়ের অভাব পূরণ করবে,আল্লাহ তার অভাব পূরণ করবেন।যে কেউ তার মুসলিম ভাইয়ের বিপদ দুর করবে,","আল্লাহ তা‘আলা কিয়ামতের দিন তার বিপদসমূহ দূর করবেন। যে ব্যক্তি কোন মুসলিমের দোষ ঢেকে রাখবে,","আল্লাহ কিয়ামতের দিন তার দোষ ঢেকে রাখবেন। (৬৯৫১) (আধুনিক প্রকাশনীঃ ২২৬৩, ইসলামিক ফাউন্ডেশনঃ)"],"ru":["Передают со слов Ибн ‘Умара, да будет доволен Аллах ими обоими, что Посланник Аллаха ﷺ сказал:","«Мусульманин мусульманину брат, и он (не должен) ни притеснять, ни предавать его. Тому, кто (поможет) своему брату в нужде его,","Аллах (поможет) в его собственной нужде, того, кто избавит мусульманина от печали,","Аллах избавит от одной из печалей Дня воскресения, а (грехи) того, кто покроет (грехи) мусульманина, Аллах покроет в День воскресения»"]}},"h_haya":{"src":"bukhari 24","w":["عَنْ","أَبِيهِ،","أَنَّ","رَسُولَ","اللَّهِ","صلى","الله","عليه","وسلم","مَرَّ","عَلَى","رَجُلٍ","مِنَ","الأَنْصَارِ","وَهُوَ","يَعِظُ","أَخَاهُ","فِي","الْحَيَاءِ،","فَقَالَ","رَسُولُ","اللَّهِ","صلى","الله","عليه","وسلم","دَعْهُ","فَإِنَّ","الْحَيَاءَ","مِنَ","الإِيمَانِ."],"p":[[0,12],[12,19],[19,31]],"m":{"en":["Narrated 'Abdullah (bin 'Umar):","Once Allah's Messenger (ﷺ) passed by an Ansari (man) who was admonishing his brother regarding Haya'.","On that Allah's Messenger (ﷺ) said, \"Leave him as Haya' is a part of faith.\""],"fr":["Rapporté par 'Abdullah (bin 'Umar) : Un jour,","le Messager d'Allah (ﷺ) est passé près d'un homme des Ansar qui réprimandait son frère à propos de la pudeur (Haya').","Alors le Messager d'Allah (ﷺ) a dit : Laisse-le, car la pudeur fait partie de la foi"],"tr":["Salim b. Abdullah'ın babası (yani İbn-i Ömer den) rivayet ettiğine göre Nebi (Sallallahu aleyhi ve Sellem) Ensardan bir kişinin yanından geçiyordu.","O sırada bu kişi kardeşine utangaçlığı (hayası) sebebiyle öğüt veriyordu. Bunun üzerine Hz.","Pey­gamber ona şöyle buyurdu: Onu bırak! Çünkü haya (utanmak) imandandır. Tekrar: 6118 Diğer Tahric: Bu hadis Müslim İman; Tirmizi İman da da geçer. (Yani onu ikisi de tahric ettiler)"],"ur":["عبداللہ بن یوسف نے ہم سے بیان کیا، وہ کہتے ہیں کہ ہمیں مالک بن انس نے ابن شہاب سے خبر دی، وہ سالم بن عبداللہ سے نقل کرتے ہیں،","","وہ اپنے باپ (عبداللہ بن عمر رضی اللہ عنہما) سے کہ ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم ایک انصاری شخص کے پاس سے گزرے اس حال میں کہ وہ اپنے ایک بھائی سے کہہ رہے تھے کہ تم اتنی شرم کیوں کرتے ہو۔ آپ صلی اللہ علیہ وسلم نے اس انصاری سے فرمایا کہ اس کو اس کے حال پر رہنے دو کیونکہ حیاء بھی ایمان ہی کا ایک حصہ ہے۔"],"id":["Telah menceritakan kepada kami [Abdullah bin Yusuf] berkata, telah mengabarkan kepada kami [Malik bin Anas] dari [Ibnu Syihab] dari [Salim bin Abdullah] dari [bapaknya],","bahwa Rasulullah shallallahu 'alaihi wasallam berjalan melewati seorang sahabat Anshar yang saat itu sedang memberi pengarahan saudaranya tentang malu.","Maka Rasulullah shallallahu 'alaihi wasallam bersabda: \"Tinggalkanlah dia, karena sesungguhnya malu adalah bagian dari iman"],"bn":["","আব্দুল্লাহ ইবনু ‘উমার (রাযি.) হতে বর্ণিত। একদা আল্লাহর রাসূল সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এক আনসারীর পাশ দিয়ে অতিক্রম করছিলেন। তিনি তাঁর ভাইকে তখন (অধিক) লজ্জা ত্যাগের জন্য নাসীহাত করছিলেন। আল্লাহর রাসূল সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাকে বললেনঃ ওকে ছেড়ে দাও। কারণ লজ্জা ঈমানের অঙ্গ। (৬১১৮;","মুসলিম ১/১২ হাঃ ৩৬, আহমাদ ৪৫৫৪) (আধুনিক প্রকাশনীঃ ২৩, ইসলামিক ফাউন্ডেশনঃ)"],"ru":["Передают со слов Салима ибн ‘Абдуллаха, передавшего со слов своего отца (Ибн ‘Умара, да будет доволен Аллах ими обоими.) о том,","что (как-то раз), проходя мимо одного из ансаров,","который давал своему брату наставления относительно стыдливости, Посланник Аллаха ﷺ сказал ему: «Оставь его, ибо, поистине, стыдливость — от веры!»"]}},"h_jamil":{"src":"muslim 265","w":["عَنْ","عَبْدِ","اللَّهِ","بْنِ","مَسْعُودٍ،","عَنِ","النَّبِيِّ","صلى","الله","عليه","وسلم","قَالَ","لاَ","يَدْخُلُ","الْجَنَّةَ","مَنْ","كَانَ","فِي","قَلْبِهِ","مِثْقَالُ","ذَرَّةٍ","مِنْ","كِبْرٍ.","قَالَ","رَجُلٌ","إِنَّ","الرَّجُلَ","يُحِبُّ","أَنْ","يَكُونَ","ثَوْبُهُ","حَسَنًا","وَنَعْلُهُ","حَسَنَةً.","قَالَ","إِنَّ","اللَّهَ","جَمِيلٌ","يُحِبُّ","الْجَمَالَ","الْكِبْرُ","بَطَرُ","الْحَقِّ","وَغَمْطُ","النَّاسِ."],"p":[[0,5],[5,17],[17,23],[23,34],[34,45]],"m":{"en":["It Is narrated on the authority of Abdullah b.","Mas'ud that the Messenger of Allah (ﷺ), observed:He who has in his heart the weight of a mustard seed of pride shall not enter Paradise.","A person (amongst his hearers) said:","Verily a person loves that his dress should be fine, and his shoes should be fine. He (the Holy Prophet) remarked:","Verily, Allah is Graceful and He loves Grace. Pride is disdaining the truth (out of self-conceit) and contempt for the people"],"fr":["Rapporté par ‘Abdullah b. Mas‘ud :","Le Messager d’Allah ﷺ a dit : « Celui qui a dans son cœur ne serait-ce qu’un grain de moutarde d’orgueil n’entrera pas au Paradis.","» Une personne a dit :","« Mais une personne aime porter de beaux vêtements et de belles chaussures. » Le Prophète ﷺ a répondu :","« En vérité, Allah est Beau et Il aime la beauté. L’orgueil, c’est rejeter la vérité et mépriser les gens. »"],"tr":["Bize Muhammed b. el-Müsenna, Muhammed b. Beşşar ve İbrahim b. Dinar -birlikte- Yahya b.","Hammad'dan tahdis etti. İbnu'l-Müsenna dedi ki: Bana Yahya b. Hammad tahdis etti. Bize Şu'be, Eban b. Tağlib'den haber verdi. O Fudayl el-Fukayml'den,","o İbrahim en-Nehal'den, o Alkame'den, o Abdullah b. Mes'ud'dan,","o Nebi (Sallallahu aleyhi ve Sellem)'den şöyle buyurduğunu nakletti: \"Kalbinde zerre ağırlığınca kibir bulunan bir kimse cennete girmez. \" Bir adam: Kişi elbisesinin güzel, ayakkabısının güzel olmasını sever(se) durumu nedir,","dedi. Allah Resulü (Sallallahu aleyhi ve Sellem): \"Şüphesiz Allah güzeldir, güzeli sever. Kibir ise hakkı kabul etmemek ve insanları küçümsemektir\" buyurdu. Diğer tahric: Tirmizi, 1999; Tuhfetu'l-Eşraf"],"ur":["یحییٰ بن حماد نے کہا : ہمیں شعبہ نے ابان بن تغلب سے حدیث سنائی ،","انہوں نے فضیل بن عمرو فقیمی سے ، انہوں نے ابراہیم نخعی سے ، انہوں نے علقمہ سے ،","انہوں نے حضرت عبد اللہ بن مسعود ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے اور انہوں نے نبی کریمﷺ سے روایت کی ،","آپ نے فرمایا : ’’ جس کے دل میں ذرہ برابر تکبر ہو گا ، وہ جنت میں داخل نہ ہو گا ۔ ‘ ‘ ایک آدمی نے کہا : انسان چاہتا ہے کہ اس کے کپڑے اچھے ہوں اور اس کے جوتے اچھے ہوں ۔ آپ نے فرمایا :","’’ اللہ خود جمیل ہے ، وہ جمال کو پسند فرماتا ہے ۔ تکبر ، حق کو قبول نہ کرنا اورلوگوں کو حقیر سمجھنا ہے ۔ ‘ ‘"],"id":["Dan telah menceritakan kepada kami [Muhammad bin al-Mutsanna] dan [Muhammad bin Basysyar] serta [Ibrahim bin Dinar] semuanya dari [Yahya bin Hammad],","[Ibnu al-Mutsanna] berkata,","telah menceritakan kepada kami [Yahya bin Hammad] telah mengabarkan kepada kami [Syu'bah] dari [Aban bin Taghlib] dari [Fudlail al-Fuqaimi] dari [Ibrahim an-Nakha'i] dari [Alqamah] dari [Abdullah bin Mas'ud] dari Nabi shallallahu 'alaihi wasallam,","beliau bersabda: \"Tidak akan masuk surga, orang yang di dalam hatinya terdapat seberat biji sawi dari kesombongan.\" Seorang laki-laki bertanya,","\"Sesungguhnya laki-laki menyukai apabila baju dan sandalnya bagus (apakah ini termasuk kesombongan)?\" Beliau menjawab: \"Sesungguhnya Allah itu bagus menyukai yang bagus, kesombongan itu menolak kebenaran dan meremehkan manusia"],"bn":["মুহাম্মাদ ইবনু আল মুসান্না, মুহাম্মাদ ইবনু বাশশার ও ইবরাহীম ইবনু দীনার (রহঃ) .....","'আবদুল্লাহ ইবনু মাসউদ (রাযিঃ) বলেন যে,","নবী সাল্লাল্লাহু আলাইহি ওয়া সাল্লাম বলেছেনঃ যার অন্তরে অণুপরিমাণ অহংকার থাকবে সে জান্নাতে প্রবেশ করবে না। এক ব্যক্তি জিজ্ঞেস করলো,","মানুষ চায় যে, তার পোশাক সুন্দর হোক, তার জুতা সুন্দর হোক, এ-ও কি অহঙ্কার? রাসূল সাল্লাল্লাহু আলাইহি ওয়া সাল্লাম বললেনঃ আল্লাহ সুন্দর,","তিনি সুন্দরকে ভালোবাসেন। প্রকৃতপক্ষে অহংকার হচ্ছে দম্ভভরে সত্য ও ন্যায় অস্বীকার করা এবং মানুষকে ঘৃণা করা*। (ইসলামিক ফাউন্ডেশনঃ ১৬৭, ইসলামিক সেন্টারঃ)"],"ru":["Передают со слов ‘Абдуллаха ибн Мас‘уда (да будет доволен им Аллах) о том,","что Пророк ﷺ сказал: «Не войдёт в Рай (тот человек),","в сердце которого (останется) высокомерие (весом хотя бы) с пылинку». (Услышав это,","один) человек воскликнул: «Но ведь человеку хочется, чтобы его одежда и обувь были красивыми!» (На это Пророк ﷺ) сказал: «Поистине,","Аллах прекрасен, и Он любит прекрасное, (что же касается) высокомерия, то это неприятие истины и проявление презрения по отношению к людям»"]}},"h_qawi":{"src":"muslim 6774","w":["عَنْ","أَبِي","هُرَيْرَةَ،","قَالَ","قَالَ","رَسُولُ","اللَّهِ","صلى","الله","عليه","وسلم","الْمُؤْمِنُ","الْقَوِيُّ","خَيْرٌ","وَأَحَبُّ","إِلَى","اللَّهِ","مِنَ","الْمُؤْمِنِ","الضَّعِيفِ","وَفِي","كُلٍّ","خَيْرٌ","احْرِصْ","عَلَى","مَا","يَنْفَعُكَ","وَاسْتَعِنْ","بِاللَّهِ","وَلاَ","تَعْجِزْ","وَإِنْ","أَصَابَكَ","شَىْءٌ","فَلاَ","تَقُلْ","لَوْ","أَنِّي","فَعَلْتُ","كَانَ","كَذَا","وَكَذَا.","وَلَكِنْ","قُلْ","قَدَرُ","اللَّهِ","وَمَا","شَاءَ","فَعَلَ","فَإِنَّ","لَوْ","تَفْتَحُ","عَمَلَ","الشَّيْطَانِ."],"p":[[0,12],[12,24],[24,36],[36,42],[42,54]],"m":{"en":["Abu Huraira reported Allah's Messenger (ﷺ) as saying:A strong believer is better and is more lovable to Allah than a weak believer,","and there is good in everyone,","(but) cherish that which gives you benefit (in the Hereafter) and seek help from Allah and do not lose heart, and if anything (in the form of trouble) comes to you, don't say:","If I had not done that, it would not have happened so and so,","but say: Allah did that what He had ordained to do and your\" if\" opens the (gate) for the Satan"],"fr":["Rapporté par Abu Huraira رضي الله عنه : Le Messager d’Allah ﷺ a dit :","« Le croyant fort est meilleur et plus aimé d’Allah que le croyant faible, mais il y a du bien en chacun.","Recherche ce qui t’est bénéfique (dans l’au-delà), demande l’aide d’Allah et ne te décourage pas. Si un malheur t’arrive, ne dis pas :","“Si je n’avais pas fait ceci,","cela ne serait pas arrivé”, mais dis : “Allah a fait ce qu’Il avait décidé.” Car le “si” ouvre la porte au diable. »"],"tr":["Bize Ebû Bekr b. Ebi Şeybe ile İbnü Nurneyr rivayet ettiler. (Dedilerki): Bize Abdullah b. İdris Rabia b. Osman'dan,","o da Muhammed b. Yahya b. Habbaan'dan, o da A'rac'dan, o da Ebû Hureyre'den naklen rivayet etti. Şöyle demiş:","Resûlullah (Sallallahu Aleyhi ve Sellem) «Kuvvetli mü'min Allah'a zayıf mü'minden daha hayırlı ve daha makbuldür. Ama her birinde hayr vardır. Sana fayda veren şeye çaba göster;","Allah'dan yardım dile ve âciz olma! Başına bir say gelirse şöyle yapsam şöyle olurdu deme!","Velâkin (bu) Allah'ın kaderi, O ne dilerse yapar, de! Çünkü eğer (kelimesi) şeytanın amelini açar.» buyurdular"],"ur":["حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا :","\" طاقت ور مومن اللہ کے نزدیک کمزور مومن کی نسبت بہتر اور زیادہ محبوب ہے ، جبکہ خیر دونوں میں ( موجود ) ہے ۔ جس چیز سے تمہیں ( حقیقی ) نفع پہنچے اس میں حرص کرو اور اللہ سے مدد مانگو اور کمزور نہ پڑو ( مایوس ہو کر نہ بیٹھ ) جاؤ ،","اگر تمہیں کوئی ( نقصان ) پہنچے تو یہ نہ کہو : کاش!","میں ( اس طرح ) کرتا تو ایسا ایسا ہوتا ، بلکہ یہ کہو : ( یہ ) اللہ کی تقدیر ہے ،","وہ جو چاہتا ہے کرتا ہے ، اس لیے کہ ( حشرت کرتے ہوئے ) کاش ( کہنا ) شیطان کے عمل ( کے دروازے ) کو کھول دیتا ہے ۔"],"id":["Telah menceritakan kepada kami [Abu Bakr bin Abu Syaibah] dan [Ibnu Numair] mereka berdua berkata; telah menceritakan kepada kami ['Abdullah bin Idris] dari [Rabi'ah bin 'Utsman] dari [Muhammad bin Yahya bin Habban] dari [Al A'raj] dari [Abu Hurairah] dia berkata;","\"Rasulullah shallallahu 'alaihi wasallam bersabda: 'Orang mukmin yang kuat lebih baik dan lebih dicintai oleh Allah Subhanahu wa Ta 'ala daripada orang mukmin yang lemah.","Pada masing-masing memang terdapat kebaikan. Capailah dengan sungguh-sungguh apa yang berguna bagimu, mohonlah pertolongan kepada Allah Azza wa Jalla dan janganlah kamu menjadi orang yang lemah. Apabila kamu tertimpa suatu kemalangan,","maka janganlah kamu mengatakan; 'Seandainya tadi saya berbuat begini dan begitu,","niscaya tidak akan menjadi begini dan begitu'. Tetapi katakanlah; 'lni sudah takdir Allah dan apa yang dikehendaki-Nya pasti akan dilaksanakan-Nya. Karena sesungguhnya ungkapan kata 'law' (seandainya) akan membukakan jalan bagi godaan syetan"],"bn":["আবূ বাকর ইবনু আবূ শাইবাহ ও ইবনু নুমায়র (রহঃ) ..... আবু হুরাইরাহ্ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন,","রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ শক্তিধর ঈমানদার দুর্বল ঈমানদারের তুলনায় আল্লাহর নিকট উত্তম ও অতীব পছন্দনীয়। তবে প্রত্যেকের মধ্যেই কল্যাণ নিহিত আছে,","যাতে তোমার উপকার রয়েছে তা অর্জনে তুমি আগ্রহী হও এবং আল্লাহর কাছে সাহায্য কামনা কর। তুমি অক্ষম হয়ে যেও না। এমন বলো না যে,","যদি আমি এমন এমন করতাম তবে এমন হত না। বরং এ কথা বলে যে,","আল্লাহ তা’আলা যা নির্দিষ্ট করেছেন এবং যা চেয়েছেন তাই করেছেন। কেননাلَوْ (যদি) শব্দটি শাইতানের (শয়তানের) কর্মের দুয়ার খুলে দেয়। (ইসলামিক ফাউন্ডেশন ৬৫৩২, ইসলামিক সেন্টার)"],"ru":["Передаётся от Абу Хурайры (да будет доволен им Аллах), что Посланник Аллаха ﷺ сказал:","«Сильный верующий лучше и любимее перед Аллахом, чем верующий слабый, однако в каждом из них есть благо. Будь упорным в том, что приносит тебе пользу,","испрашивай помощи у Аллаха и не сдавайся. А если постигнет тебя нечто, то не говори: “Если бы я сделал так-то,","то всё было бы так-то и так-то…”, отнюдь говори: “Это предопределил Аллах,","и Он сделал так, как Ему было угодно”, поскольку “если бы...” открывает возможность для козней шайтана»"]}},"h_ihsan":{"src":"muslim 5055","w":["عَنْ","رَسُولِ","اللَّهِ","صلى","الله","عليه","وسلم","قَالَ","إِنَّ","اللَّهَ","كَتَبَ","الإِحْسَانَ","عَلَى","كُلِّ","شَىْءٍ","فَإِذَا","قَتَلْتُمْ","فَأَحْسِنُوا","الْقِتْلَةَ","وَإِذَا","ذَبَحْتُمْ","فَأَحْسِنُوا","الذَّبْحَ","وَلْيُحِدَّ","أَحَدُكُمْ","شَفْرَتَهُ","فَلْيُرِحْ","ذَبِيحَتَهُ."],"p":[[0,12],[12,24],[24,28]],"m":{"en":["Shaddid b. Aus said:Two are the things which I remember Allah's Messenger (ﷺ) having said:","Verily Allah has enjoined goodness to everything; so when you kill, kill in a good way and when you slaughter, slaughter in a good way. So every one of you should sharpen his knife,","and let the slaughtered animal die comfortably"],"fr":["Rapporté par Shaddid ibn Aus : Je me souviens de deux choses que le Messager d’Allah ﷺ a dites : « En vérité,","Allah a prescrit la bienfaisance en toute chose. Donc, lorsque vous tuez, faites-le de la meilleure façon, et lorsque vous égorgez, égorgez de la meilleure façon.","Que chacun d’entre vous aiguise bien son couteau et épargne à l’animal toute souffrance. »"],"tr":["Bize Ebû Bekir b. Ebî Şeybe rivayet etti. (Dediki): Bi­ze ismail b. Uleyye Halid EI-Hazzâ'dan, o da Ebû Kılabe'den, o da Ebû'I-Eş'as'dan, o da Şeddâd b.","Evs'den naklen rivayet etti. (Şöyle demiş): iki şey varki, bunları Resûlullah (Sallallahu Aleyhi ve Sellem)'den belledim. Buyurdular ki: «Şüphesiz Allah herşeyde iyiliği farz kılmıştır. O halde siz öldürdüğünüz vakit, öldürmeyi iyi yapın.","Kestiğiniz zaman da kesmeyi iyi becerin. Her biriniz bıçağını bilesin. Ve kestiği hayvana rahat versin!»"],"ur":["اسماعیل بن علیہ نے خالد حذا ء سے ، انھوں نے ابوقلابہ سے ، انھوں نے ابو اشعث سے اور انھوں نے حضرت شداد بن اوس رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا :","دو باتیں ہیں جو میں نے رسول اللہ صلی اللہ علیہ وسلم سے یاد رکھی ہیں ، آپ صلی اللہ علیہ وسلم نے فرمایا؛ \" اللہ تعالیٰ نے ہر چیز کے ساتھ سب سے اچھا طریقہ اختیار کرنے کا حکم دیا ہے ۔ اس لئے جب تم ( قصاص یاحد میں کسی کو ) قتل کرو تو اچھے طریقے سے قتل کرو ، اور جب ذبح کرو تو اچھے طریقے سے ذبح کرو ،","تم میں سے ایک شخص ( جو ذبح کرنا چاہتا ہے ) وہ اپنی ( چھری کی ) دھار کو تیز کرلے اور ذبح کیے جانے والے جانور کو اذیت سے بچائے ۔"],"id":["Telah menceritakan kepada kami [Abu Bakar bin Abu Syaibah] telah menceritakan kepada kami [Isma'il bin 'Ulayyah] dari [Khalid Al Khaddza`] dari [Abu Qilabah] dari [Abu Al Asy'ats] dari [Syaddad bin Aus] dia berkata, \"Dua perkara yang selalu saya ingat dari Rasulullah shallallahu 'alaihi wasallam, beliau bersabda: \"Sesungguhnya Allah telah mewajibkan supaya selalu bersikap baik terhadap setiap sesuatu,","jika kamu membunuh maka bunuhlah dengan cara yang baik, jika kamu menyembelih maka sembelihlah dengan cara yang baik, tajamkan pisaumu dan senangkanlah hewan sembelihanmu.\" Dan telah menceritakan kepada kami [Yahya bin Yahya] telah menceritakan kepada kami [Husyaim]. (dalam jalur lain disebutkan) Telah menceritakan kepada kami [Ishaq bin Ibrahim] telah mengabarkan kepada kami [Abdul Wahhab At Tsaqafi]. (dalam jalur lain disebutkan) Telah menceritakan kepada kami [Abu Bakar bin Nafi'] telah menceritakan kepada kami [Ghundar] telah menceritakan kepada kami [Syu'bah]. (dalam jalur lain disebutkan) Telah menceritakan kepada kami [Abdullah bin Abdurrahman Ad Darimi] telah mengabarkan kepada kami [Muhammad bin Yusuf] dari [Sufyan].","(dalam jalur lain disebutkan) Telah menceritakan kepada kami [Ishaq bin Ibrahim] telah mengabarkan kepada kami [Jarir] dari [Manshur] mereka semua dari [Khalid Al Khaddza`] dengan sanad dan makna yang sama dengan hadits Ibnu 'Ulayyah"],"bn":["আবূ বাকর ইবনু আবূ শাইবাহ (রহঃ) ..... শাদ্দাদ ইবনু আওস (রহঃ) হতে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হতে আমি দুটি কথা মনে রেখেছি,","তিনি বলেছেনঃ আল্লাহ তা'আলা প্রত্যেক বিষয়ে তোমাদের উপর ইহসান অত্যাবশ্যক করেছেন। অতএব তোমরা যখন হত্যা করবে, দয়ার্দ্রতার সঙ্গে হত্যা করবে;","আর যখন যাবাহ করবে তখন দয়ার সঙ্গে যাবাহ করবে। তোমাদের সবাই যেন ছুরি ধারালো করে নেয় এবং তার যাবাহকৃত জন্তুকে কষ্টে না ফেলে। (ইসলামিক ফাউন্ডেশন ৪৮৯৭ ইসলামিক সেন্টার)"]}},"h_tamra":{"src":"bukhari 1417","w":["سَمِعْتُ","رَسُولَ","اللَّهِ","صلى","الله","عليه","وسلم","يَقُولُ","اتَّقُوا","النَّارَ","وَلَوْ","بِشِقِّ","تَمْرَةٍ."],"p":[[0,13]],"m":{"en":["Narrated `Adi bin Hatim heard the Prophet (ﷺ) saying:\"Save yourself from Hell-fire even by giving half a date-fruit in charity"],"fr":["Rapporté par `Adi bin Hatim : J'ai entendu le Prophète (ﷺ) dire : « Protégez-vous du Feu de l'Enfer, même en donnant la moitié d'une datte en aumône. »"],"tr":["Adiy bin Hatim r.a. Rasûlullah Sallallahu Aleyhi ve Sellem'in şöyle buyurduğunu işittim demiştir: ‘’Yarım hurmayla bile olsa cehennem'den korunun"],"ur":["ہم سے سلیمان بن حرب نے بیان کیا ‘ کہا کہ ہم سے شعبہ نے بیان کیا اور ان سے ابواسحاق عمرو بن عبداللہ سبیعی نے کہا کہ میں نے عبداللہ بن معقل سے سنا ‘ انہوں نے کہا کہ میں نے عدی بن حاتم رضی اللہ عنہ سے سنا ‘ انہوں نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ کہتے سنا کہ جہنم سے بچو اگرچہ کھجور کا ایک ٹکڑا دے کر ہی سہی ( مگر ضرور صدقہ کر کے دوزخ کی آگ سے بچنے کی کوشش کرو ) ۔"],"id":["Telah menceritakan kepada kami [Sulaiman bin Harb] telah menceritakan kepada kami [Syu'bah] dari [Abu Ishaq] berkata, aku mendengar ['Abdullah bin Ma'qil] berkata, aku mendengar ['Adiy bin Hatim radliallahu 'anhu] berkata, aku mendengar Rasulullah Shallallahu'alaihiwasallam bersabda: \"Jagalah kalian dari neraka sekalipun dengan (bershadaqah) sebutir kurma"],"bn":["‘আদী ইবনু হাতিম (রাঃ) হতে বর্ণিত। তিনি বলেন, আমি নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম -কে বলতে শুনেছি, তোমরা জাহান্নাম হতে আত্মরক্ষা কর এক টুকরা খেজুর সদাকাহ করে হলেও। (১৪১৩) (আধুনিক প্রকাশনীঃ ১৩২৫, ইসলামিক ফাউন্ডেশনঃ)"],"ru":["Сообщается, что ‘Ади ибн Хатим, да будет доволен им Аллах, сказал: «Я слышал, как Посланник Аллаха ﷺ сказал: “Защитите (себя) от Огня хотя бы половинкой финика”»"]}},"h_awn":{"src":"muslim 6853","w":["عَنْ","أَبِي","هُرَيْرَةَ،","قَالَ","قَالَ","رَسُولُ","اللَّهِ","صلى","الله","عليه","وسلم","مَنْ","نَفَّسَ","عَنْ","مُؤْمِنٍ","كُرْبَةً","مِنْ","كُرَبِ","الدُّنْيَا","نَفَّسَ","اللَّهُ","عَنْهُ","كُرْبَةً","مِنْ","كُرَبِ","يَوْمِ","الْقِيَامَةِ","وَمَنْ","يَسَّرَ","عَلَى","مُعْسِرٍ","يَسَّرَ","اللَّهُ","عَلَيْهِ","فِي","الدُّنْيَا","وَالآخِرَةِ","وَمَنْ","سَتَرَ","مُسْلِمًا","سَتَرَهُ","اللَّهُ","فِي","الدُّنْيَا","وَالآخِرَةِ","وَاللَّهُ","فِي","عَوْنِ","الْعَبْدِ","مَا","كَانَ","الْعَبْدُ","فِي","عَوْنِ","أَخِيهِ","وَمَنْ","سَلَكَ","طَرِيقًا","يَلْتَمِسُ","فِيهِ","عِلْمًا","سَهَّلَ","اللَّهُ","لَهُ","بِهِ","طَرِيقًا","إِلَى","الْجَنَّةِ","وَمَا","اجْتَمَعَ","قَوْمٌ","فِي","بَيْتٍ","مِنْ","بُيُوتِ","اللَّهِ","يَتْلُونَ","كِتَابَ","اللَّهِ","وَيَتَدَارَسُونَهُ","بَيْنَهُمْ","إِلاَّ","نَزَلَتْ","عَلَيْهِمُ","السَّكِينَةُ","وَغَشِيَتْهُمُ","الرَّحْمَةُ","وَحَفَّتْهُمُ","الْمَلاَئِكَةُ","وَذَكَرَهُمُ","اللَّهُ","فِيمَنْ","عِنْدَهُ","وَمَنْ","بَطَّأَ","بِهِ","عَمَلُهُ","لَمْ","يُسْرِعْ","بِهِ","نَسَبُهُ."],"p":[[0,12],[12,24],[24,36],[36,48],[48,60],[60,72],[72,84],[84,96],[96,101]],"m":{"en":["Abu Huraira reported Allah's Messenger (ﷺ) as saying:He who alleviates the suffering of a brother out of the sufferings of the world,","Allah would alleviate his suffering from the sufferings of the Day of Resurrection,","and he who finds relief for one who is hard-pressed, Allah would make things easy for him in the Hereafter,","and he who conceals (the faults) of a Muslim, Allah would conceal his faults in the world and in the Hereafter.","Allah is at the back of a servant so long as the servant is at the back of his brother, and he who treads the path in search of knowledge,","Allah would make that path easy,","leading to Paradise for him and those persons who assemble in the house among the houses of Allah (mosques) and recite the Book of Allah and they learn and teach the Qur'an (among themselves) there would descend upon them tranquility and mercy would cover them and the angels would surround them and Allah mentions them in the presence of those near Him,","and he who is slow-paced in doing good deeds,","his (high) lineage does not make him go ahead"],"fr":["Rapporté par Abu Huraira رضي الله عنه : Le Messager d’Allah ﷺ a dit :","« Celui qui soulage un frère d’une difficulté de ce monde, Allah le soulagera d’une difficulté du Jour de la Résurrection.","Celui qui vient en aide à une personne en difficulté, Allah lui facilitera les choses dans l’au-delà.","Celui qui couvre les défauts d’un musulman, Allah couvrira ses défauts dans ce monde et dans l’au-delà.","Allah aide le serviteur tant que celui-ci aide son frère. Celui qui emprunte un chemin pour rechercher la connaissance,","Allah lui facilitera un chemin vers le Paradis.","Quand des gens se réunissent dans une des maisons d’Allah (les mosquées) pour réciter le Livre d’Allah, l’étudier et l’enseigner entre eux, la tranquillité descend sur eux,","la miséricorde les couvre, les anges les entourent et Allah les mentionne auprès de ceux qui sont auprès de Lui. Et celui qui tarde à faire de bonnes actions,","sa noble lignée ne le fera pas avancer. »"],"tr":["Bize Yahya b. Yahya Et-Temîmî ile Ebû Bekr b. Ebî Şeybe ve Muhammed b. Ala' El-Hemdani rivayet ettiler.","Lafız Yahya'nındir. (Yahya: Ahberana; ötekilerse: Haddesena tabirlerim kullandılar. Dedilerki): Bize Ebû Muaviyc, A'meş'den,","o da Ebu Salih'den, o da Ebu Hureyre'den naklen rivayet elti. (Şöyle demiş): Resulullah (Sallalluhu Aleyhi ve Sellem):","«Bir kimse bir mu'minden dünya sıkıntılarından bir sıkıntı giderirse; Allah ondan ahiret stkınrilanndan bir sıkıntı giderir. Bir kimse başı sıkılana kolaylık gösterirse,","Allah ona dünya ve ahirette kolaylık verir. Ve bir kimse bir müslümanı (n günahını) örtbas ederse,","Allah da onu dünya ve ahirette örtbas eder. Kul din kardeşinin yardımında oldukça, Allah da kulun yardımındadır. Ve her kim bir yol tutarak,","o yolda ilim ararsa, bu sebeple Allah ona cennete götüren bir yol müyesser kılar. Bir kavim Allah'ın evlerinden bir evde toplanarak kitabullahı okurlar ve onu aralarında müzakere ederlerse;","üzerlerine sekinet iner. Allah'ın rahmeti onları kaplar. Melekler de etraflarını kuşatırlar. Allah onları kendi nezdindekilere anar.","Bir kimseyi ameli yavaşlatırsa, nesebi hızlandıramaz.» buyurdular"],"ur":["ابومعاویہ نے اعمش سے ، انہوں نے ابوصالح سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا :","رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس شخص نے کسی مسلمان کی دنیاوی تکلیفوں میں سے کوئی تکلیف دور کی ،","اللہ تعالیٰ اس کی قیامت کی تکلیفوں میں سے کوئی تکلیف دور کرے گا اور جس شخص نے کسی تنگ دست کے لیے آسانی کی ،","اللہ تعالیٰ اس کے لیے دنیا اور آخرت میں آسانی کرے گا اور جس نے کسی مسلمان کی پردہ پوشی کی ،","اللہ تعالیٰ دنیا اور آخرت میں اس کی پردہ پشی کرے گا اور اللہ تعالیٰ اس وقت تک بندے کی مدد میں لگا رہتا ہے جب تک بندہ اپنے بھائی کی مدد میں لگا رہتا ہے اور جو شخص اس راستے پر چلتا ہے جس میں وہ علم حاصل کرنا چاہتا ہے تو اللہ تعالیٰ اس کے ذریعے سے اس کے لیے جنت کا راستہ آسان کر دیتا ہے ،","اللہ کے گھروں میں سے کسی گھر میں لوگوں کا کوئی گروہ اکٹھا نہیں ہوتا ،","","وہ قرآن کی تلاوت کرتے ہیں اور اس کا درس و تدریس کرتے ہیں مگر ان پر سکینت ( اطمینان و سکون قلب ) کا نزول ہوتا ہے اور ( اللہ کی ) رحمت ان کو ڈھانپ لیتی ہے اور فرشتے ان کو اپنے گھیرے میں لے لیتے ہیں اور اللہ تعالیٰ اپنے مقربین میں جو اس کے پاس ہوتے ہیں ان کا ذکر کرتا ہے اور جس کے عمل نے اسے ( خیر کے حصول میں ) پیچھے رکھا ،","اس کا نسب اسے تیز نہیں کر سکتا ۔"],"id":["Telah menceritakan kepada kami [Yahya bin Yahya At Tamimi] dan [Abu Bakr bin Abu Syaibah] dan [Muhammad bin Al 'Ala Al Hamdani] -dan lafadh ini milik Yahya- dia berkata;","telah mengabarkan kepada kami, dan berkata yang lainnya, telah menceritakan kepada kami [Abu Mu'awiyah] dari [Al A'masy] dari [Abu Shalih] dari [Abu Hurairah] dia berkata; Rasulullah shallallahu 'alaihi wasallam telah bersabda:","'Barang siapa membebaskan seorang mukmin dari suatu kesulitan dunia, maka Allah akan membebaskannya dari suatu kesulitan pada hari kiamat. Barang siapa memberi kemudahan kepada orang yang berada dalam kesulitan,","maka Allah akan memberikan kemudahan di dunia dan akhirat. Barang siapa menutupi aib seorang muslim, maka Allah akan menutup aibnya di dunia dan akhirat. Allah akan selalu menolong hamba-Nya selama hamba tersebut menolong saudaranya sesama muslim. Barang siapa menempuh jalan untuk mencari ilmu,","maka Allah akan memudahkan jalan ke surga baginya. Tidaklah sekelompok orang berkumpul di suatu masjid (rumah Allah) untuk membaca Al Qur'an, melainkan mereka akan diliputi ketenangan, rahmat,","dan dikelilingi para malaikat, serta Allah akan menyebut-nyebut mereka pada malaikat-malaikat yang berada di sisi-Nya. Barang siapa yang ketinggalan amalnya,","maka nasabnya tidak juga meninggikannya.' Telah menceritakan kepada kami [Muhammad bin 'Abdullah bin Numair] telah menceritakan kepada kami [Bapakku] Demikian juga diriwayatkan dari jalur lainnya, dan telah menceritakannya kepada kami [Nashr bin 'Ali Al Jahdhami] telah menceritakan kepada kami [Abu Usamah] mereka berkata;","telah menceritakan kepada kami [Al A'masy] -telah menceritakan kepada kami Ibnu Numair- dari [Abu Shalih]. Sebagaimana di dalam hadits Abu Usamah Telah menceritakan kepada kami Abu Shalih dari [Abu Hurairah] dia berkata; Rasulullah shallallahu 'alaihi wasallam berkata dengan lantang, -sebagaimana Hadits Abu Mu'awiyah,","hanya saja di dalam Hadits Abu Usamah tidak disebutkan; memberi kemudahan kepada orang yang kesusahan"],"bn":["ইয়াহইয়া ইবনু ইয়াহইয়া আত তামীমী, আবু বাকর ইবনু আবূ শাইবাহ ও মুহাম্মাদ ইবনুল আলা আল হামদানী (রহঃ) .....","আবু হুরাইরাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ যে লোক কোন ঈমানদারের দুনিয়া থেকে কোন মুসীবাত দূর করে দিবে,","আল্লাহ তা’আলা বিচার দিবসে তার থেকে মুসীবাত সরিয়ে দিবেন। যে লোক কোন দুঃস্থ লোকের অভাব দূর করবে,","আল্লাহ তাআলা দুনিয়া ও আখিরাতে তার দুরবস্থা দূর করবেন। যে লোক কোন মুসলিমের দোষ-ত্রুটি লুকিয়ে রাখবে আল্লাহ তা’আলা দুনিয়া ও আখিরাতে তার দোষ-ত্রুটি লুকিয়ে রাখবেন। বান্দা যতক্ষণ তার ভাই এর সহযোগিতায় আত্মনিয়োগ করে আল্লাহ ততক্ষণ তার সহযোগিতা করতে থাকেন। যে লোক জ্ঞানার্জনের জন্য রাস্তায় বের হয়,","","","আল্লাহ এর বিনিময়ে তার জন্য জান্নাতের পথ সহজ করে দেন। যখন কোন সম্প্রদায় আল্লাহর গৃহসমূহের কোন একটি গৃহে একত্রিত হয়ে আল্লাহর কিতাব পাঠ করে এবং একে অপরের সাথে মিলে (কুরআন) অধ্যয়নে লিপ্ত থাকে তখন তাদের উপর শান্তিধারা অবতীর্ণ হয়। রহমত তাদেরকে আচ্ছন্ন করে ফেলে এবং ফেরেশতাগণ তাদেরকে পরিবেষ্টন করে রাখেন। আর আল্লাহ তা’আলা তার নিকটবর্তীদের (ফেরেশতাগণের) মধ্যে তাদের কথা আলোচনা করেন। আর যে লোককে আমলে পিছনে সরিয়ে দিবে তার বংশ (মর্যাদা) তাকে অগ্রসর করে দিবে না* (ইসলামিক ফাউন্ডেশন ৬৬০৮,","","ইসলামিক সেন্টার)"],"ru":["Сообщается, что Абу Хурайра (да будет доволен им Аллах) сказал: «Посланник Аллаха ﷺ сказал:","“Того, кто избавит верующего от одной из печалей мира этого,","Аллах избавит от одной из печалей Дня воскрешения, тому, кто облегчит положение несостоятельного (должника), Аллах облегчит положение его и в мире этом,","и в мире ином, а того, кто покроет мусульманина, Аллах покроет и в мире этом, и в мире ином.","Аллах будет оказывать помощь (Своему) рабу, пока сам раб оказывает её брату своему.","Вступившему на какой-нибудь путь в поисках знания Аллах за это облегчит путь в рай,","а когда люди собираются в одном из домов Аллаха, где они совместно читают и изучают Книгу Аллаха, обязательно нисходит на них спокойствие,","и покрывает их милость, и окружают их ангелы и поминает их Аллах среди тех, кто находится пред Ним, а тому, кого станут задерживать дела его,","происхождение его не поможет двигаться быстрее”»"]}},"h_yad":{"src":"bukhari 1429","w":["أَنَّ","رَسُولَ","اللَّهِ","صلى","الله","عليه","وسلم","قَالَ","وَهُوَ","عَلَى","الْمِنْبَرِ،","وَذَكَرَ","الصَّدَقَةَ","وَالتَّعَفُّفَ","وَالْمَسْأَلَةَ","الْيَدُ","الْعُلْيَا","خَيْرٌ","مِنَ","الْيَدِ","السُّفْلَى،","فَالْيَدُ","الْعُلْيَا","هِيَ","الْمُنْفِقَةُ،","وَالسُّفْلَى","هِيَ","السَّائِلَةُ."],"p":[[0,11],[11,21],[21,28]],"m":{"en":["Narrated Ibn `Umar:I heard Allah's Messenger (ﷺ) while he was on the pulpit speaking about charity,","to abstain from asking others for some financial help and about begging others, saying, \"The upper hand is better than the lower hand.","The upper hand is that of the giver and the lower (hand) is that of the beggar"],"fr":["Rapporté par Ibn `Umar : J'ai entendu le Messager d'Allah (ﷺ) alors qu'il était sur le minbar parler de l'aumône,","de l'importance de ne pas demander aux autres une aide financière et de ne pas mendier, en disant : « La main qui donne est meilleure que celle qui reçoit.","La main qui donne est celle du donateur et la main qui reçoit est celle du mendiant. »"],"tr":["Abdullah İbn Ömer r.a. Resululıah Sallallahu Aleyhi ve Sellem'in hutbede,","Sadaka, iffetli (onurlu) kalma ye dilencilikle ilgili bir konuşma yaparken şöyle buyurduğunu işittim demiştir:","\"Üstteki el, alttaki elden daha hayırlıdır. üstteki, veren; alttaki ise dilenen eldir"],"ur":["","ہم سے ابوالنعمان نے بیان کیا ‘ کہا کہ ہم سے حماد بن زید نے بیان کیا ‘ ان سے ایوب نے ‘ ان سے نافع نے اور ان سے ابن عمر رضی اللہ عنہما نے کہ میں نے نبی کریم صلی اللہ علیہ وسلم سے سنا۔ ( دوسری سند ) اور ہم سے عبداللہ بن مسلمہ نے بیان کیا ‘ ان سے مالک نے ‘ ان سے نافع نے اور ان سے عبداللہ بن عمر رضی اللہ عنہما نے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جب کہ آپ منبر پر تشریف رکھتے تھے۔ آپ نے صدقہ اور کسی کے سامنے ہاتھ نہ پھیلانے کا اور دوسروں سے مانگنے کا ذکر فرمایا اور فرمایا کہ اوپر والا ہاتھ نیچے والے ہاتھ سے بہتر ہے۔ اوپر کا ہاتھ خرچ کرنے والے کا ہے اور نیچے کا ہاتھ مانگنے والے کا۔",""],"id":["Telah menceritakan kepada kami [Abu An-Nu'man] berkata, telah menceritakan kepada kami [Hammad bin Zaid] dari [Ayyub] dari [Nafi'] dari [Ibnu'Umar radliallahu 'anhuma] berkata;","Aku mendengar Nabi Shallallahu'alaihiwasallam. Dan telah menceritakan kepada kami ['Abdullah bin Maslamah] dari [Malik] dari [Nafi'] dari ['Abdullah bin 'Umar radliallahu 'anhua] bahwa Rasulullah Shallallahu'alaihiwasallam bersabda ketika berada di atas mimbar,","diantaranya Beliau menyebut tentang shadaqah dan masalah tangan yang diatas lebih baik dari pada tangan yang di bawah. Tangan yang diatas adalah yang memberi (mengeluarkan infaq) sedangkan tangan yang di bawah adalah yang meminta"],"bn":["ইবনু ‘উমার (রাঃ) হতে বর্ণিত যে,","আল্লাহর রাসূল সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম একদা মিম্বারের উপর থাকা অবস্থায় সদাকাহ করা ও ভিক্ষা করা হতে বেঁচে থাকা ও ভিক্ষা করা প্রসঙ্গ উল্লেখ করে বলেনঃ উপরের হাত নীচের হাত অপেক্ষা উত্তম। উপরের হাত দাতার,","আর নীচের হাত হলো ভিক্ষুকের। (মুসলিম ১২/৩২, হাঃ ১০৩৩, আহমাদ ৪৪৭৪) (আধুনিক প্রকাশনীঃ ১৩৩৬, ইসলামিক ফাউন্ডেশনঃ)"],"ru":["Сообщается, что ‘Абдуллах бин ‘Умар, да будет доволен Аллах ими обоими, сказал:","«Однажды Посланник Аллаха ﷺ (произносивший проповедь) с минбара, упомянул о милостыне, стремлении к воздержанию и нищенстве и сказал:","“Высшая рука лучше руки низшей. Высшая рука — это рука расходующего, а низшая — рука просящего”»"]}},"h_maruf":{"src":"muslim 6690","w":["عَنْ","أَبِي","ذَرٍّ،","قَالَ","قَالَ","لِيَ","النَّبِيُّ","صلى","الله","عليه","وسلم","لاَ","تَحْقِرَنَّ","مِنَ","الْمَعْرُوفِ","شَيْئًا","وَلَوْ","أَنْ","تَلْقَى","أَخَاكَ","بِوَجْهٍ","طَلْقٍ."],"p":[[0,12],[12,22]],"m":{"en":["Abu Dharr reported:Allah's Apostle (ﷺ) said to me:","Don't consider anything insignificant out of good things even if it is that you meet your brother with a cheerful countenance"],"fr":["Rapporté par Abu Dharr رضي الله عنه : Le Messager d’Allah ﷺ m’a dit :","« Ne considère jamais un acte de bien comme insignifiant, même si c’est simplement de rencontrer ton frère avec le sourire. »"],"tr":["Bana Ebû Gassan El-Mismaî rivayet etti. (Dediki): Bize Osman b. Ömer rivayet etti. (Dediki): Bize Ebû Âmir (yâni El-Hazzâz) Ebû İmran El-Cevni'den, o da Abdullah b.","Samit'den, o da Ebû Zer'den naklen rivayet etti. (Şöyle demiş): Bana Nebi (Sallallahu Aleyhi ve Sellem): «Sakın maruftan hiç bir şeyi hakir görme! Velev din kardeşini güier yüzle karşılaman olsun!» buyurdular"],"ur":["حضرت ابوذر رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا :","\" نیکی میں کسی چیز کو حقیر نہ سمجھو ، چاہے یہی ہو کہ تم اپنے ( مسلمان ) بھائی کو کھلتے ہوئے چہرے سے ملو ۔"],"id":["Telah menceritakan kepadaku [Abu Ghassan Al Misma'i]; Telah menceritakan kepada kami ['Utsman bin 'Umar]; Telah menceritakan kepada kami [Abu 'Amir] yaitu Al Khazzaz dari [Abu 'Imran Al Jauni] dari ['Abdullah bin Ash Shamit] dari [Abu Dzar] dia berkata;","Nabi shallallahu 'alaihi wasallam berkata kepadaku: \"Janganlah kamu menganggap remeh sedikitpun terhadap kebaikan, walaupun kamu hanya bermanis muka kepada saudaramu (sesama muslim) ketika bertemu"],"bn":["আবূ গাসসান আল মিসমাঈ (রহঃ) ..... আবু যর (রাযিঃ) থেকে বর্ণিত। তিনি বলেন,","নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম আমাকে বলেছেনঃ ভালো কোন কিছু দান করাকে হীন মনে করো না, এমনকি হোক সেটা ভাইয়ের সাথে হাসিমুখে সাক্ষাৎ দেয়া। (ইসলামিক ফাউন্ডেশন ৬৪৫১, ইসলামিক সেন্টার)"]}},"h_ajaban":{"src":"muslim 7500","w":["عَنْ","صُهَيْبٍ،","قَالَ","قَالَ","رَسُولُ","اللَّهِ","صلى","الله","عليه","وسلم","عَجَبًا","لأَمْرِ","الْمُؤْمِنِ","إِنَّ","أَمْرَهُ","كُلَّهُ","خَيْرٌ","وَلَيْسَ","ذَاكَ","لأَحَدٍ","إِلاَّ","لِلْمُؤْمِنِ","إِنْ","أَصَابَتْهُ","سَرَّاءُ","شَكَرَ","فَكَانَ","خَيْرًا","لَهُ","وَإِنْ","أَصَابَتْهُ","ضَرَّاءُ","صَبَرَ","فَكَانَ","خَيْرًا","لَهُ."],"p":[[0,12],[12,24],[24,36]],"m":{"en":["","Suhaib reported that Allah's Messenger (ﷺ) said:Strange are the ways of a believer for there is good in every affair of his and this is not the case with anyone else except in the case of a believer for if he has an occasion to feel delight, he thanks (God),","thus there is a good for him in it, and if he gets into trouble and shows resignation (and endures it patiently), there is a good for him in it"],"fr":["Rapporté par Suhaib رضي الله عنه : Le Messager d’Allah ﷺ a dit : « Les affaires du croyant sont étonnantes,","car tout ce qui lui arrive est un bien pour lui, et cela n’est vrai que pour le croyant. S’il lui arrive quelque chose de plaisant,","il remercie (Allah), et c’est un bien pour lui. S’il lui arrive un malheur et qu’il patiente, c’est aussi un bien pour lui. »"],"tr":["Bize Heddâb b, Hâlid El-Ezdî ile Şeyban b. Ferrûh hep birden Süleyman b. Muğîra'dan rivayet ettiler. Lâfız Seyban'ındır. (Dediki): Bize Süleyman rivayet etti.","(Dediki): Bize Sabit, Abdurrahman b. Ebî Leylâ'dan, o da Suhayb'den naklen rivayet etti. (Şöyle demiş) Resulullah Salîallahu Aleyhi ve Sellem: «Mü'minin işine şaşarım. Gerçekten onun bütün işleri hayırdır.","bu mü'minden başka hiç bir kimsede yoktur. Kendisine varlık isabet ederse şükreyler, bu onun için hayr olur. Darlık isabet ederse sabreyler, bu da onu için hayr olur.» buyurdular"],"ur":["حضرت صہیب رضی اللہ تعالیٰ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا :","\" مومن کا معاملہ عجیب ہے ۔ اس کا ہرمعاملہ اس کے لیے بھلائی کا ہے ۔ اور یہ بات مومن کے سوا کسی اور کومیسر نہیں ۔ اسے خوشی اور خوشحالی ملے توشکر کرتا ہے ۔ اور یہ اس کے لیے اچھا ہوتا ہے اور اگر اسے کوئی نقصان پہنچے تو ( اللہ کی رضا کے لیے ) صبر کر تا ہے ،","یہ ( ابھی ) اس کے لیے بھلائی ہوتی ہے ۔"],"id":["Telah menceritakan kepada kami [Haddab bin Khalid Al Azdi] dan [Syaiban bin Farrukh] semuanya dari [Sulaiman bin Al Mughirah] dan teksnya meriwayatkan milik Syaiban,","telah menceritakan kepada kami [Sulaiman] telah menceritakan kepada kami [Tsabit] dari [Abdurrahman bin Abu Laila] dari [Shuhaib] berkata: Rasulullah Shallallahu 'alaihi wa Salam bersabda: \"perkara orang mu`min mengagumkan,","sesungguhnya semua perihalnya baik dan itu tidak dimiliki seorang pun selain orang mu`min, bila tertimpa kesenangan, ia bersyukur dan syukur itu baik baginya dan bila tertimpa musibah, ia bersabar dan sabar itu baik baginya"],"bn":["হাদ্দাব ইবনু খালিদ আল আযদী ও শাইবান ইবনু ফাররূখ (রহঃ) .....","সুহায়ব (রাযিঃ) থেকে বর্ণিত। রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ মুমিনের অবস্থা বিস্ময়কর। সকল কাজই তার জন্য কল্যাণকর। মু’মিন ছাড়া অন্য কেউ এ বৈশিষ্ট্য লাভ করতে পারে না। তারা সুখ-শান্তি লাভ করলে শুকর-গুজার করে আর অস্বচ্ছলতা বা দুঃখ-মুসীবাতে আক্রান্ত হলে সবর করে,","প্রত্যেকটাই তার জন্য কল্যাণকর। (ইসলামিক ফাউন্ডেশন ৭২২৯, ইসলামিক সেন্টার)"],"ru":["Сообщается, что Сухайб (ибн Синан), да будет доволен им Аллах, сказал: «Посланник Аллаха ﷺ сказал:","„Сколь удивительно положение верующего! Поистине, всё в положении его является для него благом, и никому (не дано) этого, кроме верующего: если что-нибудь радует его,","он благодарит (Аллаха), и это становится для него благом, если же его постигает горе, он проявляет терпение, и это (тоже) становится для него благом“»"]}},"h_gharib":{"src":"bukhari 6416","w":["أَخَذَ","رَسُولُ","اللَّهِ","صلى","الله","عليه","وسلم","بِمَنْكِبِي","فَقَالَ","كُنْ","فِي","الدُّنْيَا","كَأَنَّكَ","غَرِيبٌ،","أَوْ","عَابِرُ","سَبِيلٍ.","وَكَانَ","ابْنُ","عُمَرَ","يَقُولُ","إِذَا","أَمْسَيْتَ","فَلاَ","تَنْتَظِرِ","الصَّبَاحَ،","وَإِذَا","أَصْبَحْتَ","فَلاَ","تَنْتَظِرِ","الْمَسَاءَ،","وَخُذْ","مِنْ","صِحَّتِكَ","لِمَرَضِكَ،","وَمِنْ","حَيَاتِكَ","لِمَوْتِكَ."],"p":[[0,12],[12,17],[17,26],[26,31],[31,38]],"m":{"en":["Narrated Mujahid:`Abdullah bin `Umar said, \"Allah's Messenger (ﷺ) took hold of my shoulder and said,","'Be in this world as if you were a stranger or a traveler.\" The sub-narrator added:","Ibn `Umar used to say, \"If you survive till the evening, do not expect to be alive in the morning,","and if you survive till the morning, do not expect to be alive in the evening,","and take from your health for your sickness, and (take) from your life for your death"],"fr":["Rapporté par Mujahid : `Abdullah bin `Umar a dit : Le Messager d’Allah (ﷺ) m’a pris par l’épaule et a dit :","« Sois dans ce monde comme un étranger ou un voyageur.","» Le rapporteur a ajouté : Ibn `Umar disait : « Si tu survis jusqu’au soir, ne t’attends pas à vivre jusqu’au matin,","et si tu survis jusqu’au matin, ne t’attends pas à vivre jusqu’au soir.","Tire profit de ta santé avant la maladie, et de ta vie avant la mort. »"],"tr":["Abdullah İbn Ömer r.a.'in şöyle dediği rivayet edilmiştir: Resulullah Sallallahu Aleyhi ve Sellem omzumu tutup \"Dünyada garip veya yolcu gibi ol\" buyurdu. İbn Ömer hep \"Akşam'a kavuştuğunda sabahı, sabaha ulaştığında akşamı bekleme, sağlığında hastalığın için, yaşamında da ölümün için bir şeyler yap\" derdi. Diğer tahric: Tirmizi, zühd; İbn-i Mace, rikak Fethu'l-Bari Açıklaması: \"Dünyada garip veya yolcu gibi ol\" hadisi hakkında et-Tibi şöyle demiştir: Buradaki \"veya\" kelimesi şek için değil, emre icabette seçenek bırakmak içindir. \"J (daha doğrusu)\" manasında demek daha güzelolsa gerek. Böylece kul önce kalacak yeri olmayan bir miskine benzetilmiş, sonra durum daha da ileri bir noktaya götürülerek yolcuya benzetilmiştir. Zira garip, bazen gurbet beldelerinde ikamet edebilmektedir. Ancak uzak bir diyara doğru yola çıkan kimse ise, onu bekleyen vadiler, dağlar, yol kesiciler ve beklenmedik nice tehlikeler vardır. Çünkü o bir an bile durmaz, yoluna devam eder. Bu vecihten olsa gerek İbn Ömer bu ifadenin akabinde \"Akşama kavuştuğunda sabahı,","sabaha ulaştığın da akşamı bekleme\", \"Kendini kabir ehlinden say\" demiştir. Yani hiç yorulmadan yoluna devam et, zira sen bir kusur işleyip yolunu devam ettirmezsen o vadilerde helak olursun. Bu benzetmede benzetilenin anlamı budur. Benzeyen ise \"sağlığında hastalığın için bir şeyler yap\" sözüdür. Yani ömür hiçbir zaman sağlık ve hastalıktan hali olamaz. Dolayısıyla sağlıklı olduğun zamanda kudretin yettiği ölçüde yaşam seyrinden daha fazla mesafe kat etmeye çalış ki, hastalandığında, zayıf düştüğünde kaybettiklerinin yerini doldursun.","Bazıları da şöyle demiştir: Bu hadis dünyadan el çekip zühde dalmaya ve kanaatli olmaya teşvik eder. İmam-ı Nevevi de şöyle demiştir: Bu hadisin manası, dünyaya itimat etme, orayı ebedi kalınacak yer olarak görme, dünyadan gurbetçinin almayacağı şeyleri alma. Bazıları da şöyle demektedir: Yolcu, bir istikamete doğru gitmekte olan kimsedir. Dolayısıyla insan dünyada, efendisi tarafından bir ihtiyaç için başka bir şehre gönderilen köle gibidir. Dolayısıyla o, üstlendiği görevi yerine getirip biran evvel memleketine geri dönmeli ve gereksiz şeylere takılmamalıdır. \"Sağlığında hastalığın için de bir şeyler yap\" yani sağlıklı olduğun zamanlar itaat ve ibadetlerle meşgul ol ki, hastalandığında eksiklik olursa yerini doldurabilsin. \"Hayatında ölümün için bir şeyler yap\". Bunun manası Hakim'in rivayet ettiği İbn Abbas'ın şu merfu hadisiyle daha iyi anlaşılmaktadır. \"Resulullah Sallallahu Aleyhi ve Sellem birine nasihat ederek: Beş şeyden önce şu beş şeyin kıymetini bil: Yaşlanmadan önce gençliğinin;","hastalanmadan. önce sağlığının; fakirleşmeden önce zenginliğinin; meşguliyetten önce boş vaktinin ve ölüm gelmeden önce hayatının kıymetini bil\". Bu hadisi İbnü'l-Mübarek de Kitabu'z-Zühd'de Amr İbn Meymune'nin mürsel rivayetlerinden biri olarak sahih bir tarikle rivayet etmiştir. Bazı alimler şöyle demiştir: İbn Ömer'in sözleri merfu hadiste de yer almaktadır. İsteksizliğe son vermekle ilgilidir. Akıllı kimse daha akşamdan sabahı; sabahtan da akşamı beklememeli ve ölümün kendisini daha erken yakalayabileceğini düşünmelidir. \"Sağlığında hastalığın için bir şeyler yap\" sözü, ölümünden sonra sana faydalı olacağını düşündüğün bazı şeyleri yap anlamındadır.","Sağlıklı günlerinde daha fazla salih ameller işlemekte acele et. Zira hastalık bazen aniden gelir ve yapacaklarımıza mani olur. Dolayısıyla miadına hazırlıksız yakalanan kimse olmaktan korkulmalıdır. Yukarıda zikredilen bu hadis şu hadise zıt değildir: \"Kul hastalandığında veya yolculuğa çıktığında Allah ona sağlıklı ve mukim iken yapmış olduklarının mislini yazar\". Çünkü bu hadis amel işleyen kimse hakkında müjde olarak söylenmiştir. İbn Ömer'in hadisindeki uyarı ise, am el işlemeyen kimseler hakkında varit olmuştur. Çünkü insan hastalanınca yapamadığı ameller için pişmanlık duyar, ancak bu pişmanlık ona fayda getirmez. Hadis-i şerifte Resulullah Sallallahu Aleyhi ve Sellem (insanları) ümmeti için iyilik yapmaya, dünyaya fazla rağbet etmemeye, dünyadan sadece ihtiyaç kadarını almaya teşvik etmiştir"],"ur":["ہم سے علی بن عبداللہ نے بیان کیا، انہوں نے کہا ہم سے محمد بن عبدالرحمٰن ابومنذر طفاوی نے بیان کیا، انہوں نے کہا ہم سے سلیمان اعمش نے بیان کیا،","انہوں نے کہا مجھ سے مجاہد نے بیان کیا،","انہوں نے کہا ہم سے عبداللہ بن عمر رضی اللہ عنہما نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے میرا شانہ پکڑ کر فرمایا ”دنیا میں اس طرح ہو جا جیسے تو مسافر یا راستہ چلنے والا ہو۔“ عبداللہ بن عمر رضی اللہ عنہما فرمایا کرتے تھے شام ہو جائے تو صبح کے منتظر نہ رہو اور صبح کے وقت شام کے منتظر نہ رہو،","","اپنی صحت کو مرض سے پہلے غنیمت جانو اور زندگی کو موت سے پہلے۔"],"id":["Telah menceritakan kepada kami [Ali bin Abdullah] telah menceritakan kepada kami [Muhammad bin Abdurrahman Abu Al Mundzir At Thufawi] dari [Sulaiman Al A'masy] dia berkata;","telah menceritakan kepadaku [Mujahid] dari [Abdullah bin Umar] radliallahu 'anhuma dia berkata;","\"Rasulullah shallallahu 'alaihi wasallam pernah memegang pundakku dan bersabda: 'Jadilah kamu di dunia ini seakan-akan orang asing atau seorang pengembara.\" Ibnu Umar juga berkata;","'Bila kamu berada di sore hari, maka janganlah kamu menunggu datangnya waktu pagi,","dan bila kamu berada di pagi hari, maka janganlah menunggu waktu sore, pergunakanlah waktu sehatmu sebelum sakitmu, dan hidupmu sebelum matimu"],"bn":["‘আবদুল্লাহ্ ইবনু ‘উমার (রাঃ) হতে বর্ণিত। তিনি বলেন,","রাসূলুল্লাহ্ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম একবার আমার দু’ কাঁধ ধরে বললেনঃ তুমি দুনিয়াতে থাক যেন তুমি একজন প্রবাসী অথবা পথচারী। আর ইবনু ‘উমার (রাঃ) বলতেন,","","তুমি সন্ধ্যায় উপনীত হলে সকালের আর অপেক্ষা করো না এবং সকালে উপনীত হলে সন্ধ্যার আর অপেক্ষা করো না। তোমার সুস্থতার সময় তোমার পীড়িত অবস্থার জন্য প্রস্তুতি লও। আর তোমার জীবিত অবস্থায় তোমার মৃত্যুর জন্য প্রস্তুতি লও। [1] (আধুনিক প্রকাশনী- ৫৯৬৮,","ই.ফা)"],"ru":["Сообщается, что ‘Абдуллах бин ‘Умар, да будет доволен Аллах ими обоими, сказал: «(Однажды) Посланник Аллаха ﷺ взял меня за плечо и сказал:","“Будь в этом мире (таким), будто ты чужеземец или путник”».\\n(Передатчик этого хадиса сказал,","что) Ибн ‘Умар, да будет доволен Аллах ими обоими, часто говорил: «Если ты дожил до вечера, то не жди(,","что доживёшь и) до утра, а если ты дожил до утра, то не жди(, что доживёшь и) до вечера,","и бери у твоего здоровья (то, что пригодится) для твоей болезни, а у твоей жизни — (то, что пригодится) для твоей смерти»"]}},"h_bardayn":{"src":"bukhari 574","w":["عَنْ","أَبِيهِ،","أَنَّ","رَسُولَ","اللَّهِ","صلى","الله","عليه","وسلم","قَالَ","مَنْ","صَلَّى","الْبَرْدَيْنِ","دَخَلَ","الْجَنَّةَ."],"p":[[0,12],[12,15]],"m":{"en":["Narrated Abu Bakr bin Abi Musa:My father said, \"Allah's Messenger (ﷺ) said,","'Whoever prays the two cool prayers (`Asr and Fajr) will go to Paradise"],"fr":["Rapporté par Abu Bakr bin Abi Musa : Mon père a dit : Le Messager d’Allah (ﷺ) a dit :","« Celui qui prie les deux prières fraîches (`Asr et Fajr) entrera au Paradis. »"],"tr":["Ebu Bekir İbn Ebî Musa babası kanalıyla Allah Resulü (Sallallahu Aleyhi ve Sellem)'in şöyle dediğini nakletmiştir:","\"iki serin vakitteki namazları kim kılarsa cennete girer"],"ur":["ہم سے ہدبہ بن خالد نے بیان کیا، کہا ہم سے ہمام نے، انہوں نے کہا کہ ہم سے ابوجمرہ نے بیان کیا، ابوبکر بن ابی موسیٰ اشعری رضی اللہ عنہ سے، انہوں نے اپنے باپ سے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ جس نے ٹھنڈے وقت کی دو نمازیں ( وقت پر ) پڑھیں ( فجر اور عصر ) تو وہ جنت میں داخل ہو گا۔ ابن رجاء نے کہا کہ ہم سے ہمام نے ابوجمرہ سے بیان کیا کہ ابوبکر بن عبداللہ بن قیس رضی اللہ عنہ نے انہیں اس حدیث کی خبر دی۔ ہم سے اسحاق نے بیان کیا،","کہا ہم سے حبان نے، انہوں نے کہا کہ ہم سے ہمام نے بیان کیا، کہا ہم سے ابوجمرہ نے بیان کیا ابوبکر بن عبداللہ رضی اللہ عنہ سے، انہوں نے اپنے والد سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے، پہلی حدیث کی طرح۔"],"id":["Telah menceritakan kepada kami [Hudbah bin Khalid] berkata, telah menceritakan kepada kami [Hammam] telah menceritakan kepadaku [Abu Jamrah] dari [Abu Bakar bin Abu Musa] dari [Bapaknya], bahwa Rasulullah shallallahu 'alaihi wasallam bersabda: \"Barangsiapa mengerjakan shalat pada dua waktu dingin, maka dia akan masuk surga.\" [Ibnu Raja'] berkata;","telah menceritakan kepada kami [Hammam] dari [Abu Jamrah] bahwa [Abu Bakar bin 'Abdullah bin Qais] telah mengabarkan kepadanya seperti ini.\" Dan telah menceritakan kepada kami [Ishaq] telah menceritakan kepada kami [Habban] telah menceritakan kepada kami [Hammam] telah menceritakan kepada kami [Abu Jamrah] dari [Abu Bakar bin 'Abdullah] dari [Bapaknya] dari Nabi shallallahu 'alaihi wasallam seperti ini"],"bn":["আবূ বাকর ইবনু আবূ মূসা (রাযি.) হতে তাঁর পিতার সূত্রে বর্ণিত, তিনি বলেন, আল্লাহর রাসূল সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ যে ব্যক্তি দুই শীতের (ফজর ও ‘আসরের) সালাত আদায় করবে, সে জান্নাতে প্রবেশ করবে। ইবনু রজা‘ (রহ.) বলেন, হাম্মাম (রহ.) আবূ জামরাহ (রহ.) হতে বর্ণনা করেন যে, আবূ বাকর ইবনু ‘আবদুল্লাহ্ ইবনু কায়স (রহ.) তাঁর নিকট এ হাদীস বর্ণনা করেছেন। (আধুনিক প্রকাশনীঃ ৫৪০,","ইসলামিক ফাউন্ডেশনঃ ৫৪৬) ‘আব্দুল্লাহ্ (রাযি.) সূত্রে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হতে এ রকমই বর্ণনা করেছেন। (মুসলিম ৫/৩৭, হাঃ ৬৩৫ , আহমাদ ১৬৭৩০) (আধুনিক প্রকাশনীঃ নাই, ইসলামিক ফাউন্ডেশনঃ)"],"ru":["Передают со слов Абу Мусы, да будет доволен им Аллах, о том, что Посланник Аллаха ﷺ сказал: «Вошёл в Рай тот,","кто совершал две молитвы в прохладное время»"]}},"h_sajid":{"src":"muslim 1083","w":["عَنْ","أَبِي","هُرَيْرَةَ،","أَنَّ","رَسُولَ","اللَّهِ","صلى","الله","عليه","وسلم","قَالَ","أَقْرَبُ","مَا","يَكُونُ","الْعَبْدُ","مِنْ","رَبِّهِ","وَهُوَ","سَاجِدٌ","فَأَكْثِرُوا","الدُّعَاءَ."],"p":[[0,12],[12,21]],"m":{"en":["Abu Huraira reported:The Messenger of Allah (ﷺ) said:","The nearest a servant comes to his Lord is when he is prostrating himself, so make supplication (in this state)"],"fr":["Rapporté par Abu Huraira رضي الله عنه : Le Messager d’Allah ﷺ a dit : « Le moment où le serviteur est le plus proche de son Seigneur,","c’est lorsqu’il est en prosternation, alors faites des invocations dans cet état. »"],"tr":["Bize Hârun b. Mâ'rııf ile Amr b. Sevvâd rivayet ettiler. Dediler ki: Bize Abdullah b. Vehb, Amr b. Harîs'den, o da Umâratü'bnü Gaziyye'den, o da Ebu Bekir'in azatlısı Sümey'den naklen rivayet etti. Sümey, Ebu Salih Zekvân'ı,","Ebu Hureyre'den rivayet ederken dinlemiş. Resulullah (Sallallahu Aleyhi ve Sellem) : «Kulun rabbine en yakın olduğu hâl secdede bulunduğu hâldir. Binaenaleyh sız (secdede) duayı çok edin!» buyurmuşlar. İzah 487 de"],"ur":["۔ ذکوان نے حضرت ابو ہریرہ ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے روایت کی کہ رسول اللہﷺ نے فرمایا :","’’بندہ اپنے رب کے سب سے زیادہ قریب اس حالت میں ہوتا ہے جب وہ سجدے میں ہوتا ہے ، لہٰذا اس میں کثرت سے دعا کرو ۔ ‘ ‘"],"id":["Dan telah menceritakan kepada kami [Harun bin Ma'ruf] dan [Amru bin Sawwad] keduanya berkata, telah menceritakan kepada kami [Abdullah bin Wahb] dari [Amru bin al-Harits] dari [Umarah bin Ghaziyyah] dari [Sumai,","maula Abu Bakar] bahwasanya dia mendengar [Abu Shalih Dzakwan] bercerita dari [Abu Hurairah ra] bahwa Rasulullah Shallallahu'alaihiwasallam bersabda, \"Keadaan seorang hamba yang paling dekat dari Rabbnya adalah ketika dia sujud, maka perbanyaklah doa"],"bn":["হারূন ইবনু মা’রূফ ও আমর ইবনু সাওওয়াদ (রহঃ) .....","আবূ হুরাইরাহ (রাযিঃ) হতে বর্ণিত। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়া সাল্লাম বলেনঃ বান্দার সিজদারত অবস্থায়ই তার প্রতিপালকের অনুগ্রহ লাভের সর্বোত্তম অবস্থা (বা মুহুর্ত)। অতএব তোমরা অধিক পরিমাণে দু'আ পড়ো। (ইসলামিক ফাউন্ডেশনঃ ৯৬৫, ইসলামিক সেন্টারঃ)"],"ru":["Сообщается со слов Абу Хурайры, что Посланник Аллаха ﷺ сказал: «Ближе всего к своему Господу раб оказывается тогда,","когда совершает земной поклон, так обращайтесь же к Нему с мольбами (в такие моменты) как можно чаще»"]}}};
